        ["|cRXP_WARN_==BE AWARE OF YOUR BREATH METER==|r"] = "|cRXP_WARN_==BEACHTET EURE ATEMLEISTE==|r",
        ["|cRXP_WARN_==PAY ATTENTION TO THE UPCOMING SECTION==|r"] = "|cRXP_WARN_==ACHTET AUF DEN FOLGENDEN BEREICH==|r",
        ["|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Healers|r can heal themselves or others. Pool Energy to stun their heals if you cannot kill them before they cast|r."] = "|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Healers|r können sich selbst oder andere heilen. Sammelt Energie, um ihre Heilungen zu unterbrechen, wenn ihr sie nicht töten könnt, bevor sie wirken|r.",
        ["|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Healers|r can heal themselves or others. Stun their heals if you can|r."] = "|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Healers|r können sich selbst oder andere heilen. Betäubt ihre Heilungen, falls ihr könnt|r.",
        ["|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Stormcallers|r cast|r |T136014:0|t[Lightning Cloud]. |cRXP_WARN_Move out of the cloud without pulling nearby enemies|r."] = "|cRXP_WARN_|cRXP_ENEMY_Al'Aketh Stormcallers|r wirkt|r |T136014:0|t[Blitzschlagwolke]. |cRXP_WARN_Bewegt euch aus der Wolke heraus, ohne nahegelegene Feinde zu provozieren|r.",
        ["|cRXP_WARN_3 waves will spawn from the water, each after killing the previous wave: Wave 1 has 3 level 12-13 |cRXP_ENEMY_Greymist Coastrunners|r, Wave 2 has 2 level 15-16 |cRXP_ENEMY_Greymist Warriors|r, and Wave 3 has a level 19 |cRXP_ENEMY_Murkdeep|r and a level 16-17 |cRXP_ENEMY_Greymist Hunter|r. You can move away from the Bonfire to avoid aggroing the next wave|r"] = "|cRXP_WARN_3 Wellen spawnen aus dem Wasser, jede nach dem Töten der vorherigen Welle: Welle 1 hat 3 Level 12-13 |cRXP_ENEMY_Küstenläufer der Grauflossen|r, Welle 2 hat 2 Level 15-16 |cRXP_ENEMY_Krieger der Grauflossen|r, und Welle 3 hat ein Level 19 |cRXP_ENEMY_Gurgelbacke|r und einen Level 16-17 |cRXP_ENEMY_Jäger der Grauflossen|r. Ihr könnt euch vom Freudenfeuer entfernen, um nicht mit der nächste Welle in den Kampf zu geraten.|r",
        ["|cRXP_WARN_Abandon Need for a Cure. This will remove the timer on the quest but you will still be able to do it|r"] = "|cRXP_WARN_Brecht die Quest Heilmittel benötigt ab. Dies entfernt den Timer der Quest, aber ihr könnt sie dennoch machen|r",
        ["|cRXP_WARN_Additionally, it's recommended you enable Enemy Nameplates (Default Key: V) as it allows you to see enemies behind some of the corners inside the tower|r"] = "|cRXP_WARN_Zusätzlich wird empfohlen, dass ihr Gegner-Namensplaketten (Standardtaste: V) aktiviert, da es euch erlaubt, Feinde hinter einigen der Ecken innerhalb des Turms zu sehen|r",
        ["|cRXP_WARN_Also check for any high DPS|r |T132317:0|t[Wand] |cRXP_WARN_upgrades that you can use now/soon|r"] = "|cRXP_WARN_Sucht auch nach hohem DPS|r |T132317:0|t[Zauberstab] |cRXP_WARN_-Verbesserungen, die ihr jetzt/bald nutzen könnt|r",
        ["|cRXP_WARN_Alternatively, check the Auction House for something better or cheaper|r"] = "|cRXP_WARN_Alternativ könnt ihr bald das Auktionshaus nach etwas Besserem oder Billigerem durchsuchen|r",
        ["|cRXP_WARN_Alternatively, run back to Deathknell|r"] = "|cRXP_WARN_Oder lauft zurück nach Todesend|r",
        ["|cRXP_WARN_As you continue to quest through The Barrens, try to find a 5-man group for \"Chol'aruk the Ravener\" at some point|r"] = "|cRXP_WARN_Während ihr durch Das Brachland quested, versucht eine 5-Mann-Gruppe für \"Chol'aruk der Verschlinger\" zu finden|r",
        ["|cRXP_WARN_Attach the|r |T134335:0|t[Shiny Bauble] |cRXP_WARN_to your|r |T132932:0|t[Fishing Pole]"] = "|cRXP_WARN_Befestige das|r |T134335:0|t[Glänzendes Schmuckstück] |cRXP_WARN_an eurer|r |T132932:0|t[Angelrute]",
        ["|cRXP_WARN_Attack mobs with it to learn|r |T132140:0|t[Claw (Rank 2)]"] = "|cRXP_WARN_Greift mobs mit ihm an um|r |T132140:0|t[Klaue (Rang 2)] zu lernen",
        ["|cRXP_WARN_Avoid fighting |cRXP_ENEMY_Sethir the Ancient|r. Let him walk passed you, then|r |T132320:0|t[Stealth] |cRXP_WARN_and|r |T133644:0|t[Pick Pocket] |cRXP_WARN_when you're behind him|r"] = "|cRXP_WARN_Vemeidet einen Kampf mit |cRXP_ENEMY_Sethir der Uralte|r. Lasst ihn an euch vorbeigehen, danach|r |T132320:0|t[Verstohlenheit] |cRXP_WARN_und|r |T133644:0|t[Taschendiebstahl] |cRXP_WARN_wenn ihr hinter ihm seid|r",
        ["|cRXP_WARN_Avoid fighting the Matriarchs as much as you can|r"] = "|cRXP_WARN_Vermeide es so weit wie möglich, gegen die Matriarchin zu kämpfen.|r",
        ["|cRXP_WARN_Avoid fighting them as much as you can|r"] = "|cRXP_WARN_Vermeide es so weit wie möglich, gegen sie zu kämpfen.|r",
        ["|cRXP_WARN_Avoid killing |cRXP_ENEMY_Deth'ryll Satyrs|r for now|r"] = "|cRXP_WARN_Vermeidet es die |cRXP_ENEMY_Satyr der Deth'ryll|r vorerst zu töten|r",
        ["|cRXP_WARN_Avoid killing |cRXP_ENEMY_Wild Grells|r and |cRXP_ENEMY_Vile Sprites|r en-route|r"] = "|cRXP_WARN_Vermeidet |cRXP_ENEMY_Wilder Grell|r und |cRXP_ENEMY_Übler Grimmling|r auf dem weg zu töten|r",
        ["|cRXP_WARN_Avoid running on the main road as much as possible. Enemies will only spawn if you're on the road|r"] = "|cRXP_WARN_Vermeidet es so weit wie möglich, auf der Hauptstraße zu laufen. Feinde spawnen nur, wenn ihr auf der Straße seid|r",
        ["|cRXP_WARN_Avoid the mobs in front of the burnt building. Loot it from the back, beside the chimney. Use the chimney to LoS the casts of |cRXP_ENEMY_Pillagers|r if required|r"] = "|cRXP_WARN_Vermeidet die Mobs vor dem brennenden Gebäude. Sammelt die Beute von hinten, neben dem Schornstein. Benutzt den Schornstein, um den Zaubern der |cRXP_ENEMY_Plünderer|r auszuweichen, falls nötig|r",
        ["|cRXP_WARN_Be aware of |cRXP_ENEMY_Benny Blanco|r. He hits hard|r"] = "|cRXP_WARN_Passt auf |cRXP_ENEMY_Benny Blanco|r auf. Er schlägt hart zu|r",
        ["|cRXP_WARN_Be aware of |cRXP_ENEMY_Greymist Oracles|r'|r |T136048:0|t[Lightning Bolt] |cRXP_WARN_damage and they can also heal with|r |T136052:0|t[Healing Wave]|r"] = "|cRXP_WARN_Seid vorsichtig vor den |cRXP_ENEMY_Orakel der Grauflossen|r'|r |T136048:0|t[Blitzschlag] |cRXP_WARN_Schaden und sie können auch mit|r |T136052:0|t[Welle der Heilung]|r heilen",
        ["|cRXP_WARN_Be aware of |cRXP_ENEMY_Greymist Oracles|r'|r |T136048:0|t[Lightning Bolt] |cRXP_WARN_damage, they can also heal with|r |T136052:0|t[Healing Wave]|r"] = "|cRXP_WARN_Achtet auf |cRXP_ENEMY_Orakel der Grauflossen|r'|r |T136048:0|t[Blitzschlag] |cRXP_WARN_Schaden, sie können auch mit|r |T136052:0|t[Welle der Heilung]|r heilen",
        ["|cRXP_WARN_Be aware of |cRXP_ENEMY_Moonstalker Matriarchs|r. They always attack with a |cRXP_ENEMY_Moonstalker Runt|r by their side|r"] = "|cRXP_WARN_Seid vorsichtig vor den |cRXP_ENEMY_Mondpirschermatriarchin|r. Sie greifen immer mit einem |cRXP_ENEMY_Mondpirscherwicht|r an ihrer Seite an|r",
        ["|cRXP_WARN_Be aware of |cRXP_ENEMY_Raging Reef Crawlers|r'|r |T132152:0|t[Thrash] |cRXP_WARN_ability. You can take 200 damage instantly from their melee hits|r"] = "|cRXP_WARN_Seid vorsichtig vor den |cRXP_ENEMY_Tobender Riffkriecher|r'|r |T132152:0|t[Hauen] |cRXP_WARN_Fähigkeit. Ihr könnt bis zu 200 Schaden auf einmal durch ihre Nahkampfangriffe nehmen|r",
        ["|cRXP_WARN_Be aware that they do not have dynamic respawns|r"] = "|cRXP_WARN_Beachte, das sie keinen dynamischen Respawn haben|r",
        ["|cRXP_WARN_Be aware the |cRXP_ENEMY_Blackrock Outrunners|r will cast |T132149:0|t[Net] on you|r"] = "Passt auf, die |cRXP_WARN_Kundschafter der Blackrock|cRXP_ENEMY_ wirken |T132149:0|t[Netz]|r auf euch|r",
        ["|cRXP_WARN_Be aware this area is a hyperspawn, meaning the |cRXP_ENEMY_Murlocs|r respawn quickly|r"] = "|cRXP_WARN_Passt auf, dieses Gebiet ist ein Hyperspawn, das heißt die |cRXP_ENEMY_Murlocs|r respawnen schnell nach|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Bael'dun Appraisers|r cast|r |T135929:0|t[Lesser Heal] |cRXP_WARN_(Ranged Cast: Heals themselves or a nearby mob below 50% health for about 75 health)|r"] = "|cRXP_WARN_Passt auf, denn |cRXP_ENEMY_Gutachter von Bael'dun|r wirken|r |T135929:0|t[Geringes Heilen] |cRXP_WARN_(Distanzzauber: heilt sich selbst oder einen nahegelegenen Gegner unter 50% Gesundheit für etwa 75 Gesundheit)|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Barak Kodobane|r's melee hits deal a LOT of damage and he is protected by a |cRXP_ENEMY_Kolkar Wrangler|r. They can net you and shoot at you from ranged distance|r"] = "|cRXP_WARN_Seid vorsichtig, da die Nahkampfangriffe von |cRXP_ENEMY_Barak Kodobann|r großen Schaden anrichten und er durch einen |cRXP_ENEMY_Zänker der Kolkar|r beschützt wird. Sie können euch fesseln und aus der Ferne auf euch schießen|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Ghost Howl|r is difficult due to being level 12|r"] = "|cRXP_WARN_Seid vorsichtig, da |cRXP_ENEMY_Geistheuler|r schwierig ist, weil er Stufe 12 ist|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Murloc Foragers|r will cast|r |T135915:0|t[Drink Minor Potion] |cRXP_WARN_which heals themselves for 61-68 health|r"] = "|cRXP_WARN_Passt auf, da |cRXP_ENEMY_Murlocfutterwühler|r wirken|r |T135915:0|t[Schwachen Trank trinken] |cRXP_WARN_welches sie um 61-68 Leben heilt|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Stonesplinter Scouts|r cast|r |T132222:0|t[Shoot] |cRXP_WARN_(Ranged Cast: Deals 14-20 damage)|r"] = "|cRXP_WARN_Seid vorsichtig denn die |cRXP_ENEMY_Späher der Splittersteintroggs|r wirkt|r |T132222:0|t[Schießen] |cRXP_WARN_(Distanzangriff: verursacht 14-20 Schaden)|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Stormscale Wave Riders|r cast|r |T135836:0|t[Aqua Jet] |cRXP_WARN_(Ranged Instant: Deals damage to nearby enemies and knocks them back) - make sure you're not in a position to get knocked off the upper level of the cave|r"] = "|cRXP_WARN_Seid vorsichtig, denn |cRXP_ENEMY_Wellenreiter der Sturmschuppen|r wirken|r |T135836:0|t[Wasserstrahl] |cRXP_WARN_(Sofortiger Distanzangriff: Macht Schaden und stößt euch zurück) - stellt sicher, dass ihr nicht von oben nach unten gestoßen werdet|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Twilight Disciples|r cast|r |T135953:0|t[Renew] |cRXP_WARN_and a 3 second|r |T135915:0|t[Heal]"] = "|cRXP_WARN_Passt auf, da die |cRXP_ENEMY_Zwielicht Jünger|r |r |T135953:0|t[Erneuerung] wirken |cRXP_WARN_und eine 3-Sekunden-|r |T135915:0|t[Heilung]",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Twilight Thugs|r can|r |T132343:0|t[Disarm] |cRXP_WARN_you for 6 seconds|r"] = "|cRXP_WARN_Passt auf, da die |cRXP_ENEMY_Twilight-Rohling|r euch für 6 Sek.|r |T132343:0|t[Entwaffnen] |cRXP_WARN_können|r",
        ["|cRXP_WARN_Be careful as |cRXP_ENEMY_Witchwing Slayers|r cast|r |T135358:0|t[Execute] |cRXP_WARN_(deals a LOT of damage when you're at <20% health), and |cRXP_ENEMY_Witchwing Ambushers|r are|r |T132320:0|t[Stealthed] |cRXP_WARN_and patrol around|r"] = "|cRXP_WARN_Passt auf, denn |cRXP_ENEMY_Töterin der Hexenschwingen|r wirken|r |T135358:0|t[Hinrichten] |cRXP_WARN_(verursacht SEHR VIEL Schaden, wenn ihr unter 20% Leben seid), und |cRXP_ENEMY_Wegelagerin der Hexenschwingen|r sind|r |T132320:0|t[Verstohlen] |cRXP_WARN_und patrouillieren umher|r",
        ["|cRXP_WARN_Be careful as he deals a LOT of damage. If your|r |T132320:0|t[Stealth] |cRXP_WARN_breaks, quickly use|r |T132307:0|t[Sprint] |cRXP_WARN_and run away|r"] = "|cRXP_WARN_Passt auf, da er sehr viel Schaden verursacht. Falls von Euch|r |T132320:0|t[Verstohlenheit] |cRXP_WARN_abbricht, nutzt schnell|r |T132307:0|t[Sprinten] |cRXP_WARN_und lauft weg|r",
        ["|cRXP_WARN_Be careful as he is difficult. You can skip this quest if you need|r"] = "|cRXP_WARN_Seid vorsichtig, er ist schwierig. Ihr könnt diese Quest überspringen, falls erforderlich|r",
        ["|cRXP_WARN_Be careful as he is VERY difficult. Feel free to skip this quest if you can't group up or solo him|r"] = "|cRXP_WARN_Seid vorsichtig, da er SEHR schwierig ist. Falls ihr ihn nicht in einer Gruppe oder solo schafft, könnt ihr diese Quest gerne überspringen|r",
        ["|cRXP_WARN_Be careful as he is VERY difficult. You can skip this quest if you need|r"] = "|cRXP_WARN_Seid vorsichtig, da er SEHR schwierig ist. Ihr könnt diese Quest überspringen, falls nötig|r",
        ["|cRXP_WARN_Be careful as he usually pulls with the |cRXP_ENEMY_Kobold Miner|r next to him|r"] = "|cRXP_WARN_Seid vorsichtig, da er normalerweise den |cRXP_ENEMY_Koboldminenarbeiter|r neben ihm mit in den Kampf zieht|r",
        ["|cRXP_WARN_Be careful as nearby |cRXP_ENEMY_Murlocs|r may aggro once you click|r |cRXP_PICK_Rolf's corpse|r"] = "|cRXP_WARN_Passt auf, da in der Nähe |cRXP_ENEMY_Murlocs|r angreifen könnten, wenn ihr|r |cRXP_PICK_Rolfs Leichnam|r anklickt",
        ["|cRXP_WARN_Be careful as the |cRXP_ENEMY_Malformed Defias Drone|r and |cRXP_ENEMY_Defias Drones|r can be at the entrance of the tower if you have to run out of it|r"] = "|cRXP_WARN_Passt auf, da |cRXP_ENEMY_Missgestaltete Drohne der Defias|r und |cRXP_ENEMY_Drohne der Defias|r am Eingang des Turms sein können, wenn ihr aus ihm laufen müsst|r",
        ["|cRXP_WARN_Be careful as the |cRXP_ENEMY_Oracles|r can heal, and have a 90 damage instant-cast shock spell every few seconds|r"] = "|cRXP_WARN_Passt auf, da die |cRXP_ENEMY_Orakels|r heilen können und alle paar Sek. einen Schockzauber mit 90 Schaden wirken|r",
        ["|cRXP_WARN_Be careful as the |cRXP_ENEMY_Thistle Cubs|r can cast|r |T132152:0|t[Ravage]|cRXP_WARN_, a melee instant attack which stuns you for 2 seconds|r"] = "|cRXP_WARN_Seid vorsichtig, denn die |cRXP_ENEMY_Distelbärjunges|r können|r |T132152:0|t[Verheeren]|cRXP_WARN_,wirken. Einen sofortigen Nahkampfangriff, der euch für 2 Sek. betäubt|r",
        ["|cRXP_WARN_Be careful as the|r |cRXP_ENEMY_Nightsabers|r |cRXP_WARN_and|r |cRXP_ENEMY_Strigid Owls|r |cRXP_WARN_move very fast!|r |cRXP_ENEMY_Strigid Owls|r |cRXP_WARN_will also social aggro other|r |cRXP_ENEMY_Owls|r |cRXP_WARN_if you run past them while in combat with one|r"] = "|cRXP_WARN_Seid vorsichtig, da die|r |cRXP_ENEMY_Nachtsäbler|r |cRXP_WARN_und|r |cRXP_ENEMY_Strigideulen|r |cRXP_WARN_sich sehr schnell bewegen!|r |cRXP_ENEMY_Strigideulen|r |cRXP_WARN_werden auch andere|r |cRXP_ENEMY_Strigideulen|r pullen |cRXP_WARN_falls ihr an ihnen vorbeilauft, während ihr mit einer|r im Kampf seid",
        ["|cRXP_WARN_Be careful as they can cast|r |T132155:0|t[Muscle Tear] |cRXP_WARN_an instant attack dealing 30-55 damage|r"] = "|cRXP_WARN_Seid vorsichtig, denn sie wirken|r |T132155:0|t[Muskelriss] |cRXP_WARN_ein Direktangriff, verursacht 30-55 Schaden|r",
        ["|cRXP_WARN_Be careful as they cast|r |T132152:0|t[Ravage] |cRXP_WARN_an instant attack dealing 20-40 damage and knocking you down for 2 seconds|r"] = "|cRXP_WARN_Passt auf, wenn sie|r |T132152:0|t[Verheeren] |cRXP_WARN_wirken, einen sofortigen Angriff, der 20-40 Schaden verursacht und euch für 2 Sek. zu Boden wirft|r",
        ["|cRXP_WARN_Be careful as they cast|r |T135914:0|t[Rabies] |cRXP_WARN_if you dont kill them fast enough (Instant Melee: Reduces ALL health regen by 50% for 10 Minutes)|r"] = "|cRXP_WARN_Passt auf, sie wirken|r |T135914:0|t[Tollwut] |cRXP_WARN_wenn ihr sie nicht schnell genug tötet (Sofort Nahkampf: Verringert ALLE Gesundheitsregeneration um 50% für 10 Minuten)|r",
        ["|cRXP_WARN_Be careful as they cast|r |T135914:0|t[Rabies] |cRXP_WARN_if you dont kill them fast enough (Instant Melee: Reduces all health regeneration by 50% for 10 minutes)|r"] = "|cRXP_WARN_Seid vorsichtig, denn sie wirken|r |T135914:0|t[Tollwut] |cRXP_WARN_wenn ihr sie nicht schnell genug tötet (Sofort Nahkampf: Reduziert alle Gesundheitsregeneration um 50% für 10 Minuten)|r",
        ["|cRXP_WARN_Be careful as they have 50% increased parry for 8 seconds after they do their defense stance animation|r"] = "|cRXP_WARN_Seid vorsichtig, da sie 8 Sek. lang eine um 50% erhöhte Parierchance nach ihrer Abwehrhaltungsanimation haben|r",
        ["|cRXP_WARN_Be careful as they|r |T132307:0|t[Flee] |cRXP_WARN_at <30% health|r"] = "|cRXP_WARN_Seid vorsichtig, denn sie|r |T132307:0|t[Fliehen] |cRXP_WARN_unter 30% Gesundheit|r",
        ["|cRXP_WARN_Be careful if you go straight through the field; you can easily die|r."] = "|cRXP_WARN_Seid vorsichtig, wenn ihr direkt durch das Feld geht; ihr könnt leicht sterben|r.",
        ["|cRXP_WARN_Be careful if|r |cRXP_ENEMY_Foreman Grills|r |cRXP_WARN_or|r |cRXP_ENEMY_Sludge Beast|r |cRXP_WARN_is up. They are strong level 19 rare mobs|r"] = "|cRXP_WARN_Seid vorsichtig, wenn|r |cRXP_ENEMY_Großknecht Grills|r |cRXP_WARN_oder|r |cRXP_ENEMY_Schlammbestie|r |cRXP_WARN_aktiv ist. Sie sind starke Stufe-19-Rares|r",
        ["|cRXP_WARN_Be careful if|r |cRXP_ENEMY_Kolkanis|r |cRXP_WARN_is up, he is a level 9 rare. You may have to use a |r |T134829:0|t[Minor Healing Potion] |cRXP_WARN_if you have it|r"] = "|cRXP_WARN_Seid vorsichtig, wenn|r |cRXP_ENEMY_Kolkanis|r |cRXP_WARN_aktiv ist, er ist ein seltener mob der Stufe 9. Ihr müsst möglicherweise einen|r |T134829:0|t[Schwachen Heiltrank] |cRXP_WARN_verwenden, wenn ihr ihn habt|r",
        ["|cRXP_WARN_Be careful if|r |cRXP_ENEMY_Watch Commander Zalaphil|r |cRXP_WARN_is up, as he is a level 9 rare. You may have to use a|r |T134829:0|t[Minor Healing Potion] |cRXP_WARN_if you have one|r"] = "|cRXP_WARN_Seid vorsichtig, wenn|r |cRXP_ENEMY_Wachkommandant Zalaphil|r |cRXP_WARN_aktiv ist, da er ein seltener mob der Stufe 9 ist. Ihr müsst möglicherweise einen|r |T134829:0|t[Schwachen Heiltrank] |cRXP_WARN_verwenden, wenn ihr einen habt|r",
        ["|cRXP_WARN_Be careful near the waypoint; two Gryphons patrol the area|r."] = "|cRXP_WARN_Seid vorsichtig in der Nähe des Wegpunkts; zwei Greifen patrouillieren die Gegend|r.",
        ["|cRXP_WARN_Be careful of high level mobs en route|r"] = "|cRXP_WARN_Achtet unterwegs auf hochstufige mobs|r",
        ["|cRXP_WARN_Be careful of high level|r |cRXP_ENEMY_Young Threshadon|r"] = "|cRXP_WARN_Vorsicht vor hochstufigen|r |cRXP_ENEMY_Junger Dreschadons|r",
        ["|cRXP_WARN_Be careful of the enemies near the edge|r."] = "|cRXP_WARN_Seid vorsichtig vor den Feinden nahe der Kante|r.",
        ["|cRXP_WARN_Be careful of the higher level |cRXP_ENEMY_Wendigos|r deeper in the cave|r"] = "|cRXP_WARN_Vorsicht vor stärkeren |cRXP_ENEMY_Wendigos|r tiefer in der Höhle|r",
        ["|cRXP_WARN_Be careful of the two group of 2 |cRXP_ENEMY_Raging Moonkins|r west of the |cRXP_PICK_Mysterious Red Crystal|r as the duos closest to each other are leashed together|r"] = "|cRXP_WARN_Passt auf die beiden 2er-Gruppen |cRXP_ENEMY_Tobender Moonkin|r westlich des |cRXP_PICK_Geheimnisvoller Roter Kristall|r die beiden aneinander liegenden duos werden zusammen gepullt|r",
        ["|cRXP_WARN_Be careful of|r |cRXP_ENEMY_Krethis Shadowspinner|r |cRXP_WARN_as it's difficult but doable. She has a 130 damage shield on a 15s cooldown, and 110 damage instant shock ability|r"] = "|cRXP_WARN_Seid vorsichtig vor|r |cRXP_ENEMY_Krethis Shadowspinner|r |cRXP_WARN_- es ist schwierig, aber machbar. Sie hat einen Schutzschild mit 130 Schaden (15s Cooldown) und eine sofortige Schockfähigkeit mit 110 Schaden|r",
        ["|cRXP_WARN_Be careful of|r |cRXP_ENEMY_Krethis Shadowspinner|r |cRXP_WARN_as it's impossibly difficult to kill her!|r"] = "|cRXP_WARN_Seid vorsichtig vor|r |cRXP_ENEMY_Krethis Shadowspinner|r |cRXP_WARN_da sie extrem schwierig zu töten ist!|r",
        ["|cRXP_WARN_Be careful of|r |cRXP_ENEMY_Sunscale Scytheclaws|r |cRXP_WARN_in the area. They are up to level 18 and can|r |T132152:0|t[Thrash]"] = "|cRXP_WARN_Passt auf|r |cRXP_ENEMY_Bluthornsensenklaue|r |cRXP_WARN_in der Gegend auf. Sie sind bis Stufe 18 und können|r |T132152:0|t[Hauen]",
        ["|cRXP_WARN_Be careful to not fall of the mountain, the path is very narrow. You could die if you fall|r"] = "|cRXP_WARN_Seid vorsichtig und fallt nicht vom Berg. Der Weg ist sehr schmal. Ihr könntet sterben, wenn ihr fallt|r",
        ["|cRXP_WARN_Be careful with your money, as you need to save 31s 85c for Stormwind and Ironforge later|r"] = "|cRXP_WARN_Seid vorsichtig mit eurem Geld, da ihr 31s 85c für Sturmwind und Eisenschmiede später sparen müsst|r",
        ["|cRXP_WARN_Be careful with your money, as you should try to save 32s 8c for Stormwind later|r"] = "|cRXP_WARN_Seid vorsichtig mit eurem Geld, da ihr versuchen solltet, 32s 8c später für Sturmwind zu sparen|r",
        ["|cRXP_WARN_Be careful, these mobs cast|r |T135846:0|t[Frostbolt]|r"] = "|cRXP_WARN_Seid vorsichtig die mobs wirken|r |T135846:0|t[Frostblitz]|r",
        ["|cRXP_WARN_Be careful; it will attack you when dismissed|r."] = "|cRXP_WARN_Seid vorsichtig; es wird euch angreifen, wenn es entlassen wird|r.",
        ["|cRXP_WARN_Be careful: |cRXP_ENEMY_Al'Aketh Assassins|r use|r |T132357:0|t[Slam] |cRXP_WARN_to knock you down and|r |T136189:0|t[Sinister Strike] |cRXP_WARN_alongside their melee attacks|r."] = "|cRXP_WARN_Vorsicht: |cRXP_ENEMY_Al'Aketh Assassins|r benutzen|r |T132357:0|t[Zerschmettern] |cRXP_WARN_um euch zu Boden zu werfen und|r |T136189:0|t[Finsterer Stoß] |cRXP_WARN_zusammen mit ihren Nahkampfangriffen|r.",
        ["|cRXP_WARN_Be careful: |cRXP_ENEMY_Living Lightning|r use an ability similar to Thunder Clap that deals three times their melee damage in a single hit|r."] = "|cRXP_WARN_Vorsicht: |cRXP_ENEMY_Living Blitzschlag|r benutzen eine Fähigkeit ähnlich wie Donnerknall, die dreifachen Nahkampfschaden in einem Treffer verursacht|r.",
        ["|cRXP_WARN_Be careful: |cRXP_ENEMY_Ornery Galestriders|r use |T132156:0|t[Dust Cloud] to reduce your chance to hit."] = "Vorsicht: |cRXP_WARN_Ornery Galestriders|cRXP_ENEMY_ nutzen |T132156:0|t[Staubwolke], um die Trefferschance von Euch zu senken|r.",
        ["|cRXP_WARN_BE CAREFUL: Stick to the main road and avoid any close mobs en-route|r"] = "|cRXP_WARN_SEID VORSICHTIG: Bleibt auf der Hauptstraße und weicht allen nahegelegenen Gegnern aus|r",
        ["|cRXP_WARN_Be careful! |cRXP_ENEMY_Lunaclaw|r casts|r |T132152:0|t[Thrash] |cRXP_WARN_(Charges 2 extra attacks every 10 seconds)|r"] = "|cRXP_WARN_Be careful! |cRXP_ENEMY_Mondklaue|r wirkt|r |T132152:0|t[Hauen] |cRXP_WARN_(Aufladungen 2 extra Angriffe alle 10 Sek.)|r",
        ["|cRXP_WARN_Be careful! He is strong and is guarded by at least two|r |cRXP_ENEMY_Kolkar|r |cRXP_WARN_mobs|r"] = "|cRXP_WARN_Seid vorsichtig! Er ist ein starker Elite und wird von mindestens zwei|r |cRXP_ENEMY_Kolkar|r |cRXP_WARN_mobs|r beschützt",
        ["|cRXP_WARN_Be careful! There may be a|r |cRXP_ENEMY_Son of Arugal|r |cRXP_WARN_in the area! This is a level 25 elite, steer clear from him!|r"] = "|cRXP_WARN_Passt auf! Es könnte ein|r |cRXP_ENEMY_Sohn des Arugal|r |cRXP_WARN_im Gebiet sein! Das ist ein Elitegegner der Stufe 25. Haltet euch von ihn fern!|r",
        ["|cRXP_WARN_Be careful! These mobs cast|r |T135846:0|t[Frostbolt] |cRXP_WARN_and flee at low health. Pull them back and kill them one by one until you can safely click on the crate|r"] = "|cRXP_WARN_Passt auf! Diese Mobs wirken|r |T135846:0|t[Frostblitz] |cRXP_WARN_und fliehen bei niedriger Gesundheit. Zieht sie zurück und tötet sie einzeln, bis ihr sicher auf die Kiste klicken könnt.|r",
        ["|cRXP_WARN_Be careful! These mobs hit hard. |cRXP_ENEMY_Dark Enforcers::275437|r also have an instant cast 50-70 damage ability|r"] = "|cRXP_WARN_Seid vorsichtig! Diese Mobs schlagen hart zu. |cRXP_ENEMY_Dark Enforcers::275437|r haben auch eine sofort wirkende Fähigkeit mit 50-70 Schaden|r",
        ["|cRXP_WARN_Be careful! These mobs hit hard. |cRXP_ENEMY_Dark Enforcers|r also have an instant cast 50-70 damage ability|r"] = "|cRXP_WARN_Passt auf! Diese Mobs schlagen hart zu. |cRXP_ENEMY_Dunkler Vollstrecker|r haben auch eine sofort wirkende Fähigkeit mit 50-70 Schaden.|r",
        ["|cRXP_WARN_Be careful! Two mobs will spawn after you shut off the Valve|r"] = "|cRXP_WARN_Vorsicht! Zwei Mobs werden spawn, nachdem ihr das Ventil ausgeschaltet habt|r",
        ["|cRXP_WARN_Be careful!. At the top of the tower you can easily aggro 3 |cRXP_ENEMY_Scarlet Warriors|r at the same time|r"] = "|cRXP_WARN_Seid vorsichtig! Oben auf dem Turm könnt ihr leicht 3 |cRXP_ENEMY_Scharlachroter Krieger|r gleichzeitig pullen|r",
        ["|cRXP_WARN_Be careful!|r |cRXP_ENEMY_Moonrage Darksouls|r |cRXP_WARN_enrage when they are below 25% health. Kill them quickly when they are low|r"] = "|cRXP_WARN_Passt auf!|r |cRXP_ENEMY_Moonrage-Dunkelseele|r |cRXP_WARN_werden rasend, wenn ihre Gesundheit unter 25% fällt. Tötet sie schnell, wenn sie wenig Leben haben.|r",
        ["|cRXP_WARN_Be careful. Kill the patrolling|r |cRXP_ENEMY_Burning Blade Fanatic|r |cRXP_WARN_and the|r |cRXP_ENEMY_Lightning Hides|r |cRXP_WARN_in the back before you pull him|r"] = "|cRXP_WARN_Passt auf. Tötet die patrouillierenden|r |cRXP_ENEMY_Fanatiker der Burning Blade|r |cRXP_WARN_und die|r |cRXP_ENEMY_Blitzechse|r |cRXP_WARN_hinten, bevor ihr ihn angreift|r",
        ["|cRXP_WARN_Be careful|r |cRXP_ENEMY_Foreststrider Fledglings|r |T132307:0|t[Flee] |cRXP_WARN_at <30% health|r"] = "|cRXP_WARN_Seid vorsichtig|r |cRXP_ENEMY_Waldschreiterjunges|r |T132307:0|t[Fliehen] |cRXP_WARN_bei unter 30% Gesundheit|r",
        ["|cRXP_WARN_Be prepared to run if you don't kill the |cRXP_ENEMY_Defias Tower Sentries|r on the 2nd floor. They will most likely aggro you permanently (but not attack you) when you are on top of the bookshelf as it is an evade spot|r"] = "|cRXP_WARN_Seid bereit zu laufen, wenn ihr nicht die |cRXP_ENEMY_Turmwachposten der Defias|r im 2. Stockwerk tötet. Sie werden euch wahrscheinlich permanent angreifen (aber nicht treffen), wenn ihr auf dem Bücherregal steht, da es ein Ausweich-Platz ist|r",
        ["|cRXP_WARN_Be ready to use a|r |T134830:0|t[Lesser Healing Potion]"] = "|cRXP_WARN_Seid bereit, einen|r |T134830:0|t[Geringer Heiltrank] zu benutzen",
        ["|cRXP_WARN_Be sure |T136205:0|t[Evasion] |cRXP_WARN_is ready. If you're struggling, you can use the Fence with Throwing Weapons to abuse pathing and buy time|r"] = "|cRXP_WARN_Stellt sicher, dass |T136205:0|t[Entrinnen] |cRXP_WARN_bereit ist. Wenn ihr Schwierigkeiten habt, könnt ihr den Zaun mit Wurfwaffen nutzen, um das pathing auszunutzen und Zeit zu gewinnen|r",
        ["|cRXP_WARN_Bind your|r |T133728:0|t[Faintly Glowing Skull] |cRXP_WARN_and|r |T134712:0|t[Really Sticky Glue]|cRXP_WARN_. Save them for emergency situations|r"] = "|cRXP_WARN_Bindet euren|r |T133728:0|t[Schwach leuchtender Schädel] |cRXP_WARN_und|r |T134712:0|t[Echt klebriger Leim]|cRXP_WARN_. Behaltet sie für Notfälle|r",
        ["|cRXP_WARN_Buy a|r |T133024:0|t[Bronze Tube]"] = "|cRXP_WARN_Kaufe eine|r |T133024:0|t[Bronzeröhre]",
        ["|cRXP_WARN_Buy a|r |T133053:0|t[Wooden Mallet] |cRXP_BUY_from her if you can afford it|r"] = "|cRXP_WARN_Kauft einen|r |T133053:0|t[Hölzerner Schlaghammer] |cRXP_BUY_von ihr, falls ihr es euch leisten könnt|r",
        ["|cRXP_WARN_Buy a|r |T133634:0|t[Small Brown Pouch] |cRXP_WARN_if needed|r"] = "|cRXP_WARN_Kauft einen|r |T133634:0|t[Kleiner brauner Beutel] |cRXP_WARN_falls benötigt|r",
        ["|cRXP_WARN_Buy a|r |T135139:0|t[Burning Wand] |cRXP_WARN_if it's an upgrade|r"] = "|cRXP_WARN_Kauft einen|r |T135139:0|t[Brennender Zauberstab] |cRXP_WARN_Falls es ein upgrade ist|r",
        ["|cRXP_WARN_Buy a|r |T135280:0|t[Dacian Falx] |cRXP_WARN_if you have enough money. Equip it at 21|r"] = "|cRXP_WARN_Kauft eine|r |T135280:0|t[Dakische Sichel] |cRXP_WARN_wenn ihr genug Geld habt. Rüstet sie aus, wenn ihr Stufe 21 erreicht|r",
        ["|cRXP_WARN_Buy a|r |T135324:0|t[Longsword] |cRXP_WARN_and equip it at 21|r"] = "|cRXP_WARN_Kauft ein|r |T135324:0|t[Langschwert] |cRXP_WARN_und rüstet es auf Stufe 21 aus|r",
        ["|cRXP_WARN_Buy a|r |T135468:0|t[Smoldering Wand] |cRXP_WARN_from her|r"] = "|cRXP_WARN_Kauft einen|r |T135468:0|t[Glimmender Zauberstab] |cRXP_WARN_von ihr|r",
        ["|cRXP_WARN_Buy a|r |T135468:0|t[Smoldering Wand] |cRXP_WARN_from him|r"] = "|cRXP_WARN_Kauft einen|r |T135468:0|t[Glimmender Zauberstab] |cRXP_WARN_von ihm|r",
        ["|cRXP_WARN_Buy something from the Auction House if there's something cheaper/better|r"] = "|cRXP_WARN_Kauft etwas aus dem Auktionshaus, wenn es etwas günstigeres oder besseres gibt|r",
        ["|cRXP_WARN_Buy the following if you can afford it:|r"] = "|cRXP_WARN_Kauft Folgendes, wenn ihr es euch leisten könnt:|r",
        ["|cRXP_WARN_Buy the|r |T135641:0|t[Balanced Throwing Daggers]"] = "|cRXP_WARN_Kauft|r |T135641:0|t[Ausbalancierter Wurfdolch]",
        ["|cRXP_WARN_Cast |r|T135758:0|t[Teleport: Moonglade]"] = "|cRXP_WARN_Wirkt |r|T135758:0|t[Teleportieren: Mondlichtung]",
        ["|cRXP_WARN_Cast |T136225:0|t[Stoneform] to remove the |T136230:0|t[Touch of Zanzil] debuff|r"] = "|cRXP_WARN_Wirkt |T136225:0|t[Steingestalt], um |T136230:0|t[Berührung von Zanzil]-Debuff zu entfernen|r",
        ["|cRXP_WARN_Cast|r |T132164:0|t[Tame Beast] |cRXP_WARN_on a |cRXP_ENEMY_Strigid Hunter|r to tame it|r"] = "|cRXP_WARN_Wirkt|r |T132164:0|t[Wildtier zähmen] |cRXP_WARN_auf einen |cRXP_ENEMY_Strigidjäger|r um ihn zu Zähmen|r",
        ["|cRXP_WARN_Cast|r |T132164:0|t[Tame Beast] |cRXP_WARN_on a |cRXP_ENEMY_Thistle Bear|r to tame it|r"] = "|cRXP_WARN_Wirkt|r |T132164:0|t[Wildtier zähmen] |cRXP_WARN_auf einen |cRXP_ENEMY_Distelbär|r um es zu zähmen|r",
        ["|cRXP_WARN_Cast|r |T132164:0|t[Tame Beast] |cRXP_WARN_on a |cRXP_ENEMY_Windsong Crawler::254588|r to tame it|r"] = "|cRXP_WARN_Wirkt|r |T132164:0|t[Wildtier zähmen] |cRXP_WARN_auf einem |cRXP_ENEMY_Windsong Kriecher::254588|r, um ihn zu zähmen|r",
        ["|cRXP_WARN_Cast|r |T133644:0|t[Pick Pocket] on |cRXP_ENEMY_Sethir the Ancient|r"] = "|cRXP_WARN_Wirkt|r |T133644:0|t[Taschendiebstahl] auf |cRXP_ENEMY_Sethir der Uralte|r",
        ["|cRXP_WARN_Cast|r |T135920:0|t[Holy Light] |cRXP_WARN_on|r |cRXP_FRIENDLY_Injured Deathguards|r"] = "|cRXP_WARN_Wirkt|r |T135920:0|t[Heiliges Licht] |cRXP_WARN_auf|r |cRXP_FRIENDLY_Verletzte Todeswachen|r",
        ["|cRXP_WARN_Cast|r |T135929:0|t[Lesser Heal (Rank 2)] |cRXP_WARN_and|r |T135987:0|t[Power Word: Fortitude] |cRXP_WARN_on|r |cRXP_FRIENDLY_Guard Roberts|r"] = "|cRXP_WARN_Wirkt|r |T135929:0|t[Geringes Heilen (Rang 2)] |cRXP_WARN_und|r |T135987:0|t[Machtwort: Seelenstärke] |cRXP_WARN_auf|r |cRXP_FRIENDLY_Wache Roberts|r",
        ["|cRXP_WARN_Cast|r |T135929:0|t[Lesser Heal (Rank 2)] |cRXP_WARN_and|r |T135987:0|t[Power Word: Fortitude] |cRXP_WARN_on|r |cRXP_FRIENDLY_Sentinel Shaya|r"] = "|cRXP_WARN_Wirkt|r |T135929:0|t[Geringes Heilen (Rang 2)] |cRXP_WARN_und|r |T135987:0|t[Machtwort: Seelenstärke] |cRXP_WARN_auf|r |cRXP_FRIENDLY_Schildwache Shaya|r",
        ["|cRXP_WARN_Cast|r |T135929:0|t[Lesser Heal] (Rank 2) |cRXP_WARN_and then|r |T135987:0|t[Power Word: Fortitude] |cRXP_WARN_on |cRXP_FRIENDLY_Mountaineer Dolf|r outside|r"] = "|cRXP_WARN_Wirkt|r |T135929:0|t[Geringes Heilen] (Rang 2) |cRXP_WARN_und dann|r |T135987:0|t[Machtwort: Seelenstärke] |cRXP_WARN_auf |cRXP_FRIENDLY_Gebirgsjäger Dolf|r draußen|r",
        ["|cRXP_WARN_Cast|r |T135953:0|t[Renew] |cRXP_WARN_and|r |T135940:0|t[Power Word: Shield] |cRXP_WARN_then get full mana. Pull the 2 |cRXP_ENEMY_Murlocs|r in front of the huts, move away, then nuke one. Run away when you kill one, then kill the other|r"] = "|cRXP_WARN_Wirkt|r |T135953:0|t[Erneuerung] |cRXP_WARN_und|r |T135940:0|t[Machtwort: Schild] |cRXP_WARN_dann füllt eure Mana. Zieht die 2|cRXP_ENEMY_ Murlocs|r vor den Hütten, bewegt euch weg, dann tötet einen. Lauft weg wenn ihr einen tötet, dann tötet den anderen|r",
        ["|cRXP_WARN_Cast|r |T136006:0|t[|cRXP_LOOT_Wrath|r] |cRXP_WARN_until out of mana then switch back to|r |T135158:0|t[|cRXP_LOOT_Melee|r] |cRXP_WARN_until you are back to full and repeat|r"] = "|cRXP_WARN_Wirkt|r |T136006:0|t[|cRXP_LOOT_Zorn|r] |cRXP_WARN_bis euer Mana leer ist, dann wechselt in den|r |T135158:0|t[|cRXP_LOOT_Nahkampf|r] |cRXP_WARN_bis ihr wieder voll seid und wiederholt es|r",
        ["|cRXP_WARN_Cast|r |T136025:0|t[Find Minerals] |cRXP_WARN_and mine any Copper Vein you find for|r |T135232:0|t|cRXP_LOOT_[Rough Stones]|r|cRXP_WARN_. Make|r |T135248:0|t[Sharpening Stones] |cRXP_WARN_from them|r"] = "|cRXP_WARN_Wirkt|r |T136025:0|t[Mineraliensuche] |cRXP_WARN_und baue jede Kupferader ab, die du findest, für|r |T135232:0|t|cRXP_LOOT_[Rauer Stein]|r|cRXP_WARN_. Stellt|r |T135248:0|t[Wetzsteine] |cRXP_WARN_daraus her|r",
        ["|cRXP_WARN_Cast|r |T136071:0|t[Polymorph] |cRXP_WARN_on|r |cRXP_ENEMY_Old Icebeard|r"] = "|cRXP_WARN_Wirkt|r |T136071:0|t[Verwandlung] |cRXP_WARN_auf|r |cRXP_ENEMY_Eisbart der Alte|r",
        ["|cRXP_WARN_Cast|r |T136095:0|t[Dismiss Pet] |cRXP_WARN_and then jump into Thunder Ridge|r"] = "|cRXP_WARN_Wirkt|r |T136095:0|t[Tier freigeben] |cRXP_WARN_und springt dann in Donnergrat|r",
        ["|cRXP_WARN_cast|r |T136100:0|t[Entangling Roots] |cRXP_WARN_and use the swatter on the same Flutterfly for extra dust|r."] = "|cRXP_WARN_Wirkt|r |T136100:0|t[Wucherwurzeln] |cRXP_WARN_und benutzt die Fliegenklatsche auf dem gleichen Flutterfly für zusätzlichen Staub|r.",
        ["|cRXP_WARN_Cast|r |T136126:0|t[Life Tap] |cRXP_WARN_repeatedly until you have <10% health then jump down the ledge (NOT into the water) next to the flight master and die intentionally|r"] = "|cRXP_WARN_Wirkt|r |T136126:0|t[Aderlass] |cRXP_WARN_wiederholt, bis ihr unter 10% Gesundheit habt, dann springt neben dem Flugmeister von der Klippe (NICHT ins Wasser) und sterbt absichtlich|r",
        ["|cRXP_WARN_Cast|r |T136126:0|t[Life Tap] |cRXP_WARN_repeatedly until you have <10% health while on the way to|r |cRXP_FRIENDLY_Dungar Longdrink|r"] = "|cRXP_WARN_Wirkt|r |T136126:0|t[Aderlass] |cRXP_WARN_wiederholt bis ihr 10 Prozent Gesundheit habt, während ihr auf dem Weg zu|r |cRXP_FRIENDLY_Dungar Longdrink|r",
        ["|cRXP_WARN_Cast|r |T136183:0|t[Fear] |cRXP_WARN_on |cRXP_ENEMY_Hogger|r continously and use your regular DoTs to kill him|r"] = "|cRXP_WARN_Wirkt |T136183:0|t[Furcht] |cRXP_WARN_auf |cRXP_ENEMY_Hogger|r kontinuierlich und benutzt von Euch reguläre DoTs, um ihn zu töten|r",
        ["|cRXP_WARN_Cast|r |T136183:0|t[Fear] |cRXP_WARN_on |cRXP_ENEMY_Morgan the Collector|r continously|r"] = "|cRXP_WARN_Wirkt|r |T136183:0|t[Furcht] kontinuierlich auf|cRXP_WARN_auf |cRXP_ENEMY_Morgan der Sammler|r|r",
        ["|cRXP_WARN_Cast|r |T136183:0|t[Fear] |cRXP_WARN_on|r |cRXP_ENEMY_Old Icebeard|r"] = "|cRXP_WARN_Wirkt|r |T136183:0|t[Furcht] |cRXP_WARN_auf|r |cRXP_ENEMY_Eisbart der Alte|r",
        ["|cRXP_WARN_Cast|r |T136221:0|t[Summon Voidwalker] |cRXP_WARN_and|r |T135230:0|t[Create Healthstone] |cRXP_WARN_while waiting for the Tram to Ironforge if needed|r"] = "|cRXP_WARN_Wirkt|r |T136221:0|t[Leerwandler beschwören] |cRXP_WARN_und|r |T135230:0|t[Gesundheitsstein herstellen] |cRXP_WARN_während ihr auf die Tiefenbahn nach Eisenschmiede wartet falls nötig|r",
        ["|cRXP_WARN_Check \"Enable Interact Key\" and bind the \"Interact with Target\" option to a key|r"] = "|cRXP_WARN_Überprüft \"Aktiviere Interaktionstaste\" und bindet die \"Interagieren mit Ziel\" Option auf eine Taste|r",
        ["|cRXP_WARN_Check if|r |cRXP_FRIENDLY_Lizzarik|r |cRXP_WARN_is in the Crossroads. He sells potions and|r |T133476:0|t[|cRXP_FRIENDLY_Heavy Spiked Mace|r] |cRXP_WARN_which is a limited supply item|r"] = "|cRXP_WARN_Überprüft, ob|r |cRXP_FRIENDLY_Lizzarik|r |cRXP_WARN_im Wegekreuz ist. Er verkauft Tränke und|r |T133476:0|t[|cRXP_FRIENDLY_Schwerer Stachelkolben|r] |cRXP_WARN_, welcher ein begrenzter Gegenstand ist|r",
        ["|cRXP_WARN_Choose between Mining, Herbalism, or Skinning|r."] = "|cRXP_WARN_Choose between Bergbau, Kräuterkunde, oder Kürschnerei|r.",
        ["|cRXP_WARN_Choose the|r |T135641:0|t[Craftsman's Dagger]|cRXP_WARN_. Save it for later|r"] = "|cRXP_WARN_Wählt den|r |T135641:0|t[Handwerkerdolch] |cRXP_WARN_. Sichert ihn für später|r",
        ["|cRXP_WARN_Choose the|r |T135641:0|t[Curvewood Dagger] |cRXP_WARN_as you should try to save a|r |T135641:0|t[Dagger] |cRXP_WARN_for your|r |T132290:0|t[Poisons] |cRXP_WARN_quest later|r"] = "|cRXP_WARN_Wählt den|r |T135641:0|t[Krummholzdolch] |cRXP_WARN_aus, da ihr versuchen solltet, einen|r |T135641:0|t[Dolch] |cRXP_WARN_für eure|r |T132290:0|t[Gifte] |cRXP_WARN_Quest später zu haben|r",
        ["|cRXP_WARN_Clear an exit path if needed so you can reset them along with the |cRXP_ENEMY_Succubus|r if needed. You may skip this and do it at level 23 if you wish|r"] = "|cRXP_WARN_Macht einen Fluchtweg frei, damit ihr die|cRXP_ENEMY_Sukkubus|r zusammen mit ihm zurücksetzen könnt, falls nötig. Ihr könnt diesen Schritt überspringen und ihn auf Stufe 23 tun, falls gewünscht|r",
        ["|cRXP_WARN_Clear the furbolgs near the cave before talking to him|r"] = "|cRXP_WARN_Tötet die Furbolgs in der Nähe der Höhle, bevor ihr mit ihm sprecht|r",
        ["|cRXP_WARN_Click here for more info about pet training|r"] = "|cRXP_WARN_Hier Klicken für mehr Infos bezüglich Pet Training|r",
        ["|cRXP_WARN_Click here for video reference on \"Split pulling\". It is a short video and invaluable to learn|r"] = "|cRXP_WARN_Klickt hier für eine Videoreferenz zu \"Split-Pulling\". Es ist ein kurzes Video und äußerst lehrreich|r",
        ["|cRXP_WARN_Click here for video reference on \"Split pulling\"|r"] = "|cRXP_WARN_Klickt hier für eine Videoreferenz zu \"Teil pulling\"|r",
        ["|cRXP_WARN_CLICK HERE If you're struggling|r"] = "|cRXP_WARN_KLICKT HIER, wenn ihr Schwierigkeiten habt|r",
        ["|cRXP_WARN_Click on the skull on the ground. This will summon|r |cRXP_ENEMY_Ulag.|r |cRXP_WARN_Kill him|r"] = "|cRXP_WARN_Klickt auf den Schädel auf dem Boden. Dies wird|r |cRXP_ENEMY_Ulag.|r beschwören |cRXP_WARN_Tötet ihn|r",
        ["|cRXP_WARN_Click the |cRXP_PICK_Scrying Bowl|r on the ground|r"] = "|cRXP_WARN_Klickt die |cRXP_PICK_Wahrsageschale|r auf dem Boden|r",
        ["|cRXP_WARN_Click the|r |cRXP_WARN_Mausoleum Trigger|r |cRXP_WARN_on the ground. This will summon|r |cRXP_ENEMY_Ulag.|r |cRXP_WARN_Kill him|r"] = "|cRXP_WARN_Klickt auf den|r |cRXP_WARN_Mausoleum Auslöser|r |cRXP_WARN_am Boden. Dies wird|r |cRXP_ENEMY_Ulag.|r |cRXP_WARN_beschwören. Tötet ihn|r",
        ["|cRXP_WARN_Collect 5 |T134187:0|t[Earthroot] via |T136065:0|t[Herbalism] and rarely |cRXP_PICK_Battered Chests|r for a future class quest|r"] = "Sammelt 5 |T134187:0|t[Erdwurzel] über |cRXP_WARN_über |T136065:0|t[Kräuterkunde] und selten in |cRXP_PICK_Ramponierte Truhe|r für eine zukünftige Klassenquest|r",
        ["|cRXP_WARN_Complete the 1-9 Skyborne guide before continuing. This guide requires the quests from Part 1|r."] = "|cRXP_WARN_Schließt den 1-9-Skyborne-Leitfaden ab, bevor ihr fortfahrt. Dieser Leitfaden erfordert die Quests aus Teil 1|r.",
        ["|cRXP_WARN_Completing this will give 4100xp. The entrance to the cave where he is located is marked on your map (|cRXP_ENEMY_Razormane|r area)|r"] = "|cRXP_WARN_Dies gibt 4100 XP. Der Eingang zur Höhle, in der er sich aufhält, ist auf der Karte von Euch markiert (|cRXP_ENEMY_Klingenmähnen|r Gebiet)|r",
        ["|cRXP_WARN_Conjure water while waiting|r"] = "|cRXP_WARN_Beschwört Wasser, während ihr wartet|r",
        ["|cRXP_WARN_Consider skipping some of the level 17|r |cRXP_ENEMY_Reef Crawlers|r |cRXP_WARN_if you get decent drops.|r |cRXP_WARN_You don't have to complete this quest now|r"] = "|cRXP_WARN_Denkt daran, einige der Stufe 17|r |cRXP_ENEMY_Riffkriecher|r |cRXP_WARN_zu überspringen, wenn ihr gute drops bekommt.|r |cRXP_WARN_Ihr müsst diese Quest nicht jetzt abschließen|r",
        ["|cRXP_WARN_Continue leveling your|r |T133971:0|t[Cooking] |cRXP_WARN_until you run out of|r |T132832:0|t[Small Eggs]"] = "Macht weiter, um eure |T133971:0|t[Kochkunst] |cRXP_WARN_zu leveln, bis euch die |r |T132832:0|t[kleinen Eier] |cRXP_WARN_ausgehen|r",
        ["|cRXP_WARN_Continue up the trail|r"] = "|cRXP_WARN_Folgt weiter den Pfad hinauf|r",
        ["|cRXP_WARN_Create a|r |T135139:0|t[Lesser Magic Wand]"] = "|cRXP_WARN_Stellt einen |r |T135139:0|t[Geringer Magiezauberstab] her",
        ["|cRXP_WARN_Create a|r |T135805:0|t[Basic Campfire] |cRXP_WARN_(in your Profession Book)|r"] = "|cRXP_WARN_Erstellt eine|r |T135805:0|t[Kochfeuerstelle] |cRXP_WARN_(in eurem Berufsbuch)|r",
        ["|cRXP_WARN_Create a|r |T135805:0|t[Basic Campfire] |cRXP_WARN_(under the General Tab of your Spellbook)|r"] = "|cRXP_WARN_Erstellt eine|r |T135805:0|t[Einfaches Lagerfeuer] |cRXP_WARN_(unter dem Allgemeinen-Reiter eures Zauberbuches)|r",
        ["|cRXP_WARN_Create as many|r |T132662:0|t[Brown Linen Robes] |cRXP_WARN_as you can|r"] = "|cRXP_WARN_Stellt so viele|r |T132662:0|t[Braune Leinenrobe] |cRXP_WARN_wie ihr könnt|r her",
        ["|cRXP_WARN_Delete any leftover|r |T132914:0|t[Sunscale Feathers] |cRXP_WARN_you still have|r"] = "|cRXP_WARN_Entfernt alle übrigen|r |T132914:0|t[Bluthornfeder] |cRXP_WARN_, die ihr noch habt|r",
        ["|cRXP_WARN_Delete the|r |T135426:0|t[Small Throwing Knife] |cRXP_WARN_from your bags, as it is no longer needed|r"] = "|cRXP_WARN_Zerstört das|r |T135426:0|t[Kleines Wurfmesser] |cRXP_WARN_aus euren Taschen, da es nicht mehr benötigt wird|r",
        ["|cRXP_WARN_Destroy the|r |T133490:0|t[Executor's Motivator] |cRXP_WARN_as it's no longed needed for anything|r"] = "|cRXP_WARN_Zerstört den|r |T133490:0|t[Motivator des Exekutors] |cRXP_WARN_da es nicht mehr für irgendetwas benötigt wird|r",
        ["|cRXP_WARN_Destroy|r |T134227:0|t[Horn of Echeyakee] |cRXP_WARN_as you no longer need it|r"] = "|cRXP_WARN_Zerstört|r |T134227:0|t[Horn von Echeyakee] |cRXP_WARN_, da ihr es nicht mehr braucht|r",
        ["|cRXP_WARN_Die and respawn at the |cRXP_FRIENDLY_Spirit Healer|r near the arrow|r"] = "|cRXP_WARN_Sterbt und erscheint neu beim |cRXP_FRIENDLY_Geistheiler|r in der Nähe des Pfeils|r",
        ["|cRXP_WARN_Die and respawn at the Spirit Healer by using|r |T136126:0|t[Life Tap] |cRXP_WARN_and standing on the Bonfire next to you|r"] = "|cRXP_WARN_Sterbt und respawnt beim Geistheiler durch die Anwendung von|r |T136126:0|t[Aderlass] |cRXP_WARN_und steht auf dem Lagerfeuer daneben|r",
        ["|cRXP_WARN_Disenchant all the|r |T132662:0|t[Brown Linen Robes] |cRXP_WARN_that you made and create a|r |T135225:0|t[Runed Copper Rod]"] = "|cRXP_WARN_Entzaubert alle|r |T132662:0|t[Braune Leinenrobe] |cRXP_WARN_die ihr gemacht habt und erstellt eine|r |T135225:0|t[Runenverzierte Kupferrute]",
        ["|cRXP_WARN_Dismiss your |cRXP_ENEMY_Dire Mottled Boar|r by right clicking its unit frame and clicking dismiss, otherwise you'll be unable to tame a|r |cRXP_ENEMY_Surf Crawler|r"] = "|cRXP_WARN_Gebt euren |cRXP_ENEMY_Scheckiger Terroreber|r frei, indem ihr mit der rechten Maustaste auf seinen Einheitenrahmen klickt und auf Freigeben klickt. Andernfalls könnt ihr einen |rBrandungskriecher|cRXP_ENEMY_ nicht zähmen|r",
        ["|cRXP_WARN_Dismiss your |cRXP_ENEMY_Ornery Galestrider::251707|r by right clicking its unit frame and clicking dismiss, otherwise you'll be unable to tame an|r |cRXP_ENEMY_Vuldren::250874|r"] = "|cRXP_WARN_Gebt von Euch |cRXP_ENEMY_Ornery Galestrider::251707|r frei, indem ihr mit Rechtsklick auf seinen Unit Frame klickt und auf Freigeben klickt, sonst könnt ihr|r |cRXP_ENEMY_Vuldren::250874|r nicht zähmen",
        ["|cRXP_WARN_Dismiss your |cRXP_ENEMY_Surf Crawler|r by right clicking its unit frame and clicking dismiss, otherwise you'll be unable to tame an|r |cRXP_ENEMY_Armored Scorpid|r"] = "|cRXP_WARN_Gebt euren |cRXP_ENEMY_Ausgewachsener Brandungskriecher|r frei, indem ihr auf sein Einheitenfenster rechtsklickt und auf Freigeben klickt, sonst könnt ihr keinen|r |cRXP_ENEMY_Gepanzerter Skorpid|r zähmen",
        ["|cRXP_WARN_Dismiss your |cRXP_ENEMY_Windsong Crawler::254588|r by right clicking its unit frame and clicking dismiss, otherwise you'll be unable to tame an|r |cRXP_ENEMY_Ornery Galestrider::251707|r"] = "|cRXP_WARN_Entlasst euren |cRXP_ENEMY_Windsong Kriecher::254588|r, indem ihr mit der rechten Maustaste auf seinen Einheitsrahmen klickt und auf 'Freigeben' klickt, sonst könnt ihr keinen|r |cRXP_ENEMY_Ornery Galestrider::251707|r zähmen",
        ["|cRXP_WARN_Dismiss your|r |T136218:0|t[Imp] |cRXP_WARN_by right clicking its unit frame and clicking dismiss|r"] = "|cRXP_WARN_Gebt euren|r |T136218:0|t[Wichtel] |cRXP_WARN_frei indem ihr auf den Einheitenrahmen und dann auf freigeben klickt |r",
        ["|cRXP_WARN_Do not accept Stormpike's Order yet|r"] = "|cRXP_WARN_Nehmt Sturmlanze's Order noch nicht an|r",
        ["|cRXP_WARN_Do NOT fly anywhere!|r"] = "|cRXP_WARN_Fliegt nicht irgendwohin|r",
