        ["|cRXP_WARN_Do not follow the wolf that spawns|r"] = "|cRXP_WARN_Folge nicht dem Wolf, der erscheint|r",
        ["|cRXP_WARN_Do NOT go below 1 Silver|r"] = "|cRXP_WARN_Fallt NICHT unter 1 Silber|r",
        ["|cRXP_WARN_Do not jump off the zeppelin early, as you may be pushed off the platform|r."] = "|cRXP_WARN_Springt nicht vorzeitig vom Zeppelin ab, sonst werdet ihr möglicherweise von der Plattform heruntergestoßen.|r",
        ["|cRXP_WARN_Do not loot any of the|r |T134059:0|t[|cRXP_PICK_Sacks of Oats|r] |cRXP_WARN_yet unless you have sent yourself large capacity bags as you will need to preserve bagspace for the upcoming segment|r"] = "|cRXP_WARN_Sammelt noch keine|r |T134059:0|t[|cRXP_PICK_Sack Hafer|r] |cRXP_WARN_ es sei denn, ihr habt euch selbst große Taschen geschickt, da ihr Platz für den kommenden Abschnitt brauchen werdet|r",
        ["|cRXP_WARN_Do not move or jump until the quest is complete|r."] = "|cRXP_WARN_Bewegt euch nicht und springt nicht, bis die Quest abgeschlossen ist|r.",
        ["|cRXP_WARN_Do NOT sell any of these items until you turn the Redridge Goulash quest|r"] = "|cRXP_WARN_Verkauft KEINE dieser Gegenstände, bis ihr die Quest Rotkammgulasch abgebt|r",
        ["|cRXP_WARN_Do NOT sell your|r |T133884:0|t[|cRXP_LOOT_Murloc Eyes|r]"] = "|cRXP_WARN_Verkauft nicht eure|r |T133884:0|t[|cRXP_LOOT_Murlocaugen|r]",
