        ["|cRXP_WARN_Do not use|r |T132845:0|t[Walk on Air] |cRXP_WARN_until you accept Bugged|r."] = "|cRXP_WARN_Verwendet nicht|r |T132845:0|t[Luftwandeln] |cRXP_WARN_bis ihr die Quest Bugged annehmt|r.",
        ["|cRXP_WARN_Do NOT vendor the|r |T133581:0|t[Bag of Marbles] |cRXP_WARN_reward. This is an incredibly valuable item all the way through to level 60|r"] = "|cRXP_WARN_Verkauft|r |T133581:0|t[Tasche of Marbles] NICHT an einen Händler|cRXP_WARN_Dies ist ein unglaublich wervoller Gegenstand bis Level 60|r",
        ["|cRXP_WARN_Do this quickly as another player may purchase it before you do|r"] = "|cRXP_WARN_Tut dies schnell, da ein anderer Spieler es vor euch kaufen könnte|r",
