        ["|cRXP_WARN_Don't fly anywhere!|r"] = "|cRXP_WARN_Fliegt nicht irgendwohin!|r",
        ["|cRXP_WARN_Don't go out of your way to complete this right now. You'll come back to Loch Modan soon|r"] = "|cRXP_WARN_Macht euch nicht extra auf den Weg, um das jetzt abzuschließen. Ihr kommt bald nach Loch Modan zurück|r",
        ["|cRXP_WARN_Don't go out of your way to farm this now. Just remember to hold onto the eggs and start thinking how many skillups you still need to reach 50 cooking|r"] = "|cRXP_WARN_Macht euch keinen Stress die Eier jetzt zu farmen. Denkt einfach daran, die Eier zu behalten und überlegt, wie viele Fertigkeitspunkte ihr noch benötigt, um Kochen 50 zu erreichen|r",
        ["|cRXP_WARN_Don't go out of your way to farm this now. Simply kill and loot all the boars you're passing by|r"] = "|cRXP_WARN_Macht euch jetzt nicht unnötig die Mühe, dies zu farmen. Tötet und plündert einfach alle Wildschweine, an denen du vorbei kommst|r",
        ["|cRXP_WARN_Don't go out of your way to farm this now. Simply kill and loot all the wolves you're passing by|r"] = "|cRXP_WARN_Macht euch jetzt nicht unnötig die Mühe, dies zu farmen. Tötet und plündert einfach alle Wölfe, an denen du vorbei kommst|r",
        ["|cRXP_WARN_Don't go out of your way to loot all |cRXP_LOOT_Stolen Books|r yet|r"] = "|cRXP_WARN_Bemüht euch noch nicht, alle |cRXP_LOOT_Gestohlene Bücher|r zu plündern|r",
        ["|cRXP_WARN_Don't kill |cRXP_ENEMY_Meven Korgal|r yet|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Meven Korgal|r noch nicht|r",
        ["|cRXP_WARN_Don't kill any |cRXP_ENEMY_Young Black Bears|r en-route|r"] = "|cRXP_WARN_Tötet keine |cRXP_ENEMY_Junger Schwarzbär|r auf dem weg|r",
