        ["|cRXP_WARN_Don't worry if you're not|r |T132147:0|t[Dual Wielding] |cRXP_WARN_right now, you'll buy a weapon later when necessary|r"] = "|cRXP_WARN_Macht euch keine Sorgen, wenn ihr jetzt keine|r |T132147:0|t[Beidhändigkeit] |cRXP_WARN_habt,ihr werdet später wenn nötig eine Waffe kaufen|r",
