        ["|cRXP_WARN_Ensure to turn this in before the 10 minute expiry on the|r |T1387609:0|t[Jar of Snow]"] = "Stellt sicher, dass ihr dies abgebt, bevor die 10-Minuten-Frist des |T1387609:0|t[Krug mit Schnee] |cRXP_WARN_abläuft|r",
        ["|cRXP_WARN_Ensure you have 10|r |T132889:0|t[Linen Cloth] |cRXP_WARN_for your upcoming Paladin class quest|r"] = "|cRXP_WARN_Sorgt dafür, dass ihr 10|r |T132889:0|t[Leinenstoff] |cRXP_WARN_für eure bevorstehende Die Bruderschaft der Defias-Klassenquest habt|r",
        ["|cRXP_WARN_Ensure you have dismissed your previous|r |cRXP_ENEMY_Gray Forest Wolf|r"] = "|cRXP_WARN_Stellt sicher, dass ihr euren vorherigen|r Grauer Forstwolf|cRXP_ENEMY_ freigegeben habt|r",
        ["|cRXP_WARN_Ensure you have dismissed your previous|r |cRXP_ENEMY_Rockhide Boar|r"] = "|cRXP_WARN_Stellt sicher, dass ihr euren vorherigen|r Steinhauteber|cRXP_ENEMY_ freigegeben habt|r",
        ["|cRXP_WARN_Ensure you save 20s 70c for later|r"] = "|cRXP_WARN_Stellt sicher, dass ihr 20s 70c für später spart|r",
