        ["|cRXP_WARN_Ensure your subzone is Coldridge Valley when you die! Otherwise you will be sent to the Kharanos graveyard|r"] = "|cRXP_WARN_Stellt sicher, dass eure Subzone Das Eisklammtal ist, wenn ihr sterbt! Andernfalls werdet ihr zum Kharanos-Friedhof geschickt.|r",
        ["|cRXP_WARN_Enter and explore Fargodeep Mine|r"] = "|cRXP_WARN_Betretet und erforscht die Tiefenschachtmine|r",
