        ["|cRXP_WARN_Equip the|r |T135641:0|t[Curvewood Dagger] |cRXP_WARN_for this quest if you don't already have a|r |T135641:0|t[Dagger] |cRXP_WARN_equipped|r"] = "|cRXP_WARN_Legt|r |T135641:0|t[Krummholzdolch] |cRXP_WARN_für diese Quest an, wenn ihr nicht bereits einen|r |T135641:0|t[Dolch] |cRXP_WARN_angelegt habt|r",
        ["|cRXP_WARN_Equip the|r |T7791298:0|t[Flutterfly Swatter] if you don't have |T7791298:0|t[Zephrali Bludgeon]."] = "|cRXP_WARN_Legt|r |T7791298:0|t[Flatterfliegenklatsche] an, falls ihr nicht |T7791298:0|t[Knüppel der Zephrali] habt.",
        ["|cRXP_WARN_Equip the|r |T7792097:0|t[Honed Greathammer] if you don't have |T7792097:0|t[Zephrali Smasher]."] = "|cRXP_WARN_Legt|r |T7792097:0|t[Gewetzter Großhammer] an, falls ihr nicht |T7792097:0|t[Zermalmer der Zephrali] habt.",
        ["|cRXP_WARN_Equip the|r |T7798447:0|t[Balanced Quarterstaff] if you don't have |T7792229:0|t[Zephrali Knife]."] = "|cRXP_WARN_Legt|r |T7798447:0|t[Ausbalancierter Bauernstecken] an, falls ihr nicht |T7792229:0|t[Messer der Zephrali] habt.",
        ["|cRXP_WARN_Equip the|r |TInterface/Icons/inv_knife_1h_skybornec60_b_01:0|t[Quickblade's Dagger] if you don't have |T7791298:0|t[Zephrali Bludgeon]."] = "|cRXP_WARN_Legt|r |TInterface/Icons/inv_knife_1h_skybornec60_b_01:0|t[Quickblade's Dagger] an, falls ihr nicht |T7791298:0|t[Knüppel der Zephrali] habt.",
        ["|cRXP_WARN_Equip them both once you're level 14|r"] = "|cRXP_WARN_Legt sie beide an, wenn ihr Stufe 14 seid|r",
        ["|cRXP_WARN_Escort |cRXP_FRIENDLY_Kerlonian|r to his bag |cRXP_WARN_in Darkshore|r|r"] = "|cRXP_WARN_Eskortiert |cRXP_FRIENDLY_Kerlonian|r zu seinen Beutel |cRXP_WARN_in Dunkelküste|r|r",
        ["|cRXP_WARN_Escort |cRXP_FRIENDLY_Prospector Remtravel|r through the Excavation|r"] = "|cRXP_WARN_Eskortiert |cRXP_FRIENDLY_Ausgrabungsleiter Remtravel|r durch die Ausgrabung|r",
        ["|cRXP_WARN_Escort |cRXP_FRIENDLY_Therylune|r out of The Masters Glaive|r"] = "|cRXP_WARN_Eskortiert |cRXP_FRIENDLY_Therylune|r aus Der Meistergleve|r",
        ["|cRXP_WARN_Even if some of these are gray, still complete the quest as it is part of a chain|r"] = "|cRXP_WARN_Auch wenn einige dieser Quests grau sind, vervollständigt sie trotzdem, da sie Teil einer Quest-Reihe sind|r",
        ["|cRXP_WARN_Expect to break about 10 stones, but you may need up to 15|r."] = "|cRXP_WARN_Erwartet, etwa 10 Steine zu zerbrechen, aber möglicherweise benötigt ihr bis zu 15.|r",
        ["|cRXP_WARN_Feel free to skip this for now and come back later if you wish|r"] = "|cRXP_WARN_Ihr könnt diesen Schritt gerne überspringen und später zurückkommen, wenn ihr möchtet.|r",
        ["|cRXP_WARN_Feel free to skip this quest if you haven't had many drops yet so far|r"] = "|cRXP_WARN_Könnt diese Quest gerne überspringen, wenn ihr bis jetzt noch nicht viele Gegenstände gelootet habt|r",
        ["|cRXP_WARN_Finish collecting the |T134187:0|t[Earthroot] via |T136065:0|t[Herbalism] and rarely|r |cRXP_PICK_Battered Chests|r"] = "|cRXP_WARN_Beendet das Sammeln der |T134187:0|t[Erdwurzeln] durch |T136065:0|t[Kräuterkunde] und seltene |rZerschlagene Truhen|cRXP_PICK_|r",
        ["|cRXP_WARN_Finish getting the items for Mazzranache|r"] = "|cRXP_WARN_Beendet das Sammeln der Gegenstände für Mazzranache|r",
        ["|cRXP_WARN_Fly to Ironforge and skip this step if you're planning on running the Hall of Thanes dungeon in Ironforge|r"] = "|cRXP_WARN_Fliegt nach Eisenschmiede und überspringt diesen Schritt, wenn ihr plant, den Die Halle der Thanen Dungeon in Eisenschmiede durchzulaufen|r",
        ["|cRXP_WARN_Focus on killing |cRXP_ENEMY_Surena Caledon|r very quickly|r"] = "|cRXP_WARN_Fokussiert euch auf das sehr schnelle Töten von |cRXP_ENEMY_Surena Caledon|r |r",
        ["|cRXP_WARN_Follow the arrow closely to return to Northshire to turn in the quest you just completed for a weapon reward|r"] = "|cRXP_WARN_Folgt genau dem Pfeil, um nach Nordhain zurückzukehren und die gerade abgeschlossene Quest für eine Waffenbelohnung abzugeben|r",
        ["|cRXP_WARN_Follow the arrow precisely to avoid dying. Regain some health before the second jump|r"] = "|cRXP_WARN_Folgt den Pfeil genau, um nicht zu sterben. Heilt euch vor dem zweiten Sprung.|r",
        ["|cRXP_WARN_Found throughout the zone. Use |T1029587:0|t[Skysight] near one to gain 10% movement speed for 15 min instead of 15 sec|r."] = "|cRXP_WARN_Gefunden in der ganzen Zone. Benutzt |T1029587:0|t[Himmelssicht] in der Nähe davon, um 10% Bewegungsgeschwindigkeit für 15 Min. statt 15 Sek. zu erhalten|r.",
        ["|cRXP_WARN_Found throughout the zone|r |cRXP_WARN_Use|r |T236219:0|t[Read Ley Line] |cRXP_WARN_near one to gain 100% Mana and Health regeneration for 15 min instead of 15 sec|r."] = "|cRXP_WARN_Gefunden in der ganzen Zone|r |cRXP_WARN_Benutzt|r |T236219:0|t[Leylinie erschließen] |cRXP_WARN_neben einem, um 100% Mana- und Gesundheitsregeneration für 15 Min. anstatt 15 Sek. zu erhalten|r.",
        ["|cRXP_WARN_Get the items for Mazzranache as you quest throughout the zone|r"] = "|cRXP_WARN_Sammelt die Gegenstände für Mazzranache, während ihr in der Zone an Aufträgen arbeitet|r",
        ["|cRXP_WARN_Go up the ramp to the right of|r |cRXP_FRIENDLY_Jocaste|r"] = "|cRXP_WARN_Geht die Rampe auf der rechten Seite von|r |cRXP_FRIENDLY_Jocaste|r",
        ["|cRXP_WARN_Go upstairs in the keep|r"] = "|cRXP_WARN_Geht die Treppen in der Burg hinauf|r",
        ["|cRXP_WARN_Grind |cRXP_ENEMY_Mottled Boars|r. Loot them until you have 1 silver worth of vendor items|r"] = "|cRXP_WARN_Farmt |cRXP_ENEMY_Scheckiger Eber|r. Plündert sie, bis ihr Gegenstände im Wert von 1 Silber habt|r",
        ["|cRXP_WARN_Grind |cRXP_ENEMY_Plainstriders|r. Loot them until you have 1 silver worth of vendor items|r"] = "|cRXP_WARN_Farmt |cRXP_ENEMY_Ebenenschreiter|r. Plündert sie, bis ihr einen Wert von 1 Silber an Verkaufsgegenständen habt|r",
        ["|cRXP_WARN_Grind |cRXP_ENEMY_Plainstriders|r. Loot them until you have 2 silver worth of vendor items|r"] = "|cRXP_WARN_Farmt |cRXP_ENEMY_Ebenenschreiter|r. Plündert sie, bis ihr einen Wert von 2 Silber an Verkaufsgegenständen habt|r",
        ["|cRXP_WARN_Grind en-route. Make sure you have at least 2|r |T134075:0|t[|cRXP_LOOT_Soul Shards|r] before reaching Redridge |cRXP_WARN_by using|r |T136163:0|t[|cRXP_FRIENDLY_Drain Soul|r] as mobs are about to die"] = "|cRXP_WARN_Grinded auf dem Weg. Stellt sicher, dass ihr mindestens 2|r |T134075:0|t[|cRXP_LOOT_Seelensplitter|r] habt bevor ihr das Rotkammgebirge erreicht |cRXP_WARN_durch Verwendung von|r |T136163:0|t[|cRXP_FRIENDLY_Seelendieb|r] während die Mobs sterben",
        ["|cRXP_WARN_Grind extra |cRXP_ENEMY_Ragged Young Wolves|r if you don't have enough money|r"] = "Farmt|cRXP_WARN_ extra |cRXP_ENEMY_Struppiger junger Wolf|r wenn ihr nicht genug Geld habt|r",
        ["|cRXP_WARN_Grind to 1110+/1400xp|r"] = "|cRXP_WARN_Farmt bis 1110+/1400xp|r",
        ["|cRXP_WARN_Grind until you have 10s30c worth of vendorables|r"] = "|cRXP_WARN_Farmt, bis ihr 10s30c Wert an Verkaufswaren habt|r",
        ["|cRXP_WARN_He can be found in one of the camps|r"] = "|cRXP_WARN_Er befindet sich in einem der Lager|r",
        ["|cRXP_WARN_He has a chance of spawning every time a |cRXP_ENEMY_Kolkar|r is killed|r"] = "|cRXP_WARN_Er hat eine Chance zu spawnen, jedes Mal wenn ein |cRXP_ENEMY_Kolkar|r getötet wird|r",
        ["|cRXP_WARN_He has at least two different spawn locations inside Thunder Ridge|r"] = "|cRXP_WARN_Er hat mindestens zwei verschiedene Spawnplätze im Donnergrat|r",
        ["|cRXP_WARN_He is a level 11 elite. Skip this step if you are unable to kill him|r"] = "|cRXP_WARN_Er ist ein Level-11-Elite. Überspringt diesen Schritt, wenn ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_He is upstairs in the building|r"] = "|cRXP_WARN_Er ist oben im Gebäude.|r",
        ["|cRXP_WARN_He knocks you back and takes additional fire damage|r."] = "|cRXP_WARN_Er schlägt euch zurück und erleidet zusätzlichen Feuer-Schaden|r.",
        ["|cRXP_WARN_He may be patrolling around the graveyard|r"] = "|cRXP_WARN_Er könnte rund um den Friedhof patrouillieren|r",
        ["|cRXP_WARN_He patrols a little|r"] = "|cRXP_WARN_Er patrouilliert ein bisschen|r",
        ["|cRXP_WARN_He patrols along the eastern road|r"] = "|cRXP_WARN_Er patrouilliert entlang der östlichen Straße|r",
        ["|cRXP_WARN_He patrols around a bit|r"] = "|cRXP_WARN_Er patrouilliert ein wenig herum|r",
        ["|cRXP_WARN_He patrols around the graveyard|r"] = "|cRXP_WARN_Er patrouilliert um den Friedhof herum|r",
        ["|cRXP_WARN_He patrols clockwise around Northern Mulgore|r"] = "|cRXP_WARN_Er patrouilliert im Uhrzeigersinn um das nördliche-Mulgore|r",
        ["|cRXP_WARN_He patrols the road|r"] = "|cRXP_WARN_Er patrouilliert auf der Straße|r",
        ["|cRXP_WARN_He patrols up and down the platform|r"] = "|cRXP_WARN_Er patrouilliert auf der Plattform auf und ab|r",
        ["|cRXP_WARN_He runs clockwise in circles around Bloodhoof Village|r"] = "|cRXP_WARN_Er läuft im Uhrzeigersinn in Kreisen um Das Dorf der Bluthufe|r",
        ["|cRXP_WARN_He spawns at the first camp and patrols up the hill|r"] = "|cRXP_WARN_Er spawnt im ersten Lager und patroulliert den Hügel hinauf|r",
        ["|cRXP_WARN_He will also summon a |cRXP_ENEMY_Rumbler|r add. Be careful if you're attempting to solo this. Skip this step if you are unable to kill him|r"] = "|cRXP_WARN_Er wird auch einen |cRXP_ENEMY_Rumpler|r Add herbeirufen. Seid vorsichtig, wenn ihr versucht, dies alleine zu schaffen. Überspringt diesen Schritt, wenn ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_He will summon three |cRXP_ENEMY_Rumblers|r. Skip this step if you are unable to kill him|r"] = "|cRXP_WARN_Er wird drei |cRXP_ENEMY_Rumpler|r herbeirufen. Überspringt diesen Schritt, wenn ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_He's an abomination that patrols along the road to Brill|r"] = "|cRXP_WARN_Er ist eine Abscheulichkeit, welches die Straße nach Brill patrouilliert.|r",
        ["|cRXP_WARN_Hippogryphs are extremely fast. Do not rely on outrunning them if things get dangerous|r."] = "|cRXP_WARN_Hippogryphs are extremely fast. Tut nicht rely on outrunning them if things get dangerous|r.",
        ["|cRXP_WARN_If |cRXP_ENEMY_Echeyakee|r didn't spawn after using the|r |T134227:0|t[Horn of Echeyakee]|cRXP_WARN_or you didn't get the tag when it did spawn, abandon Echeyakee, then return to town and accept it again|r"] = "|cRXP_WARN_Wenn |cRXP_ENEMY_Echeyakee|r nicht gespawnt ist, nachdem ihr das|r |T134227:0|t[Horn von Echeyakee]|cRXP_WARN_ oder wenn ihr die tag nicht bekommen habt, wenn er doch gespawnt ist, brecht die Quest Echeyakee ab, kehrt dann zur Stadt zurück und nehmt sie wieder an|r",
        ["|cRXP_WARN_If |cRXP_ENEMY_Echeyakee|r doesn't spawn after using the|r |T134227:0|t[Horn of Echeyakee]|cRXP_WARN_ or you didn't get the tag when it did spawn, skip this step|r"] = "|cRXP_WARN_Falls |cRXP_ENEMY_Echeyakee|r nicht erscheint, nachdem ihr das|r |T134227:0|t[Horn von Echeyakee]|cRXP_WARN_ benutzt habt, oder ihr den tag nicht bekommen habt, als er erschien ist, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If |cRXP_FRIENDLY_Pal'juh|r is not there, feel free to skip this step and deathskip back to Sen'jin Village at the Bonfire|r"] = "|cRXP_WARN_Falls |cRXP_FRIENDLY_Pal'juh|r nicht dort ist, könnt ihr diesen Schritt gerne überspringen und per Death-Skip am Lagerfeuer zurück zum Dorf Sen'jin gelangen.|r",
        ["|cRXP_WARN_If |cRXP_FRIENDLY_Pal'juh|r is not there, feel free to skip this step|r"] = "|cRXP_WARN_Falls |cRXP_FRIENDLY_Pal'juh|r nicht dort ist, könnt ihr diesen Schritt gerne überspringen|r",
        ["|cRXP_WARN_If a bird attacks you, cancel the carrying aura to avoid being teleported outside|r."] = "|cRXP_WARN_Wenn ein Vogel euch angreift, brecht die carrying aura ab, um nicht nach außen teleportiert zu werden|r.",
        ["|cRXP_WARN_If a Flutterfly doesn't fly away, use the swatter on it again|r"] = "|cRXP_WARN_Falls ein Flutterfly nicht wegfliegt, benutzt den Schwatter erneut auf ihn|r",
        ["|cRXP_WARN_If a Tornado is nearby, touch it to gain 40% increased movement speed for 5 minutes. Dealing damage removes the effect|r."] = "|cRXP_WARN_Wenn ein Tornado in der Nähe ist, berührt ihn, um 40% erhöhte Bewegungsgeschwindigkeit für 5 Minuten zu erhalten. Wenn ihr Schaden verursacht, wird der Effekt entfernt|r.",
        ["|cRXP_WARN_If a Tornado is present, use it for faster travel|r."] = "|cRXP_WARN_Wenn ein Tornado vorhanden ist, benutzt ihn für schnellere Reisen|r.",
        ["|cRXP_WARN_If he is not there, skip this quest for now|r"] = "|cRXP_WARN_Falls er nicht da ist, überspringt diese Quest für jetzt.|r",
        ["|cRXP_WARN_If it hasn't dropped after 25+ mobs, feel free to skip this quest|r"] = "|cRXP_WARN_Falls es nach 25+ Mobs nicht gedropped ist, könnt ihr diese Quest gerne überspringen|r",
        ["|cRXP_WARN_If someone already did, it will finish anyway|r"] = "|cRXP_WARN_Falls someone already did, it will finish anyway|r",
        ["|cRXP_WARN_If the |cRXP_ENEMY_Savannah Patriarchs|r are heavily contested consider skipping this quest for now, it can be completed later|r"] = "|cRXP_WARN_Falls die |cRXP_ENEMY_Savannah Patriarchs|r stark umkämpft sind, überspringt diese Quest vorerst. Sie kann später abgeschlossen werden|r",
        ["|cRXP_WARN_If the area is abnormally crowded, camp one spawn point or rotate between nearby stones|r."] = "|cRXP_WARN_Falls die Gegend abnorm überfüllt ist, haltet euch an einem Spawnpunkt auf oder rotiert zwischen nahegelegenen Steinen.|r",
        ["|cRXP_WARN_If the Tornado speed buff is active or a Tornado is nearby, avoid killing them.|r."] = "|cRXP_WARN_Falls der Tornado-Geschwindigkeitsbuff aktiv ist oder ein Tornado in der Nähe ist, vermeidet, sie zu töten.|r",
        ["|cRXP_WARN_If there are no |cRXP_ENEMY_Defias|r nearby, run back instead|r"] = "|cRXP_WARN_Falls dort keine |cRXP_ENEMY_Defias|r in der nähe sind, lauft stattdessen zürück|r",
        ["|cRXP_WARN_If there aren't many |cRXP_ENEMY_Gnarlpine Mystics|r you may have to kill |cRXP_ENEMY_Gnarlpine Warriors|r to make them spawn|r"] = "|cRXP_WARN_Falls es nicht viele |cRXP_ENEMY_Mystiker der Knarzklauen|r gibt, müsst ihr möglicherweise |cRXP_ENEMY_Krieger der Knarzklauen|r töten, um sie spawnen zu lassen|r",
        ["|cRXP_WARN_If you are unable to kill the |cRXP_ENEMY_The Threshwackonator 4100|r, skip this step|r"] = "|cRXP_WARN_Falls ihr |cRXP_ENEMY_Der Dreschonator 4100|r nicht töten könnt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you are unable to loot these due to too many |cRXP_ENEMY_Murlocs|r, skip this step|r"] = "|cRXP_WARN_Falls ihr diese nicht plündern könnt wegen zu vielen |cRXP_ENEMY_Murlocs|r, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you can't afford it, skip this step|r"] = "|cRXP_WARN_Falls ihr euch das nicht leisten könnt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you can't afford this, then grind money from the nearby |cRXP_ENEMY_Tunnel Rats|r until you have enough|r"] = "|cRXP_WARN_Falls ihr euch das nicht leisten könnt, farmt Geld von den nahegelegenen |cRXP_ENEMY_Tunnel-Ratten|r bis ihr genug habt|r",
        ["|cRXP_WARN_If you can't do this, just run out of Undercity normally|r"] = "|cRXP_WARN_Falls ihr das nicht könnt, lauft einfach normal aus der Unterstadt|r",
        ["|cRXP_WARN_If you did not get a|r |T132867:0|t[Lesser Magic Essence] |cRXP_WARN_then buy one from|r |cRXP_FRIENDLY_Thaddeus|r |cRXP_WARN_if there is one available. Otherwise finish this step later|r"] = "|cRXP_WARN_Falls ihr|r |T132867:0|t[Geringe Magieessenz] nicht bekommen habt |cRXP_WARN_dann kauft eine bei|r |cRXP_FRIENDLY_Thaddeus|r |cRXP_WARN_wenn eine verfügbar ist. Sonst beendet diesen Schritt später|r",
        ["|cRXP_WARN_If you do this and were gathering|r |T132889:0|t[Linen Cloth] |cRXP_WARN_earlier, you can sell your|r |T132889:0|t[Linen Cloth] |cRXP_WARN_on the Auction House|r"] = "|cRXP_WARN_Falls ihr das macht und vorher|r |T132889:0|t[Leinenstoff] |cRXP_WARN_gesammelt habt, könnt ihr euren|r |T132889:0|t[Leinenstoff] |cRXP_WARN_im Auktionshaus verkaufen|r",
        ["|cRXP_WARN_If you don't get the quest credit for sitting down abandon the quest and pick it up again!|r"] = "|cRXP_WARN_Falls das Sitzen nicht für die Quest zählt, brecht sie ab und nehmt sie erneut auf!|r",
        ["|cRXP_WARN_If you don't want to do this or you'd rather buy it from the Auction House later, skip this step|r"] = "|cRXP_WARN_Falls ihr das nicht tun möchtet oder lieber später vom Auktionshaus kaufen möchtet, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you don't want to do this, skip this step|r"] = "|cRXP_WARN_Falls ihr das nicht tun wollt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you don't want to do this, swim underwater into the bottom floor of the boat then loot the |cRXP_LOOT_Mist Veil's Lockbox|r inside|r"] = "|cRXP_WARN_Falls ihr das nicht tun möchtet, schwimmt unter Wasser in den unteren Teil des Bootes und plündert dann die |cRXP_LOOT_Schließkassette der NEBELSCHLEIER|r von innen|r",
        ["|cRXP_WARN_If you don't want to do this, swim underwater into the bottom floor of the boat then loot the |cRXP_LOOT_Silver Dawning's Lockbox|r inside|r"] = "|cRXP_WARN_Falls ihr das nicht wollt, schwimmt unter Wasser zum unteren Deck des Bootes, dann plündert die |cRXP_LOOT_Schließkassette der SILBERMORGEN|r im Inneren|r",
        ["|cRXP_WARN_If you don't want to or can't do this, skip this step|r"] = "|cRXP_WARN_Falls ihr das nicht wollt oder könnt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you don't wish to do this or would rather try to buy a cheaper/better weapon from the AH soon instead, skip this step|r"] = "|cRXP_WARN_Falls ihr das nicht tun möchtet oder lieber bald eine billigere/bessere Waffe vom Auktionshaus kaufen möchtet, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you don't wish to do this, skip this step|r"] = "|cRXP_WARN_Falls ihr es nicht möchtet, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you equip the|r |T133762:0|t[Enchanted Moonstalker Cloak]|cRXP_WARN_, make sure you save your current cloak for later as the|r |T133762:0|t[Enchanted Moonstalker Cloak] |cRXP_WARN_is lost upon a later turn in|r"] = "|cRXP_WARN_Falls ihr |r |T133762:0|t[Verzauberter Mondpirscher-Umhang]|cRXP_WARN_ anlegt, stellt sicher, dass ihr euren aktuellen Umhang für später speichert, da der |r |T133762:0|t[Verzauberter Mondpirscherumhang] |cRXP_WARN_ bei einer späteren Abgabe verloren geht|r",
        ["|cRXP_WARN_If you fail and run out of Taming Rod Charges, abandon the quest, then pick it up again and come back|r"] = "|cRXP_WARN_Falls ihr fehlschlagt und eure Zähmerruten-Aufladungen aufgebraucht sind, brecht die Quest ab, nehmt sie wieder an und kommt zurück|r",
        ["|cRXP_WARN_If you fail the quest don't worry as you can get it again later|r"] = "|cRXP_WARN_Falls ihr die Quest nicht schafft, macht euch keine Sorgen, da ihr sie später erneut bekommen könnt|r",
        ["|cRXP_WARN_If you failed the quest, skip this step|r"] = "|cRXP_WARN_Falls ihr die Quest nicht geschafft habt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you find a Tornado, touch it to gain its speed buff|r."] = "|cRXP_WARN_Falls ihr einen Tornado findet, berührt ihn, um seinen Geschwindigkeitsbonus zu erhalten|r.",
        ["|cRXP_WARN_If you give up and can't find enough, skip this step|r"] = "|cRXP_WARN_Falls ihr aufgebt und nicht genug finden könnt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you have a|r |T135641:0|t[Dagger] |cRXP_WARN_in your bags or equipped, you can cast|r |T132282:0|t[Ambush] |cRXP_WARN_on the |cRXP_ENEMY_Defias Tower Patrollers|r and |cRXP_ENEMY_Defias Tower Sentries|r inside to kill them instantly. Be prepared to run after you kill the first |cRXP_ENEMY_Defias Tower Sentry|r and remember you can be hit from above. This is slower, but a LOT safer|r"] = "|cRXP_WARN_Wenn ihr einen|r |T135641:0|t[Dolch] |cRXP_WARN_in euren Taschen oder ausgerüstet habt, könnt ihr|r |T132282:0|t[Hinterhalt] |cRXP_WARN_auf die |cRXP_ENEMY_Turmpatrouille der Defias|r und |cRXP_ENEMY_Turmwachposten der Defias|r im Inneren wirken, um sie sofort zu töten. Seid bereit zu laufen, nachdem ihr den ersten |cRXP_ENEMY_Turmwachposten der Defias|r getötet habt und denkt daran, dass ihr von oben getroffen werden könnt. Das ist langsamer, aber VIEL sicherer|r",
        ["|cRXP_WARN_If you have a|r |T626003:0|t|cFFF48CBAPaladin|r|cRXP_WARN_,|r |T625999:0|t|cFFFF7C0ADruid|r |cRXP_WARN_or|r |T626006:0|t|cFF0070DDShaman|r |cRXP_WARN_friend you can skip this step and ask them to remove it for you|r"] = "|cRXP_WARN_Falls ihr einen|r |T626003:0|t|cFFF48CBADie Bruderschaft der Defias|r|cRXP_WARN_,|r |T625999:0|t|cFFFF7C0ADruide|r |cRXP_WARN_oder|r |T626006:0|t|cFF0070DDSchamane|r |cRXP_WARN_Freund habt, könnt ihr diesen Schritt überspringen und bittet ihn, es für euch zu entfernen|r",
        ["|cRXP_WARN_If you have a|r |T626003:0|t|cFFF48CBAPaladin|r|cRXP_WARN_,|r |T625999:0|t|cFFFF7C0ADruid|r |cRXP_WARN_or|r |T626006:0|t|cFF0070DDShaman|r |cRXP_WARN_friend, ask them to remove the|r |T136230:0|t[Touch of Zanzil] |cRXP_WARN_for you instead|r"] = "|cRXP_WARN_Falls ihr einen|r |T626003:0|t|cFFF48CBADie Bruderschaft der Defias|r|cRXP_WARN_,|r |T625999:0|t|cFFFF7C0ADruide|r |cRXP_WARN_oder|r |T626006:0|t|cFF0070DDSchamane|r |cRXP_WARN_Freund habt, bittet ihn, den|r |T136230:0|t[Berührung von Zanzil] |cRXP_WARN_für euch statt dessen zu entfernen|r",
        ["|cRXP_WARN_If you have any|r |T133717:0|t[Bombs]|cRXP_WARN_/|r[Grenades] |cRXP_WARN_you can also use them to split pull|r |cRXP_ENEMY_Ruuzel|r"] = "|cRXP_WARN_Wenn ihr irgendwelche|r |T133717:0|t[Bomben]|cRXP_WARN_/|r[Granaten] habt|cRXP_WARN_könnt ihr sie auch verwenden, um die Mobs zu trennen|r |cRXP_ENEMY_Ruuzel|r",
        ["|cRXP_WARN_If you just trained earlier, skip this step|r"] = "|cRXP_WARN_Wenn ihr gerade zuvor trainiert habt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you need more|r |T133970:0|t|cRXP_LOOT_[Chunks of Boar Meat]|r |cRXP_WARN_travel to the west near|r |cRXP_ENEMY_Bellygrub|r |cRXP_WARN_and kill more|r |cRXP_ENEMY_Great Goretusks|r"] = "|cRXP_WARN_Falls ihr mehr|r |T133970:0|t|cRXP_LOOT_[Brocken Eberfleisch]|r braucht |cRXP_WARN_reist nach Westen in die nähe von|r |cRXP_ENEMY_Stopfwanst|r |cRXP_WARN_und tötet mehr|r |cRXP_ENEMY_Großer Geiferzahn|r",
        ["|cRXP_WARN_If you see |cRXP_ENEMY_Xabraxxis|r yell in chat or see someone fighting him, help them. Open the |cRXP_PICK_Xabraxxis' Demon Bag|r he drops on the ground. Loot it for the|r |cRXP_LOOT_Talisman of Corruption|r"] = "|cRXP_WARN_Wenn ihr seht, dass |cRXP_ENEMY_Xabraxxis|r im Chat schreit, oder seht, dass jemand gegen ihn kämpft, helft ihnen. Öffnet |cRXP_PICK_Xabraxxis Dämonentasche|r, den er auf dem Boden fallen lässt. Plündert ihn für den|r |cRXP_LOOT_Talisman der Verderbnis|r",
        ["|cRXP_WARN_If you see a Tornado, touch it for 40% movement speed. Dealing damage removes the effect|r."] = "|cRXP_WARN_Falls ihr einen Tornado seht, berührt ihn für 40% Bewegungsgeschwindigkeit. Wenn ihr Schaden austeilt, wird der Effekt entfernt|r.",
        ["|cRXP_WARN_If you see|r |cRXP_FRIENDLY_Astor|r|cRXP_WARN_, talk to him and kill him. Loot him for the letter. He patrols the road between Brill and The Sepulcher|r"] = "|cRXP_WARN_Falls ihr|r |cRXP_FRIENDLY_Astor|r seht|cRXP_WARN_, sprecht mit ihm und tötet ihn. Plündert ihn für den Brief. Er patrouilliert die Straße zwischen Brill und dem Grabmal|r",
        ["|cRXP_WARN_If you spot a Tornado, approach it to gain 40% increased movement speed for 5 minutes. The effect ends if you deal damage|r."] = "|cRXP_WARN_Falls ihr einen Tornado seht, nähert euch ihm, um 40% erhöhte Bewegungsgeschwindigkeit für 5 Minuten zu erhalten. Der Effekt endet, wenn ihr Schaden austeilt|r.",
        ["|cRXP_WARN_If you time it correctly, you can cancel it midair to land in the building|r"] = "|cRXP_WARN_Wenn ihr es richtig zeitiert, könnt ihr es mitten in der Luft abbrechen und im Gebäude landen|r",
        ["|cRXP_WARN_If you walk through the orchard, watch out for stealthed bandits|r."] = "|cRXP_WARN_Falls ihr durch den Obstgarten geht, passt auf getarnte Banditen auf|r.",
        ["|cRXP_WARN_If you would rather purchase 5|r |T134187:0|t[Earthroot] |cRXP_WARN_from the Auction House later, skip this step|r"] = "|cRXP_WARN_Falls ihr lieber 5|r |T134187:0|t[Erdwurzel] |cRXP_WARN_später aus Auktionshaus kauft, überspringt diesen Schritt|r",
        ["|cRXP_WARN_If you're at the Tower of Azora simply run to Redridge|r"] = "|cRXP_WARN_Falls ihr am Turm von Azora seid, lauft einfach ins Rotkammgebirge|r",
        ["|cRXP_WARN_If you're in Goldshire it will be faster to Fly from Stormwind|r"] = "|cRXP_WARN_Falls ihr in Goldhain seid, ist es schneller, von Sturmwind zu fliegen|r",
        ["|cRXP_WARN_If you're planning on running the Hall of Thanes dungeon in Ironforge later, skip this step|r"] = "|cRXP_WARN_Falls ihr plant, Die Halle der Thanen in Eisenschmiede später zu besuchen, überspringt diesen Schritt|r",
        ["|cRXP_WARN_Ignore the Leyline; we'll deathskip shortly|r"] = "|cRXP_WARN_Ignoriert die Leylinie; wir werden bald einen Death-Skip machen|r",
        ["|cRXP_WARN_It has multiple spawn locations in the Lake|r"] = "|cRXP_WARN_Es kann an mehreren Orten im See spawnen|r",
        ["|cRXP_WARN_It has multiple spawn locations|r"] = "|cRXP_WARN_Es hat mehrere Spawnpunkte|r",
        ["|cRXP_WARN_It has two different spawn locations|r"] = "|cRXP_WARN_Es gibt zwei verschiedene Spawnpositionen|r",
        ["|cRXP_WARN_It is a dynamic respawn area meaning if you kill enough they will keep respawning|r"] = "|cRXP_WARN_Dies ist ein dynamisches Respawn-Gebiet, was bedeutet, dass die Gegner erneut erscheinen, wenn ihr genug von ihnen tötet|r",
        ["|cRXP_WARN_It is important to turn in this quest as soon as you get the|r |T133736:0|t[|cRXP_LOOT_Nibbled-On Book|r] |cRXP_WARN_drop|r"] = "|cRXP_WARN_Es ist wichtig, diese Quest abzugeben, sobald ihr|r |T133736:0|t[|cRXP_LOOT_Angeknabbertes Buch|r] |cRXP_WARN_erhaltet|r",
        ["|cRXP_WARN_It may spawn in different locations underwater|r"] = "|cRXP_WARN_Es kann an verschiedenen Orten unter Wasser spawnen|r",
        ["|cRXP_WARN_It will be in your spellbook|r"] = "|cRXP_WARN_Es wird sich in eurem Zauberbuch befinden|r",
        ["|cRXP_WARN_It's important to buy a non-shadow damage wand. You'll have to deal with mobs resistant to shadow damage later|r"] = "|cRXP_WARN_Es ist wichtig, einen Zauberstab ohne Schattenschaden zu kaufen. Später werdet ihr auf Gegner stoßen, die gegen Schattenschaden resistent sind.|r",
        ["|cRXP_WARN_Ivar is protected by two|r |cRXP_ENEMY_Ravenclaw Slaves|r |cRXP_WARN_inside the barn. You can solopull one of them as he patrols forward|r"] = "|cRXP_WARN_Ivar ist durch zwei|r |cRXP_ENEMY_Sklave von Rabenklaue|r |cRXP_WARN_in der Scheune geschützt. Ihr könnt eine von ihnen solo pullen, wenn sie nach vorne patrouilliert|r",
        ["|cRXP_WARN_Jump into the hut|r"] = "|cRXP_WARN_Springt in die Hütte|r",
        ["|cRXP_WARN_Jump into the Lake|r"] = "|cRXP_WARN_Springt in den See|r",
        ["|cRXP_WARN_Jump on top of the pillar above |cRXP_FRIENDLY_Bink|r, then walk slightly east of her onto the arrow position. Position your character until it looks like they're floating, then perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Springt auf den Pfeiler über |cRXP_FRIENDLY_Bink|r, dann lauft leicht östlich von ihr zur Pfeilposition. Positioniert Euren Charakter bis es aussieht, als würde er schweben, dann führt einen Logout Skip durch, indem ihr euch ausloggt und wieder einloggt|r",
        ["|cRXP_WARN_Jump on top of the rock on the top floor inside the cave. Position your character until it looks like they're floating, then perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Springt auf die Spitze des Felsens auf der oberen Ebene in der Höhle. Positioniert euren Charakter, bis er so aussieht, als würde er schweben, und führt dann einen Logout-Skip durch, indem ihr euch aus- und wieder einloggt|r",
        ["|cRXP_WARN_Jump onto the ship, go down to the 2nd floor and level your lockpicking up to at least 70|r"] = "|cRXP_WARN_Springt aufs Schiff, geht zur 2. Etage hinunter und trainiert euer Schlösser knacken bis mindestens 70|r",
        ["|cRXP_WARN_Jump onto the top of the weapon stand. Perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Springt auf die Spitze des Waffenständers. Führt einen Ausloggen-Überspringen skip durch, indem ihr euch abmeldet und wieder anmeldet|r",
        ["|cRXP_WARN_Keep at least 3 Small Eggs for a later quest|r"] = "|cRXP_WARN_Behaltet mindestens 3 Kleine Eier für eine spätere Quest.|r",
        ["|cRXP_WARN_Keep in mind this is a timed quest, you need to turn it in within 10 minutes of accepting|r"] = "|cRXP_WARN_Denkt daran, dass dies eine zeitgesteuerte Quest ist. Ihr müsst sie innerhalb von 10 Minuten abgeben|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mindless Zombies|r and |cRXP_ENEMY_Wretched Zombies|r. Loot them until you have 25 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Hirnloser Zombie|r und |cRXP_ENEMY_Elender Zombie|r. Plündert sie, bis ihr 25 Kupfer wert an Händler-Gegenständen (einschließlich eurer Rüstung) habt|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mindless Zombies|r and |cRXP_ENEMY_Wretched Zombies|r. Loot them until you have 33 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Hirnloser Zombie|r und |cRXP_ENEMY_Elender Zombie|r. Plündert sie, bis ihr 33 Kupfer wert an Händler-Gegenständen (einschließlich eurer Rüstung) habt|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mottled Boars|r. Loot them until you have 10 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Scheckiger Eber|r. Sammelt Beute von ihnen bis ihr 10 Kupfer Wert an Verkaufsgegenständen habt (einschließlich eurer Rüstung)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mottled Boars|r. Loot them until you have 35 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Scheckiger Eber|r. Sammelt Beute von ihnen bis ihr 35 Kupfer Wert an Verkaufsgegenständen habt (einschließlich eurer Rüstung)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mottled Boars|r. Loot them until you have 50 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Scheckiger Eber|r. Sammelt Beute von ihnen bis ihr 50 Kupfer Wert an Verkaufsgegenständen habt (einschließlich eurer Rüstung)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Mottled Boars|r. Loot them until you have 60 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Scheckiger Eber|r. Sammelt Beute von ihnen bis ihr 60 Kupfer Wert an Verkaufsgegenständen habt (einschließlich eurer Rüstung)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Plainstriders|r. Loot them until you have 10 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Ebenenschreiter|r. Plündert sie, bis ihr 10 Kupfer an Verkaufsgegenständen habt (einschließlich eurer Rüstung)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Young Scavengers|r and |cRXP_ENEMY_Duskbats|r. Loot them until you have 10 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Junger Aasfresser|r und |cRXP_ENEMY_Nachtsauger|r. Plündert sie, bis ihr Gegenstände im Wert von 10 Kupfer habt (einschließlich der rüstung von Euch)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Young Scavengers|r and |cRXP_ENEMY_Duskbats|r. Loot them until you have 50 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Junger Aasfresser|r und |cRXP_ENEMY_Nachtsauger|r. Plündert sie, bis ihr Gegenstände im Wert von 50 Kupfer habt (einschließlich der rüstung von Euch)|r",
        ["|cRXP_WARN_Kill |cRXP_ENEMY_Young Scavengers|r and |cRXP_ENEMY_Duskbats|r. Loot them until you have 60 copper worth of vendor items (including your armor)|r"] = "|cRXP_WARN_Tötet |cRXP_ENEMY_Junger Aasfresser|r und |cRXP_ENEMY_Nachtsauger|r. Plündert sie, bis ihr Gegenstände im Wert von 60 Kupfer habt (einschließlich der rüstung von Euch)|r",
        ["|cRXP_WARN_Kill and loot |cRXP_ENEMY_Ragged Young Wolves|r until you have 10 copper or more of vendor trash|r"] = "|cRXP_WARN_Tötet und plündert|cRXP_ENEMY_ Struppiger junger Wolf|r, bis ihr 10 Kupfermünzen oder mehr Händler-Schrott habt|r",
        ["|cRXP_WARN_Kill the imp first. Use|r |T132155:0|t[Gouge] |cRXP_WARN_when he casts|r |T136169:0|t[Soul Siphon]"] = "Tötet|cRXP_WARN_ den Wichtel zunächst. Benutzt|r |T132155:0|t[Solarplexus] |cRXP_WARN_wenn er|r |T136169:0|t[Seelenentzug] wirkt",
        ["|cRXP_WARN_Kill the imp first. Use|r |T136026:0|t[Earth Shock] |cRXP_WARN_when he casts|r |T136169:0|t[Soul Siphon]"] = "Tötet|cRXP_WARN_ den Wichtel zunächst. Benutzt|r |T136026:0|t[Erdschock] |cRXP_WARN_wenn er|r |T136169:0|t[Seelenentzug] wirkt",
        ["|cRXP_WARN_Kill the imp first|r"] = "|cRXP_WARN_Tötet den Wichtel zuerst|r",
        ["|cRXP_WARN_Kite |cRXP_ENEMY_Bellygrub|r back to Lakeshire so the |cRXP_FRIENDLY_Guards|r assist you in killing|r |cRXP_ENEMY_Bellygrub|r"] = "|cRXP_WARN_Zieht |cRXP_ENEMY_Stopfwanst|r nach Seenhain, damit die |cRXP_FRIENDLY_Wachen|r euch beim Töten von |rStopfwanst|cRXP_ENEMY_ helfen|r",
        ["|cRXP_WARN_Kite |cRXP_ENEMY_Vagash|r down to|r |cRXP_FRIENDLY_Rudra|r"] = "|cRXP_WARN_Lockt |cRXP_ENEMY_Vagash|r zu|r |cRXP_FRIENDLY_Rudra|r",
        ["|cRXP_WARN_Kite a |cRXP_ENEMY_Young Forest Bear|r toward|r |cRXP_FRIENDLY_Guard Thomas|r"] = "|cRXP_WARN_Zieht einen |cRXP_ENEMY_Junger Waldbär|r zu|r |cRXP_FRIENDLY_Wache Thomas|r",
        ["|cRXP_WARN_Kite him back to the guard tower if required ensuring you've done at least 50% damage to him|r"] = "|cRXP_WARN_Lockt ihn zurück zum Wachturm, falls nötig, und stellt sicher, dass ihr mindestens 50% Schaden angerichtet habt|r",
        ["|cRXP_WARN_Kite him to the guard south of the ranch. Make sure you do 51%+ damage to him|r"] = "|cRXP_WARN_Lockt ihn zur Wache südlich der Ranch. Achtet darauf, dass ihr 51%+ Schaden an ihm verursacht|r",
        ["|cRXP_WARN_Level up your|r |T133971:0|t[Cooking] |cRXP_WARN_using the|r |T133970:0|t|cRXP_LOOT_[Chunks of Boar Meat]|r |cRXP_WARN_you farmed earlier. You need level 50|r |T133971:0|t[Cooking]"] = "|cRXP_WARN_Level up eure|r |T133971:0|t[Kochkunst] |cRXP_WARN_benutzt die|r |T133970:0|t|cRXP_LOOT_[Brocken Eberfleisch]|r |cRXP_WARN_welche ihr vorher gefarmt habt. Ihr braucht 50|r |T133971:0|t[Kochkunst]",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_if needed while waiting for the tram|r"] = "|cRXP_WARN_Levelt eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_falls erforderlich, während ihr auf die Straßenbahn wartet|r",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_to 80|r"] = "|cRXP_WARN_Steigert eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_auf 80|r",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_while waiting for the boat to Darkshore if needed|r"] = "|cRXP_WARN_Levelt eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_während ihr auf das Boot nach Dunkelküste wartet, falls nötig|r",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_while waiting for the boat|r"] = "|cRXP_WARN_Levelt eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_während ihr auf das Boot wartet|r",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_while waiting for the Tram to Ironforge if needed|r"] = "|cRXP_WARN_Verbessert eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_während ihr auf die Tiefenbahn wartet, falls erforderlich|r",
        ["|cRXP_WARN_Level your|r |T135966:0|t[First Aid] |cRXP_WARN_while waiting for the Tram to Stormwind City if needed|r"] = "|cRXP_WARN_Levelt eure|r |T135966:0|t[Erste Hilfe] |cRXP_WARN_auf, während ihr auf die Tiefenbahn nach Sturmwind wartet, falls nötig|r",
        ["|cRXP_WARN_Level your|r |T136065:0|t[Herbalism] |cRXP_WARN_to 15 to be able to gather 5|r |T134187:0|t[Earthroot] |cRXP_WARN_for an important class quest soon. You can unlearn it afterwards|r"] = "|cRXP_WARN_Erhöht eure|r |T136065:0|t[Kräuterkunde] |cRXP_WARN_auf 15, um 5|r |T134187:0|t[Erdwurzel] |cRXP_WARN_für eine wichtige Klassenquest später zu sammeln. Ihr könnt es danach wieder verlernen|r",
        ["|cRXP_WARN_Level your|r |T136065:0|t[Herbalism] |cRXP_WARN_to 15 to be able to herb|r |T134187:0|t[Earthroot] |cRXP_WARN_for an important class quest soon. You can unlearn it afterwards|r"] = "|cRXP_WARN_Erhöht eure|r |T136065:0|t[Kräuterkunde] |cRXP_WARN_auf 15, um |r |T134187:0|t[Erdwurzel] |cRXP_WARN_für eine wichtige Klassenquest in kürze zu sammeln. Du kannst es hinterher wieder verlernen|r",
        ["|cRXP_WARN_Look for a group to kill it or skip the quest; respawns are lengthy|r."] = "|cRXP_WARN_Sucht nach einer Gruppe um es zu töten oder überspringt die Quest; die Respawns sind lange|r.",
        ["|cRXP_WARN_Look for her from a distance or follow her dialogue; the arrow marks only an approximate location|r."] = "|cRXP_WARN_Sucht sie aus der Ferne oder folgt ihrem Dialog; der Pfeil markiert nur einen ungefähren Ort|r.",
        ["|cRXP_WARN_Loot the|r |T134095:0|t[Flawed Power Stone] |cRXP_WARN_next to|r |cRXP_FRIENDLY_Ak'Zeloth|r|cRXP_WARN_. This item has a 30 minute timer, so be sure to be quick|r"] = "|cRXP_WARN_Plündert den|r |T134095:0|t[Fehlerhaften Kraftstein] |cRXP_WARN_neben|r |cRXP_FRIENDLY_Ak'zeloth|r|cRXP_WARN_. Dieser Gegenstand hat einen 30-Minuten-Timer, daher müsst ihr schnell sein|r",
        ["|cRXP_WARN_Loot them for valuable vendor trash to help pay for weapon upgrades and class training|r."] = "|cRXP_WARN_Plündert sie für wertvollen Händlerschrott, um Waffenverbesserungen und Klassentraining zu finanzieren|r.",
        ["|cRXP_WARN_Looting this will spawn 2 |cRXP_ENEMY_Blackwood Furbolgs|r that will aggro and run towards you. Be ready to fight them or reset them|r"] = "|cRXP_WARN_Das Plündern davon wird 2 |cRXP_ENEMY_Furbolg der Schwarzfelle|r spawnen, die euch angreifen und auf euch zulaufen. Seid bereit, gegen sie zu kämpfen oder setzt sie zurück|r",
        ["|cRXP_WARN_Make sure that you have 1 silver leftover after leaving the vendor to be able to afford|r |T132204:0|t[|cRXP_FRIENDLY_Serpent Sting|r]"] = "|cRXP_WARN_stellt sicher, dass ihr 1 Silber übrig habt, nachdem ihr den Händler verlasst, um|r |T132204:0|t[|cRXP_FRIENDLY_Schlangenbiss|r] bezahlen zu können",
        ["|cRXP_WARN_Make sure that you have at least 1 silver 2 copper worth of vendor trash|r, you can count your staff that vendors for 9c"] = "|cRXP_WARN_Stellt sicher, dass ihr mindestens 1 Silber 2 Kupfer an Händlermüll habt|r, ihr könnt eure Gegenstände zählen, die 9 Kupfer wert sind",
        ["|cRXP_WARN_Make sure the timer does not run out|r"] = "|cRXP_WARN_Stellt sicher, dass der Timer nicht abläuft|r",
        ["|cRXP_WARN_Make sure to deal 51%+ damage to get credit|r"] = "|cRXP_WARN_Stellt sicher, dass ihr 51%+ Schaden verursacht, um Questfortschritt zu erhalten|r",
        ["|cRXP_WARN_Make sure you check if |cRXP_ENEMY_Murkdeep|r is already up in the water (if someone has previously failed the encounter or left the |cRXP_ENEMY_Greymist Hunter|r in the wave that he spawns with alive)|r"] = "|cRXP_WARN_Stellt sicher, dass ihr überprüft, ob |cRXP_ENEMY_Gurgelbacke|r bereits im Wasser ist (wenn der Kampf zuvor fehlgeschlagen ist oder ihr den |cRXP_ENEMY_Jäger der Grauflossen|r in der Welle, in der er spawnt, am Leben gelassen habt)|r",
        ["|cRXP_WARN_Make sure you deal at least 50% damage to him|r"] = "|cRXP_WARN_Stellt sicher, dass ihr mindestens 50% Schaden anrichtet|r",
        ["|cRXP_WARN_Make sure you have 1 empty bagspace slot before accepting this quest|r"] = "|cRXP_WARN_Stellt sicher, dass ihr 1 freien Inventarplatz habt, bevor ihr diese Quest annehmt|r",
        ["|cRXP_WARN_Make sure you have 10|r |T132889:0|t[Linen Cloth] |cRXP_WARN_in your bag|r"] = "|cRXP_WARN_Stellt sicher, dass ihr 10|r |T132889:0|t[Leinenstoff] |cRXP_WARN_im Beutel habt|r",
        ["|cRXP_WARN_Make sure you have a|r |T134095:0|t[Flawed Power Stone] |cRXP_WARN_(30 minute duration) on you|r"] = "|cRXP_WARN_Stellt sicher, dass ihr einen|r |T134095:0|t[Fehlerhafter Kraftstein] |cRXP_WARN_(30 Minuten Dauer) bei euch habt|r",
        ["|cRXP_WARN_Make sure you have|r |T134916:0|t[Find Herbs] |cRXP_WARN_enabled to see them on the minimap|r"] = "|cRXP_WARN_Stellt sicher, dass ihr|r |T134916:0|t[Kräutersuche] |cRXP_WARN_aktiviert habt, um sie auf der Minikarte zu sehen|r",
        ["|cRXP_WARN_Make sure you save 10c or more for later|r"] = "|cRXP_WARN_Behaltet 10c oder mehr für später|r",
        ["|cRXP_WARN_Make sure you save 10s for training later|r"] = "|cRXP_WARN_Sorgt dafür, dass ihr 10s für späteres Training spart|r",
        ["|cRXP_WARN_Make sure you save 6s for training later|r"] = "|cRXP_WARN_Sorgt dafür, dass ihr 6s für späteres Training spart|r",
        ["|cRXP_WARN_Make sure you're on the west side of the river or you might end up going the wrong way|r"] = "|cRXP_WARN_Achtet darauf, dass ihr auf der Westseite des Flusses seid, sonst könnt ihr auf dem falschen Friedhof landen|r",
        ["|cRXP_WARN_Make sure your subzone is NOT Coldridge Pass|r"] = "|cRXP_WARN_Stellt sicher, dass eure zone nicht Eisklamm ist|r",
        ["|cRXP_WARN_Manually|r |T132320:0|t[Unstealth]|cRXP_WARN_, then press your \"Interact with Target\" keybind to open the |cRXP_PICK_Duskwood Chest|r. Loot it for|r |cRXP_LOOT_Klaven Mortwake's Journal|r"] = "|cRXP_WARN_Stoppt manuell|r |T132320:0|t[Verstohlenheit]|cRXP_WARN_, dann drückt von Euch \"Interagieren mit Ziel\" Taste, um das |cRXP_PICK_Dämmerwaldtruhe|r zu öffnen. Plündert sie für|r |cRXP_LOOT_Klaven Mortwakes Tagebuch|r",
        ["|cRXP_WARN_Move or press ESC to cancel|r."] = "|cRXP_WARN_Bewegt euch oder drückt ESC zum Abbrechen|r.",
        ["|cRXP_WARN_Move to the Bonfire in the center of the camp to start the |cRXP_ENEMY_Murkdeep|r encounter:|r"] = "|cRXP_WARN_Bewegt euch zum Freudenfeuer in der Mitte des Lagers, um den |cRXP_ENEMY_Gurgelbacke|r-Kampf zu beginnen:|r",
        ["|cRXP_WARN_NOTE: This can spawn in one of many different locations. Swim around until you see the exclamation point on your minimap|r"] = "|cRXP_WARN_HINWEIS: Dies kann an vielen verschiedenen Orten erscheinen. Schwimmt herum, bis ihr das Ausrufezeichen auf eurer Minikarte seht|r",
        ["|cRXP_WARN_NOTE: This item has a low drop rate. Skip this step if you do not find it by the time you are done with the|r |cRXP_ENEMY_Dark Iron Spies|r"] = "|cRXP_WARN_HINWEIS: Dieser Gegenstand hat eine niedrige Droprate. Überspringt diesen Schritt, wenn ihr ihn nicht findet, bis ihr mit den|r Spione der Dunkeleisenzwerge|cRXP_ENEMY_ fertig seid|r",
        ["|cRXP_WARN_NOTE: This item has a low drop rate. Skip this step if you do not find it|r"] = "|cRXP_WARN_HINWEIS: Dieser Gegenstand hat eine niedrige Drop-Rate. Überspringt diesen Schritt, wenn ihr es nicht findet|r",
        ["|cRXP_WARN_NOTE: Your|r |T132320:0|t[Stealth] |cRXP_WARN_will temporarily stop working after looting|r |cRXP_LOOT_Klaven Mortwake's Journal|r"] = "|cRXP_WARN_NOTIZ: Eure|r |T132320:0|t[Verstohlenheit] |cRXP_WARN_wird kurz nachdem ihr gelootet habt nicht funktionieren|r |cRXP_LOOT_Klaven Mortwakes Tagebuch|r",
        ["|cRXP_WARN_NOTE:|r If all crabs are dead then you can also tame an |cRXP_ENEMY_Ornery Galestrider::251707|r until you find a crab."] = "|cRXP_WARN_HINWEIS:|r Falls alle Krebse tot sind, könnt ihr auch einen |cRXP_ENEMY_Ornery Galestrider::251707|r zähmen, bis ihr einen Krebs findet.",
        ["|cRXP_WARN_NOTE:|r This quest is |cRXP_WARN_OPTIONAL|r. Skip this step if the crabs are too contested."] = "|cRXP_WARN_HINWEIS:|r Diese Quest ist |cRXP_WARN_OPTIONAL|r. Überspringt diesen Schritt, falls die Krabben zu sehr umstritten sind.",
        ["|cRXP_WARN_NOTE:|r This quest is optional. You can skip it when there are too many people doing it."] = "|cRXP_WARN_HINWEIS:|r Diese Quest ist optional. Ihr könnt sie überspringen, wenn zu viele Spieler sie ausführen.",
        ["|cRXP_WARN_Obtain an|r |T134059:0|t[E.C.A.C.] |cRXP_WARN_and a|r |T134065:0|t[Thieves' Tools]"] = "|cRXP_WARN_Besorgt einen|r |T134059:0|t[R.C.V.K.] |cRXP_WARN_und einen|r |T134065:0|t[Diebeswerkzeug]",
        ["|cRXP_WARN_On a highly populated server or fresh launch, your best option is camping his spawnpoint|r"] = "|cRXP_WARN_Auf einem stark bevölkerten Server oder bei einem frischen Start ist es am besten, an seinem Spawn-Punkt zu campen.|r",
        ["|cRXP_WARN_On the arrow location, press your \"Interact with Target\" keybind to loot the |cRXP_LOOT_Mist Veil's Lockbox|r from outside the boat|r"] = "|cRXP_WARN_Am Ort des Pfeils drückt eure Mit Ziel interagieren keybind, um die |cRXP_LOOT_Schließkassette der NEBELSCHLEIER|r von außen zu plündern|r",
        ["|cRXP_WARN_On the arrow location, press your \"Interact with Target\" keybind to loot the |cRXP_LOOT_Silver Dawning's Lockbox|r from outside the boat|r"] = "|cRXP_WARN_Drückt euren \"Interagieren mit Ziel\"-Hotkey am Ort mit dem Pfeil, um die |cRXP_LOOT_Schließkassette der SILBERMORGEN|r von außerhalb des Bootes zu plündern|r",
        ["|cRXP_WARN_On the Boat if it just arrived or on the dock if the boat just left:|r"] = "|cRXP_WARN_Auf dem Boot, wenn es gerade angekommen ist, oder am Dock, wenn das Boot gerade abgefahren ist:|r",
        ["|cRXP_WARN_On the Tram when it arrives:|r"] = "|cRXP_WARN_Auf der Tiefenbahn, wenn sie ankommt:|r",
        ["|cRXP_WARN_Once you have 50c worth of vendor trash:|r"] = "|cRXP_WARN_Bis ihr 50c Wert an Müll habt:|r",
        ["|cRXP_WARN_Once you reach this xp breakpoint, skip the harpy/escort quest and go straight to Darnassus. You will have another opportunity to finish those quests later|r"] = "|cRXP_WARN_Sobald ihr diese XP-Schwelle erreicht, überspringt die Harpyien-/Eskorte-Quest und geht direkt nach Darnassus. Ihr werdet eine weitere Gelegenheit haben, diese Quests später zu machen|r",
        ["|cRXP_WARN_One mob will spawn after you shut off the Valve|r"] = "|cRXP_WARN_Ein Mob wird spawnen, nachdem ihr das Ventil ausgeschaltet habt|r",
        ["|cRXP_WARN_Only train|r |T132147:0|t[Dual Wield] |cRXP_WARN_and|r |T132307:0|t[Sprint]"] = "|cRXP_WARN_Trainiert nur|r |T132147:0|t[Beidhändigkeit] |cRXP_WARN_und|r |T132307:0|t[Sprinten]",
        ["|cRXP_WARN_Only train|r |T132147:0|t[Dual Wield] |cRXP_WARN_and|r |T132307:0|t[Sprint]|cRXP_WARN_. Do not train other spells to save your money for later|r"] = "|cRXP_WARN_Trainiert nur|r |T132147:0|t[Beidhändigkeit] |cRXP_WARN_und|r |T132307:0|t[Sprinten] |cRXP_WARN_. Trainiert keine anderen Zauber, um das Geld für später zu sparen|r",
        ["|cRXP_WARN_Open the |cRXP_PICK_Practice Lockboxes|r on the ground in Alther's Mill until your|r |T136058:0|t[Lockpicking] skill is 80|r"] = "|cRXP_WARN_Öffnet die |cRXP_PICK_Übungsschließkassette|r am Boden in Althers Mühle, bis euer|r |T136058:0|t[Schlossknacken] 80 erreicht|r",
        ["|cRXP_WARN_Otherwise, you may be sent to a different graveyard|r"] = "|cRXP_WARN_Ansonsten könnt ihr zu einem anderen Friedhof geschickt werden|r",
        ["|cRXP_WARN_Perform a Logout Skip by positioning your character on the edge of the rock until it looks like they're floating, then logging out and back in|r"] = "|cRXP_WARN_Führt einen Logout-Skip durch, indem ihr den Charakter von Euch an der Kante des Steins positioniert, bis es aussieht, als würde er schweben, dann loggt euch aus und wieder ein|r",
        ["|cRXP_WARN_Perform a Logout Skip by positioning your character on the highest part of the lowest staircase until it looks like they're floating, then logging out and back in|r"] = "|cRXP_WARN_Führt einen Logout-Skip durch: Positioniert den Character von Euch auf der höchsten Stelle der niedrigsten Treppenstufe, bis er zu schweben scheint. Meldet euch dann ab und wieder an|r",
        ["|cRXP_WARN_Perform a Logout Skip inside the cave by jumping on top of a shredder, well, or the wooden plank stuck in the wall, then log out and back in|r"] = "|cRXP_WARN_Führt einen Logout-Skip in der Höhle durch, indem ihr auf einen Shredder, einen Brunnen oder die in der Wand steckende Holzplanke springt, dann meldet euch ab und wieder an|r",
        ["|cRXP_WARN_Pool 100 Rage before you engage|r |cRXP_ENEMY_Princess|r"] = "|cRXP_WARN_Sammelt 100 Wut, bevor ihr gegen |rPrinzessin|cRXP_ENEMY_ kämpft|r",
        ["|cRXP_WARN_Pool 100 Rage. Pull the 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_in front of the huts, move away and keep|r |T132316:0|t[Hamstring] |cRXP_WARN_on one whilst killing the other. Also use|r |T133581:0|t[Bag of Marbles] |cRXP_WARN_on the one you're killing. Run away and reset the one being kited with|r |T132316:0|t[Hamstring] |cRXP_WARN_after you've killed one|r"] = "|cRXP_WARN_Sammelt 100 Wut. Zieht die 2|r Murlocs|cRXP_ENEMY_ vor den Hütten, bewegt euch weg und haltet|r |T132316:0|t[Kniesehne] |cRXP_WARN_auf einem aktiv,während ihr den anderen tötet. Benutzt auch|r |T133581:0|t[Tasche mit Murmeln] |cRXP_WARN_auf den, den ihr tötet. Lauft weg und|r |cRXP_WARN_setzt den einen den ihr mit|r |T132316:0|t[Kniesehne] |cRXP_WARN_zurück gezogen habt zurück, nachdem ihr den anderern getötet habt|r",
        ["|cRXP_WARN_Press ESCAPE to cancel the Farsight|r"] = "|cRXP_WARN_Drückt ESC, um die Fernsicht abzubrechen|r",
        ["|cRXP_WARN_Press Escape, then go into -> Options -> Controls|r"] = "|cRXP_WARN_Drückt Escape, dann geht in -> Optionen -> Steuerung|r",
        ["|cRXP_WARN_Press the Macro in the \"Active Items Frame\" to craft|r |T133685:0|t[Linen Bandages] for a later quest."] = "|cRXP_WARN_Drückt das Makro im \"Aktiv Gegenstände Frame\", um herzustellen|r |T133685:0|t[Linen Bandages] für eine spätere Quest.",
        ["|cRXP_WARN_Prioritize |cRXP_ENEMY_Roiling Winds::251143|r|r"] = "|cRXP_WARN_Priorisiert |cRXP_ENEMY_Roiling Winde::251143|r|r",
        ["|cRXP_WARN_Prioritize killing any |cRXP_ENEMY_Young Forest Bears|r you see|r"] = "|cRXP_WARN_Priorisiert das Töten jedes |cRXP_ENEMY_Junger Waldbär|r, den ihr seht|r",
        ["|cRXP_WARN_Prioritize the |cRXP_ENEMY_Matriarch::251261|r|r"] = "|cRXP_WARN_Priorisiert |cRXP_ENEMY_Matriarchin::251261|r|r",
        ["|cRXP_WARN_Prioritize them|r"] = "|cRXP_WARN_Priorisiert sie|r",
        ["|cRXP_WARN_Prioritize training|r |T132147:0|t[Dual Wield]"] = "|cRXP_WARN_Priorisiert das lernen von|r |T132147:0|t[Beidhändigkeit]",
        ["|cRXP_WARN_Pull him backwards towards the|r |cRXP_ENEMY_Lightning Hides|r |cRXP_WARN_you just killed. Otherwise you may bodypull additional Burning Blade mobs|r"] = "|cRXP_WARN_Zieht ihn rückwärts zu den|r |cRXP_ENEMY_Donnerechsen|r |cRXP_WARN_die ihr gerade besiegt habt. Andernfalls könnt ihr versehentlich zusätzliche Burning Blade Gegner anziehen.|r",
        ["|cRXP_WARN_Pull the 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_in front of the huts, move away and cast|r |T136183:0|t[Fear] |cRXP_WARN_on one of them constantly, and try to keep DoTs on both|r"] = "|cRXP_WARN_Zieht die 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_vor den Hütten, bewegt euch weg und|r |T136183:0|t[Furcht] |cRXP_WARN_wirkt auf einen von ihnen ständig, und versucht, DoTs auf beide zu halten|r",
        ["|cRXP_WARN_Pull the 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_in front of the huts, move away and focus killing one of them. Use|r |T136205:0|t[Evasion] |cRXP_WARN_once they're both attacking you. This is a good opportunity to use|r |T133581:0|t[Bag of Marbles]|cRXP_WARN_. Run away and reset once you've killed one|r"] = "|cRXP_WARN_Zieht die 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_vor den Hütten, bewegt euch weg und konzentriert euch auf das Töten eines Murlocs. Benutzt|r |T136205:0|t[Entrinnen] |cRXP_WARN_sobald beide euch angreifen. Dies ist eine gute Gelegenheit,|r |T133581:0|t[Tasche mit Murmeln]|cRXP_WARN_zu benutzen. Lauft weg und setzt den Kampf zurück, sobald ihr einen getötet habt|r",
        ["|cRXP_WARN_Pull the 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_in front of the huts, move away and nuke one of them down fast. Use|r |T135954:0|t[Divine Protection] |cRXP_WARN_and your Heals as required. This is a good opportunity to use|r |T133581:0|t[Bag of Marbles]|cRXP_WARN_. Run away and reset once you've killed one|r"] = "|cRXP_WARN_Zieht die 2|r Murlocs|cRXP_ENEMY_ vor den Hütten, bewegt euch weg und tötet einen sehr schnell. Benutzt|r |T135954:0|t[Göttlicher Schutz] |cRXP_WARN_und eure Heilungen wie erforderlich. Dies ist eine gute Gelegenheit|r |T133581:0|t[Tasche mit Murmeln] zu benutzen|cRXP_WARN_. Lauft weg und|r |cRXP_WARN_setzt den einen den ihr kitet zurück nachdem ihr einen getötet habt|r",
        ["|cRXP_WARN_Pull the 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_in front of the huts, move away and|r |T136071:0|t[Polymorph] |cRXP_WARN_one whilst killing the other. Kill the|r |T136071:0|t[Polymorphed] |cRXP_WARN_one after|r"] = "|cRXP_WARN_Zieht die 2|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_vor den Hütten, bewegt euch weg und|r |T136071:0|t[Verwandlung] |cRXP_WARN_einen, während ihr den anderen tötet. Tötet den|r |T136071:0|t[Verwandelt]|cRXP_WARN_ danach|r",
        ["|cRXP_WARN_Put|r |T132162:0|t[Beast Training]|cRXP_WARN_(under the General tab),|r |T132163:0|t[Revive Pet]|cRXP_WARN_, and|r |T132165:0|t[Feed Pet] |cRXP_WARN_onto your Action Bars|r"] = "|cRXP_WARN_Legt|r |T132162:0|t[Wildtierausbildung]|cRXP_WARN_(unter dem Allgemein-Reiter),|r |T132163:0|t[Tier wiederbeleben]|cRXP_WARN_, und|r |T132165:0|t[Tier füttern] |cRXP_WARN_auf eure Aktionsleisten|r",
        ["|cRXP_WARN_Put|r |T132164:0|t[Tame Beast]|cRXP_WARN_,|r |T136095:0|t[Dismiss Pet]|cRXP_WARN_, and|r |T132161:0|t[Call Pet] |cRXP_WARN_onto your Action Bars|r"] = "|cRXP_WARN_Zieht|r |T132164:0|t[Wildtier zähmen]|cRXP_WARN_,|r |T136095:0|t[Tier freigeben]|cRXP_WARN_, und|r |T132161:0|t[Begleiter rufen] |cRXP_WARN_in eure Aktionsleisten|r",
        ["|cRXP_WARN_Put|r |T132363:0|t[Sunder Armor] |cRXP_WARN_on your action bar and ensure to use it constantly. It is more effective than using|r |T132282:0|t[Heroic Strike]"] = "|cRXP_WARN_Legt|r |T132363:0|t[Rüstung zerreißen] |cRXP_WARN_auf die Aktionsleiste von Euch und stellt sicher, dass ihr es ständig benutzt. Es ist effektiver als die Verwendung von|r |T132282:0|t[Heldenhafter Stoß]",
        ["|cRXP_WARN_Refresh|r |T236219:0|t[Read Ley Line] |cRXP_WARN_near the Leyline|r"] = "|cRXP_WARN_Auffrischen|r |T236219:0|t[Lesen Leylinie] |cRXP_WARN_nahe der Leylinie|r",
        ["|cRXP_WARN_Remember during|r |T135954:0|t[Divine Protection] |cRXP_WARN_you are unable to attack|r"] = "|cRXP_WARN_Denkt daran, während|r |T135954:0|t[Göttlicher Schutz] |cRXP_WARN_aktiv ist,könnt ihr nicht angreifen|r",
        ["|cRXP_WARN_Remember to equip the|r |T135425:0|t[Keen Throwing Knives] |cRXP_WARN_when you are level 11|r"] = "|cRXP_WARN_Vergesst nicht, die |r|T135425:0|t[Beißendes Wurfmesser] |cRXP_WARN_auszurüsten, wenn ihr Stufe 11 seid|r",
        ["|cRXP_WARN_Remember to equip the|r |T135468:0|t[Smoldering Wand] |cRXP_WARN_later when you reach level 15|r"] = "|cRXP_WARN_Vergesst nicht, den|r |T135468:0|t[Glimmender Zauberstab] |cRXP_WARN_später auszurüsten, wenn ihr Stufe 15 erreicht|r",
        ["|cRXP_WARN_Remember to re-equip your main weapon if you switched to a|r |T135641:0|t[Dagger] |cRXP_WARN_earlier|r"] = "|cRXP_WARN_Erinnert euch, wieder auf eure Hauptwaffe zu wechseln, sofern ihr sie durch einen|r |T135641:0|t[Dolch] |cRXP_WARN_gewechselt habt|r",
        ["|cRXP_WARN_Remember to reapply this food buff when it expires|r"] = "|cRXP_WARN_Denkt daran, diesen Essensbuff erneut anzuwenden, wenn er abläuft|r",
        ["|cRXP_WARN_Remember to train your pet whenever they get Training Points for|r |T132162:0|t[Beast Training]"] = "|cRXP_WARN_Erinnert euch daran, euer tier zu trainieren, wenn es Trainingspunkte für|r |T132162:0|t[Wildtierausbildung] erhält",
        ["|cRXP_WARN_Repeatedly cast|r |T136071:0|t[Polymorph] |cRXP_WARN_and use the swatter on the same Flutterfly for extra dust|r."] = "|cRXP_WARN_Wirkt wiederholt|r |T136071:0|t[Verwandlung] |cRXP_WARN_und benutzt die Fliegenklatsche auf dem gleichen Flutterfly für zusätzlichen Staub|r.",
        ["|cRXP_WARN_Run away and reset the |cRXP_ENEMY_Murlocs|r after completing the quest|r"] = "|cRXP_WARN_Lauft weg und setzt die |cRXP_ENEMY_Murlocs|r zurück, nachdem ihr die Quest abgeschlossen habt|r",
        ["|cRXP_WARN_Run on top of |cRXP_PICK_Rolf's corpse|r, then cast|r |T135954:0|t[Divine Protection] |cRXP_WARN_and then immediately click|r |cRXP_PICK_Rolf's corpse|r"] = "|cRXP_WARN_Rennt auf |cRXP_PICK_Rolfs Leichnam|r, wirkt dann|r |T135954:0|t[Göttlicher Schutz] |cRXP_WARN_und klickt sofort|r |cRXP_PICK_Rolfs Leichnam|r",
        ["|cRXP_WARN_Run up the dirt path then drop down into the bunker|r"] = "|cRXP_WARN_Lauft den Erdpfad hinauf, dann springt in den Bunker|r",
        ["|cRXP_WARN_Save 10|r |T132889:0|t[Linen Cloth] |cRXP_WARN_for a quest later. Make sure you do not sell it|r"] = "|cRXP_WARN_Behaltet 10|r |T132889:0|t[Leinenstoff] |cRXP_WARN_für eine Quest später. Stellt sicher, dass ihr es nicht verkauft|r",
        ["|cRXP_WARN_Save 2 silver for your class spells!|r"] = "|cRXP_WARN_Behaltet 2 Silber für eure Klassenzauber!|r",
        ["|cRXP_WARN_Save 4 silver for your class spells!|r"] = "|cRXP_WARN_Behaltet 4 Silber für eure Klassenzauber!|r",
