        ["|cRXP_WARN_Save any|r |T133970:0|t|cRXP_LOOT_[Chunks of Boar Meat]|r |cRXP_WARN_you loot as well as you can use them to level|r |T133971:0|t[Cooking] |cRXP_WARN_to 50 which is required for Duskwood later|r"] = "|cRXP_WARN_Sichert jeden|r |T133970:0|t|cRXP_LOOT_[Brocken Eberfleisch]|r |cRXP_WARN_, den ihr plündert, da ihr ihn zum Leveln von|r |T133971:0|t[Kochkunst] |cRXP_WARN_bis 50 verwenden könnt, was später im Dämmerwald erforderlich ist|r",
        ["|cRXP_WARN_Save the |cRXP_LOOT_Gooey Spider Legs|r for later|r"] = "|cRXP_WARN_Behaltet die |cRXP_LOOT_Klebriges Spinnenbeine|r für später|r",
