        ["|cRXP_WARN_Select \"I need a report for Executor Zygand\"|r"] = "|cRXP_WARN_Wählt „Ich benötige einen Bericht für Executor Zygand aus|r",
        ["|cRXP_WARN_Select \"I need a report for Executor Zygand|r\""] = "|cRXP_WARN_Wählt aus \"Ich benötige einen Bericht für Exekutor Zygand|r\"",
        ["|cRXP_WARN_Send your pet to attack a |cRXP_ENEMY_Thistle Bear|r. Once your pet is stunned by the |cRXP_ENEMY_Thistle Bear|r, abandon your pet and start taming it|r"] = "|cRXP_WARN_Sendet euer pet zum Angriff auf einen |cRXP_ENEMY_Distelbär|r. Sobald euer pet durch den |cRXP_ENEMY_Distelbär|r betäubt ist, gebt euer Haustier auf und beginnt es zu zähmen|r",
        ["|cRXP_WARN_She may be moving between locations during a roleplay sequence. Wait at the waypoint location|r."] = "|cRXP_WARN_Sie kann sich während eines Rollenspiels zwischen Orten bewegen. Wartet am Wegpunkt-Ort|r.",
        ["|cRXP_WARN_She may be moving between locations during a roleplay sequence|r."] = "|cRXP_WARN_Sie könnte sich während einer Rollenspielbewegung zwischen Orten bewegen|r.",
        ["|cRXP_WARN_She Nets and Poisons. Skip this step if you are unable to kill her|r"] = "|cRXP_WARN_Sie nutzt Netze und Gifte. Überspringt diesen Schritt, wenn ihr sie nicht töten könnt|r",
        ["|cRXP_WARN_She patrols around|r"] = "|cRXP_WARN_Sie patrouilliert herum|r",
        ["|cRXP_WARN_Skip and abandon this quest if it won't drop|r"] = "|cRXP_WARN_Überspringt und brecht die Quest ab, falls es nicht droppt.|r",
        ["|cRXP_WARN_Skip it if you can't do this quest. You will have another opportunity to complete it at higher level|r"] = "|cRXP_WARN_Überspringt sie, falls du diese Quest nicht machen kannst. Du wirst eine weitere Gelegenheit haben, sie auf höherem Level abzuschließen|r",
