        ["|cRXP_WARN_Skip the|r |cRXP_LOOT_Lieutenant's Insignia|r |cRXP_WARN_if you're unlucky with the drop|r"] = "|cRXP_WARN_Überspringt die|r |cRXP_LOOT_Insignien des Lieutenants|r |cRXP_WARN_falls ihr pech mit den Drops habt|r",
        ["|cRXP_WARN_Skip this if you already have two professions|r."] = "|cRXP_WARN_Überspringt diesen Schritt, falls ihr bereits zwei Berufe habt|r.",
