        ["|cRXP_WARN_Skip this if you want, it's only a small time saver|r"] = "|cRXP_WARN_Überspringt dies, wenn ihr wollt, es spart nur wenig Zeit|r",
        ["|cRXP_WARN_Skip this quest if the NPC is not there|r"] = "|cRXP_WARN_Überspringt die Quest, wenn der NPC nicht da ist|r",
        ["|cRXP_WARN_Skip this quest if there is a lot of competition! There aren't that many |cRXP_PICK_Rocks|r and they do not respawn quickly|r"] = "|cRXP_WARN_Überspringt diese Quest, wenn es viel Konkurrenz gibt! Es gibt nicht so viele |cRXP_PICK_Felsen|r und sie erscheinen nicht schnell wieder.|r",
