        ["|cRXP_WARN_Skip this step if he is not there. It can take up to 25 minutes for him to respawn|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn er nicht dort ist. Es kann bis zu 25 Minuten dauern, bis er respawnt|r",
        ["|cRXP_WARN_Skip this step if she is not there|r"] = "|cRXP_WARN_Überspringt diesen Schritt, falls sie nicht da ist|r",
        ["|cRXP_WARN_Skip this step if there aren't any mobs nearby to complete the objective!|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn es keine Mobs in der Nähe gibt, um das Ziel zu erfüllen!|r",
