        ["|cRXP_WARN_Skip this step if you can't find him or can't kill him. You can come back for him later|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn ihr ihn nicht finden oder nicht töten könnt. Ihr könnt später zurückkommen|r",
        ["|cRXP_WARN_Skip this step if you don't have 1 silver, or if you wish to do it later|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn ihr nicht 1 Silber habt oder ihn später machen wollt|r",
        ["|cRXP_WARN_Skip this step if you wish to not buy any|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn ihr nichts kaufen möchtet|r",
