        ["|cRXP_WARN_Skip this step if you're unable to find him|r"] = "|cRXP_WARN_Überspringt diesen Schritt, wenn ihr ihn nicht finden könnt|r",
        ["|cRXP_WARN_Skip this step if you've already bought a wand or can get one cheap from the AH.|r"] = "|cRXP_WARN_Überspringt diesen Schritt, falls ihr bereits einen Zauberstab gekauft habt oder einen billig aus dem Auktionshaus bekommen könnt.|r",
        ["|cRXP_WARN_Skip this step once you've made all|r |T132834:0|t[Herb Baked Eggs]"] = "Überspringt diesen Schritt, sobald ihr alle |T132834:0|t[Kräutergebackenen Eier] |cRXP_WARN_hergestellt habt|r",
        ["|cRXP_WARN_Smash the|r |T134707:0|t[Picks] |cRXP_WARN_at the Forge|r"] = "|cRXP_WARN_Zerstört die|r |T134707:0|t[Spitzhacken] |cRXP_WARN_in der Schmiede|r",
        ["|cRXP_WARN_Stand on the waypoint location. Position your camera and cursor until you can click 3 |cRXP_PICK_Practice Lockboxes|r at once without having to move anything|r"] = "|cRXP_WARN_Steht auf dem Wegpunkt. Positioniert eure Kamera und euren Cursor, bis ihr 3 |cRXP_PICK_Übungsschließkisten|r gleichzeitig anklicken könnt, ohne das ihr euch bewegen müsst|r",
        ["|cRXP_WARN_Start casting|r |T136126:0|t[Life Tap] |cRXP_WARN_on your way back up to |cRXP_FRIENDLY_Gakin the Darkbinder|r as you will do a deathskip momentarily|r"] = "|cRXP_WARN_Wirkt|r |T136126:0|t[Aderlass] |cRXP_WARN_auf eurem Weg zurück nach oben zu |cRXP_FRIENDLY_Gakin der Dunkelbinder|r da ihr in Kürze einen Deathskip machen werdet|r",
        ["|cRXP_WARN_Start collecting 3 stacks of|r |T132889:0|t[Linen Cloth] |cRXP_WARN_as you quest throughout Durotar. This will be used to make your wand later|r"] = "|cRXP_WARN_Sammelt 3 Stapel|r |T132889:0|t[Leinenstoff] |cRXP_WARN_während ihr in Durotar Quests absolviert. Das wird später verwendet, um deinen Zauberstab herzustellen|r",
        ["|cRXP_WARN_Start collecting 3 stacks of|r |T132889:0|t[Linen Cloth]|cRXP_WARN_. This will be used to make a|r |T135139:0|t[Lesser Magic Wand] |cRXP_WARN_later|r"] = "|cRXP_WARN_Sammelt 3 Stapel|r |T132889:0|t[Leinenstoff]|cRXP_WARN_. Dies wird benutzt, um einen|r |T135139:0|t[Geringer Magiezauberstab] |cRXP_WARN_später herzustellen|r",
        ["|cRXP_WARN_Start looking for a group for Gyromast's Revenge/|r|cRXP_ENEMY_The Threshwackonator 4100|r"] = "|cRXP_WARN_Beginnt, eine Gruppe für Gyromasts Rache/|r|cRXP_ENEMY_Der Dreschonator 4100|r zu suchen",
        ["|cRXP_WARN_Start|r |T133971:0|t[Cooking] |T132834:0|t[Herb Baked Eggs]|cRXP_WARN_. Do this until your|r |T133971:0|t[Cooking] |cRXP_WARN_has reached at least level 10|r"] = "|cRXP_WARN_Fangt an|r |T133971:0|t[Kochkunst] |T132834:0|t[Kräutergebackenes Ei] |cRXP_WARN_. zu kochen. Macht dies, bis eure|r |T133971:0|t[Kochkunst] |cRXP_WARN_mindestens 10 erreicht hat|r",
        ["|cRXP_WARN_Stay on the upper levels of the cave if possible|r"] = "|cRXP_WARN_Bleibt, wenn möglich, in der oberen Ebenen der Höhle|r",
        ["|cRXP_WARN_Stay on the upper section. If there is not a |cRXP_LOOT_Death Cap|r at the end of the top side, drop down and get one from the southern room below|r"] = "|cRXP_WARN_Bleibt im oberen Bereich. Wenn es keine |cRXP_LOOT_Todeskappe|r am Ende der Oberseite gibt, springt hinunter und holt eine aus dem südlichen Raum darunter|r",
        ["|cRXP_WARN_Steer clear of the|r |cRXP_ENEMY_Thunderheads|r |cRXP_WARN_in the area|r"] = "|cRXP_WARN_Vermeidet|r |cRXP_ENEMY_Donnerköpfe|r |cRXP_WARN_in der Gegend|r",
        ["|cRXP_WARN_STICK TO THE MAIN ROAD AND AVOID ANY CLOSE MOBS EN-ROUTE|r"] = "|cRXP_WARN_BLEIBT AUF DER HAUPTSTRASSE UND VERMEIDET ALLE NAHEGELEGENEN MOBS AUF DEM WEG|r",
        ["|cRXP_WARN_Stop casting |T136006:0|t[|cRXP_LOOT_Wrath|r] altogether!|r Only use |T135158:0|t[|cRXP_LOOT_Melee|r] and |T136096:0|t[|cRXP_LOOT_Moonfire|r] from now on!"] = "Stoppt das Wirken von |T136006:0|t[Zorn] |cRXP_WARN_vollständig!|cRXP_LOOT_ Benutzt nur |T135158:0|t[|rNahkampf|r] und |T136096:0|t[|cRXP_LOOT_Mondfeuer|r] |cRXP_LOOT_ab sofort!|r",
        ["|cRXP_WARN_Swim out in the water|r"] = "|cRXP_WARN_Schwimmt hinaus ins Wasser|r",
        ["|cRXP_WARN_Swim underwater to the outside of the back of the boat|r"] = "|cRXP_WARN_Schwimmt unter Wasser zur Außenseite der Bootsrückseite|r",
        ["|cRXP_WARN_Take the Deeprun Tram to the Ironforge side|r"] = "|cRXP_WARN_Nehmt die Tiefenbahn nach Eisenschmiede|r",
        ["|cRXP_WARN_Take the Deeprun Tram to the Stormwind side|r"] = "|cRXP_WARN_Nehmt die Tiefenbahn in Richtung Sturmwind|r",
        ["|cRXP_WARN_The |cRXP_ENEMY_Malformed Defias Drone|r spawns at the entrance to the tower, then patrols around the outside of it|r"] = "|cRXP_WARN_Die |cRXP_ENEMY_Missgestaltete Drohne der Defias|r taucht am Eingang des Turms auf und patrouilliert um das Äußere des Turms herum|r",
        ["|cRXP_WARN_The |cRXP_PICK_Miners' League Crates|r can be found all throughout the Mine|r"] = "|cRXP_WARN_|cRXP_PICK_Kisten der Minenarbeiterliga|r sind überall in der Mine zu finden|r",
        ["|cRXP_WARN_The level 5 mobs may turn gray during this quest. Still finish it as you need to complete this quest to unlock the follow up's|r"] = "|cRXP_WARN_Die Mobs der Stufe 5 können während dieser Quest grau werden. Beendet sie trotzdem, da ihr diese Quest abschließen müsst, um die Fortsetzung freizuschalten|r",
        ["|cRXP_WARN_The zeppelin can arrive at any time during its 6-minute cycle. While you wait, complete the following:|r"] = "|cRXP_WARN_Der Zeppelin kann während seines 6-Minuten-Zyklus jederzeit ankommen. Während ihr wartet, erledigt Folgendes:|r",
        ["|cRXP_WARN_Their spawn locations are scattered throughout the island|r"] = "|cRXP_WARN_Ihre Spawpunkte sind über die gesamte Insel verstreut|r",
        ["|cRXP_WARN_There is a quest in Duskwood later requiring your|r |T133971:0|t[Cooking] |cRXP_WARN_to be 50 or higher. You can also cook this when you get on the boat soon|r"] = "|cRXP_WARN_Es gibt eine Quest im Dämmerwald, die später eure|r |T133971:0|t[Kochkunst]|cRXP_WARN_ von 50 oder höher erfordert. Ihr könnt dies auch kochen, wenn ihr das nächste mal das Boot nehmt|r",
        ["|cRXP_WARN_These can be difficult to see|r"] = "|cRXP_WARN_Diese können schwer zu sehen sein|r",
        ["|cRXP_WARN_These will provide a high DPS increase in early levels. If you don't want to or can't do this, skip this step|r"] = "|cRXP_WARN_Diese bieten einen hohen DPS-Anstieg in frühen Leveln. Falls ihr das nicht tun möchtet oder nicht könnt, überspringt diesen Schritt|r",
        ["|cRXP_WARN_They are found near trees in the Gnoll area|r"] = "|cRXP_WARN_Sie befinden sich in der Nähe von Bäumen im Gnoll-Gebiet|r",
        ["|cRXP_WARN_They are immune to fear!|r"] = "|cRXP_WARN_Sie sind immun gegen Furcht!|r",
        ["|cRXP_WARN_They are mainly found near the stone walls in the area|r"] = "|cRXP_WARN_Sie sind hauptsächlich in der Nähe der Steinmauern in der Umgebung zu finden|r",
        ["|cRXP_WARN_They are mainly found underneath/near the trees|r"] = "|cRXP_WARN_Sie sind hauptsächlich unter/neben den Bäumen zu finden|r",
        ["|cRXP_WARN_They are usually located next to tree trunks|r"] = "|cRXP_WARN_Sie befinden sich normalerweise neben Baumstämmen|r",
        ["|cRXP_WARN_They can be found under the trees on the ground|r"] = "|cRXP_WARN_Sie können unter den Bäumen auf dem Boden gefunden werden|r",
        ["|cRXP_WARN_They can patrol around|r"] = "|cRXP_WARN_Sie können in der Gegend herumpatrouillieren|r",
        ["|cRXP_WARN_They look like small brown sacks and can be partially buried into the ground. They can be hard to see|r"] = "|cRXP_WARN_Sie sehen wie kleine braune Säcke aus und können teilweise im Boden vergraben sein. Sie können schwer zu sehen sein|r",
        ["|cRXP_WARN_They look like small brown sacks. They can be hard to see|r"] = "|cRXP_WARN_Sie sehen wie kleine braune Säcke aus. Sie können schwer zu sehen sein|r",
        ["|cRXP_WARN_They're usually guarded by a|r |cRXP_ENEMY_Bloodtalon Taillasher|r"] = "|cRXP_WARN_Sie werden normalerweise von einem|r |cRXP_ENEMY_Blutkrallenschwanzpeitscher|r bewacht",
        ["|cRXP_WARN_This is a hyperspawn area. You should not need to move from here|r"] = "|cRXP_WARN_Dies ist ein Hyperspawn-Gebiet. Ihr solltet nicht von hier weg müssen|r",
        ["|cRXP_WARN_This is a limited supply item. Skip this step if |cRXP_FRIENDLY_Billibub Cogspinner|r doesn't have one|r"] = "|cRXP_WARN_Dieses Item hat limitierte Verfügbarkeit. Überspringe den Schritt, wenn |cRXP_FRIENDLY_Billibub Zahnrad|r keine hat|r",
        ["|cRXP_WARN_This is a limited supply item. Skip this step if |cRXP_FRIENDLY_Gearcutter Cogspinner|r doesn't have one|r"] = "|cRXP_WARN_Dieses Item hat limitierte Verfügbarkeit. Überspringe den Schritt, wenn |cRXP_FRIENDLY_Gearcutter Cogspinner|r keine hat|r",
        ["|cRXP_WARN_This is a limited supply item. Skip this step if |cRXP_FRIENDLY_Neal Allen|r doesn't have one|r"] = "|cRXP_WARN_Dieses Item hat limitierte Verfügbarkeit. Überspringe den Schritt, wenn |cRXP_FRIENDLY_Neal Allen|r keine hat|r",
        ["|cRXP_WARN_This is a pre-quest for RFC. It has a low droprate|r"] = "|cRXP_WARN_Das ist eine Vor-Quest für RFC mit niedriger Fallquote|r",
        ["|cRXP_WARN_This is a timed quest, you have to escort him to his bag in 20 minutes|r"] = "|cRXP_WARN_Dies ist eine Zeitquest, ihr müsst ihn in 20 Minuten zu seinem Beutel bringen|r",
        ["|cRXP_WARN_This is for leveling up your|r |T133971:0|t[Cooking] |cRXP_WARN_while on the boat soon|r"] = "|cRXP_WARN_Dies ist zum Aufleveln  eurer|r |T133971:0|t[Kochkunst] |cRXP_WARN_während ihr bald auf dem Boot seid|r",
        ["|cRXP_WARN_This is hard! Group up if possible. It has 700 health but his damage is manageable. Skip this step if you can't kill it|r"] = "|cRXP_WARN_Das ist schwierig! Macht eine Gruppt, falls möglich. Er hat 700 Leben, aber sein Schaden ist bewältigbar. Überspringt diesen Schritt, wenn ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_This is hard! Group up if possible. It has 800 health but his damage is manageable. Skip this step if you can't kill it|r"] = "|cRXP_WARN_Das ist schwierig! Macht eine Gruppt, falls möglich. Er hat 800 Leben, aber sein Schaden ist bewältigbar. Überspringt diesen Schritt, wenn ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_This is hard! Group up if possible. Skip this step if you can't kill it|r"] = "|cRXP_WARN_Das ist schwer! Bildet eine Gruppe, falls möglich. Überspringt diesen Schritt, falls ihr ihn nicht töten könnt|r",
        ["|cRXP_WARN_This is used in conjunction with|r |T136241:0|t[Blacksmithing] |cRXP_WARN_to make|r |T135248:0|t[Rough Sharpening Stones] |cRXP_WARN_and|r |T135255:0|t[Rough Weightstones] |cRXP_WARN_to increase your weapon damage|r"] = "|cRXP_WARN_Dies wird zusammen mit|r |T136241:0|t[Schmiedekunst] |cRXP_WARN_verwendet, um|r |T135248:0|t[Rauer Wetzstein] |cRXP_WARN_und|r |T135255:0|t[Rauer Gewichtsstein] |cRXP_WARN_herzustellen und den Waffenschaden von Euch zu erhöhen|r",
        ["|cRXP_WARN_This is used to make|r |T135805:0|t[Basic Campfires] |cRXP_WARN_on Boats to level your|r |T133971:0|t[Cooking] |cRXP_WARN_skill without losing time|r"] = "|cRXP_WARN_Dies wird verwendet, um|r |T135805:0|t[Basic Campfires] |cRXP_WARN_auf Schiffen zu erstellen und eure|r |T133971:0|t[Kochkunst] |cRXP_WARN_Fähigkeit zu leveln, ohne Zeit zu verlieren|r",
        ["|cRXP_WARN_This is used to make|r |T135805:0|t[Basic Campfires] |cRXP_WARN_while waiting for Boats to level your|r |T133971:0|t[Cooking] |cRXP_WARN_skill without losing time|r"] = "|cRXP_WARN_Dies wird zum Erstellen von|r |T135805:0|t[Einfaches Lagerfeuer] |cRXP_WARN_benutzt, während ihr auf die Boote wartet, um eure|r |T133971:0|t[Kochkunst] |cRXP_WARN_-Fertigkeit zu leveln, ohne Zeit zu verschwenden|r",
        ["|cRXP_WARN_This quest does not have to be completed now|r"] = "|cRXP_WARN_Diese Quest muss jetzt nicht abgeschlossen werden|r",
        ["|cRXP_WARN_This quest is difficult. Find a group for him if needed. Skip this step if you're unable to find a group or solo him|r"] = "|cRXP_WARN_Diese Quest ist schwierig. Findet eine Gruppe für ihn, falls nötig. Überspringt diesen Schritt, wenn ihr keine Gruppe findet oder ihn solo nicht besiegen könnt|r",
