        ["|cRXP_WARN_Travel back to the hills you just ran over for a shortcut to eastern Elwynn Forest|r"] = "|cRXP_WARN_Reist zurück zu den Hügeln, durch die ihr gerade gelaufen seid, als Abkürzung zum östlichen Elwynn-Wald|r",
