        ["|cRXP_WARN_Travel toward the |cRXP_PICK_Campfire|r on the ground|r"] = "|cRXP_WARN_Lauft zum |cRXP_PICK_Lagerfeuer|r auf dem Boden|r",
        ["|cRXP_WARN_Travel up to 2nd top floor of the tower. Whilst in|r |T132320:0|t[Stealth] |cRXP_WARN_and the |cRXP_ENEMY_Defias Tower Sentries|r aren't next to you, Jump onto the chair, then onto the lamp, then onto the bookshelf on top of the waypoint location|r"] = "|cRXP_WARN_Reist bis zum 2. Stockwerk des Turms hinauf. Während ihr in|r |T132320:0|t[Verstohlenheit] |cRXP_WARN_seid und die |cRXP_ENEMY_Turmwachposten der Defias|r nicht neben euch sind, springt auf den Stuhl, dann auf die Lampe, dann auf das Bücherregal oben auf dem Wegpunkt|r",
        ["|cRXP_WARN_Try to avoid |cRXP_ENEMY_Mangy Duskbats|r if you can due to them being much tougher to kill than |cRXP_ENEMY_Duskbats|r|r"] = "|cRXP_WARN_Vermeidet wenn möglich |cRXP_ENEMY_Räudiger Nachtsauger|r, da sie viel zäher zu töten sind als |cRXP_ENEMY_Nachtsauger|r|r",
        ["|cRXP_WARN_Try to avoid |cRXP_ENEMY_Scarlet Initiates|r if you can as they have|r |T135843:0|t[Frost Armor] |cRXP_WARN_(slows your attack speed)|r"] = "|cRXP_WARN_Versucht, die |cRXP_ENEMY_Scharlachroter Initiand|r zu vermeiden, wenn ihr könnt, da sie|r |T135843:0|t[Frostrüstung] |cRXP_WARN_(verlangsamt von Euch die Angriffsgeschwindigkeit)|r haben",
        ["|cRXP_WARN_Try to avoid getting close to him or he will cast|r |T135848:16|t[Glacial Roar] |cRXP_WARN_which stuns you for 3 seconds|r"] = "|cRXP_WARN_Versucht, nicht zu nah an ihn heranzugehen, sonst wirkt er|r |T135848:16|t[Gletschergebrüll] |cRXP_WARN_was dich 3 Sek. betäubt|r",
        ["|cRXP_WARN_Try to do this quest if you can as it'll save you time later as it rewards|r |T134797:0|t[Draught of Water Breathing] |cRXP_WARN_for underwater quests later|r"] = "|cRXP_WARN_Versucht diese Quest zu machen, wenn ihr könnt, da sie später Zeit spart|r |T134797:0|t[Trank der Wasseratmung] |cRXP_WARN_für spätere Unterwasser-Quests|r",
        ["|cRXP_WARN_Try to find a group for this step. The |cRXP_ENEMY_Kobolds|r respawn very fast in the cave|r"] = "|cRXP_WARN_Versucht, eine Gruppe für diesen Schritt zu finden. Die |cRXP_ENEMY_Kobolde|r respawnen sehr schnell in der Höhle|r",
        ["|cRXP_WARN_Try to finish|r looting the |cRXP_LOOT_Owl Feathers|r on the owls next to the furlbogs"] = "|cRXP_WARN_Versucht, das Sammeln der|r Eulenfedern|cRXP_LOOT_ an den Eulen neben den Furlbogs abzuschließen|r",
        ["|cRXP_WARN_Try to get to level 2 before getting there|r"] = "|cRXP_WARN_Versucht, Stufe 2 zu erreichen, bevor ihr dort ankommt|r",
