        ["|cRXP_WARN_Use|r |T136058:0|t[Pick Lock] |cRXP_WARN_to open|r |T133626:0|t[Tazan's Satchel]"] = "Benutzt |T136058:0|t[Schloss knacken] |cRXP_WARN_um|r |T133626:0|t[Tazans Ranzen] |cRXP_WARN_zu öffnen|r",
        ["|cRXP_WARN_Use|r |T136100:0|t[Entangling Roots] |cRXP_WARN_on him when he turns hostile then create distance and kite using instant cast spells|r"] = "|cRXP_WARN_Benutzt|r |T136100:0|t[Wucherwurzeln] |cRXP_WARN_|r auf ihn und baue Distanz zu ihm auf. Kite ihn mit Schnellzaubern",
        ["|cRXP_WARN_Vendor all your gear and your staff|r! Buy a |T135139:0|t[|cRXP_LOOT_Short Staff|r] from him"] = "|cRXP_WARN_Verkauft eure komplette Ausrüstung und euren Stab|r! Kauft den |T135139:0|t[|cRXP_LOOT_Kurzstab|r] von ihm",
        ["|cRXP_WARN_Vendor and repair if needed|r"] = "|cRXP_WARN_Verkaufe und repariere falls nötig|r",
        ["|cRXP_WARN_Vendor and repair if needed|r."] = "|cRXP_WARN_Vendor und repair if needed|r.",
        ["|cRXP_WARN_Vendor trash and repair|r."] = "|cRXP_WARN_Vendor trash und repair|r.",
        ["|cRXP_WARN_Vendor trash|r"] = "|cRXP_WARN_verkauft Schrott|r",
        ["|cRXP_WARN_Wait for the respawn if it's not up|r"] = "|cRXP_WARN_Wartet auf den Respawn, falls es noch nicht da ist|r",
        ["|cRXP_WARN_Wait for the Roleplay|r."] = "|cRXP_WARN_Wartet auf das Rollenspiel|r.",
        ["|cRXP_WARN_Wait until |cRXP_ENEMY_Old Icebeard|r patrols out of the Cave. Once he patrols out of the Cave you can enter and loot|r |cRXP_PICK_MacGrann's Meat Locker|r"] = "|cRXP_WARN_Wartet bis |cRXP_ENEMY_Eisbart der Alte|r aus der Höhle patrouilliert. Sobald er aus der Höhle patrouilliert, könnt ihr hineingehen und|r |cRXP_PICK_MacGranns Fleisch-Spind|r plündern",
        ["|cRXP_WARN_walk onto the top of the bed, then jump onto the top of the bookshelf. Perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Geht auf die Spitze des Bettes, dann springt auf die Spitze des Bücherregals. Führt einen Logout-Skip durch, indem ihr euch abmeldet und wieder anmeldet|r",
        ["|cRXP_WARN_Watch for stealthed enemies in the apple orchard|r."] = "|cRXP_WARN_Beobachtet getarnte Feinde im Apfelgarten|r.",
        ["|cRXP_WARN_Watch out for stealthed bandits along the way|r."] = "|cRXP_WARN_Beobachtet die getarnten Banditen entlang des Weges|r.",
        ["|cRXP_WARN_Watch out for|r |cRXP_ENEMY_Witchwing Ambushers|r|cRXP_WARN_. They are stealthed and patrol in the area|r"] = "|cRXP_WARN_Passt auf|r |cRXP_ENEMY_Wegelagerin der Hexenschwingen|r|cRXP_WARN_. Sie sind verstohlen und patrouillieren in der Gegend|r",
        ["|cRXP_WARN_Watch the video below before you attempt to kill |cRXP_ENEMY_Vagash|r. It can be soloed on any class|r"] = "|cRXP_WARN_Schaut das Video unten, bevor ihr versucht, |cRXP_ENEMY_Vagash|r zu töten. Es kann von jeder Klasse solo absolviert werden|r",
        ["|cRXP_WARN_We choose the|r |T132383:0|t[Explosive Rockets] |cRXP_WARN_as the reward. It deals decent damage, and can be used for \"Split pulling\" which is incredibly useful|r"] = "|cRXP_WARN_Wir wählen die|r |T132383:0|t[Explosiv Raketen] |cRXP_WARN_als Belohnung. Sie verursachen ordentlichen Schaden und können für \"Split-Pulls\" genutzt werden, was unglaublich nützlich ist|r",
        ["|cRXP_WARN_We need them for Cooking later|r."] = "|cRXP_WARN_Wir brauchen sie später für die Kochkunst|r.",
        ["|cRXP_WARN_While the Tornado speed buff is active, avoid killing them|r."] = "|cRXP_WARN_Während der Tornado-Geschwindigkeitsbonus aktiv ist, vermeidet es, sie zu töten|r.",
        ["|cRXP_WARN_While waiting for the Boat on the dock:|r"] = "|cRXP_WARN_Während des Wartens auf das Boot am Dock:|r",
        ["|cRXP_WARN_Work on completing the other quest objectives as you move there|r"] = "|cRXP_WARN_Arbeitet an der Vervollständigung der anderen Questziele, während ihr dorthin reist|r",
        ["|cRXP_WARN_You can cancel the Farsight once the objective completes|r"] = "|cRXP_WARN_Ihr könnt die Fernsicht abbrechen, sobald das Ziel abgeschlossen ist|r",
        ["|cRXP_WARN_You can cast|r |T136071:0|t[Polymorph] |cRXP_WARN_on|r |cRXP_ENEMY_Fizzle|r |cRXP_WARN_and kill the|r |cRXP_ENEMY_Imp|r |cRXP_WARN_first|r"] = "|cRXP_WARN_Ihr könnt|r |T136071:0|t[Verwandlung] |cRXP_WARN_auf|r |cRXP_ENEMY_Fizzle|r wirken |cRXP_WARN_und tötet|r |cRXP_ENEMY_Wichtel|r |cRXP_WARN_zuerst|r",
        ["|cRXP_WARN_You can delete|r |T134707:0|t[Prospector's Picks] |cRXP_WARN_from your bags, as they're no longer needed|r"] = "|cRXP_WARN_Ihr könnt|r |T134707:0|t[Ausgrabungsleiterhacke] |cRXP_WARN_zerstören, da sie nicht mehr benötigt werden|r",
        ["|cRXP_WARN_You can delete|r |T134712:0|t[Water of the Seers] |cRXP_WARN_from your bags, as it's no longer needed|r"] = "|cRXP_WARN_Ihr könnt|r |T134712:0|t[Wasser der Seher] |cRXP_WARN_zerstören, da es nicht mehr benötigt wird|r",
        ["|cRXP_WARN_You can gather herbs along the way to start working toward 20 Herbalism for a later quest. This is optional, especially at launch, so do it at your own risk|r"] = "|cRXP_WARN_Ihr könnt Kräuter sammeln, während ihr vorbeigeht, um auf 20 Kräuterkunde für eine spätere Quest hinzuarbeiten. Dies ist optional, besonders zu Beginn, also macht es auf eigenes Risiko|r",
        ["|cRXP_WARN_You can get it later if it's not there|r"] = "|cRXP_WARN_Ihr könnt es später holen, falls es nicht da ist|r",
        ["|cRXP_WARN_You can loot |cRXP_PICK_Furlbrow's Wardrobe|r from outside if you angle your camera correctly|r"] = "|cRXP_WARN_Ihr könnt die |cRXP_PICK_Furlbrows Kleiderschrank|r von außen plündern, wenn ihr eure Kamera richtig neigt|r",
        ["|cRXP_WARN_You can LoS (Line of Sight) the |cRXP_ENEMY_Greymist Oracles|r'|r  |T136048:0|t[Lightning Bolts] |cRXP_WARN_around the sunken ship to avoid taking its damage|r"] = "|cRXP_WARN_Ihr könnt aus dem Sichtfeld der |cRXP_ENEMY_Orakel der Grauflossen|r'|r|T136048:0|t[Blitzschlag]|cRXP_WARN_ gehen. Geht um das versunkene Schiff, um den Schaden auszuweichen|r",
        ["|cRXP_WARN_You can mine ore along the way to start working toward 20 Mining for a later quest. This is optional, especially at launch, so do it at your own risk|r"] = "|cRXP_WARN_Ihr könnt Erz abbauen, während ihr vorbeigeht, um auf 20 Bergbau für eine spätere Quest hinzuarbeiten. Dies ist optional, besonders zu Beginn, also macht es auf eigenes Risiko|r",
        ["|cRXP_WARN_You can run to bodies of water found within the cave to evade the|r |cRXP_ENEMY_Voidwalker|r |cRXP_WARN_after killing|r |cRXP_ENEMY_Gazz'uz|r"] = "|cRXP_WARN_Ihr könnt zu Gewässern innerhalb der Höhle fliehen um dem|r Leerwandler|cRXP_ENEMY_ nach dem Töten von|r |cRXP_WARN_Gazz'uz|r |cRXP_ENEMY_zu entkommen|r",
        ["|cRXP_WARN_You can skin along the way to start working toward 20 Skinning for a later quest. This is optional, especially at launch, so do it at your own risk|r"] = "|cRXP_WARN_Ihr könnt Häute sammeln, während ihr vorbeigeht, um auf 20 Kürschnerei für eine spätere Quest hinzuarbeiten. Dies ist optional, besonders zu Beginn, also macht es auf eigenes Risiko|r",
        ["|cRXP_WARN_You can talk to him from outside or on top of the bunker|r"] = "|cRXP_WARN_Ihr könnt mit ihm von außen oder oben auf dem Bunker sprechen|r",
        ["|cRXP_WARN_You can usually find them near Farm Fences or Buildings|r"] = "|cRXP_WARN_Ihr findet sie normalerweise in der nähe von Farmzäunen oder Gebäuden|r",
        ["|cRXP_WARN_You can waste the trap and make the quest impossible to complete! If it happens to you you need to return to the questgiver and ask for another trap|r"] = "|cRXP_WARN_Du kannst die Falle verschwenden und die Quest damit unlösbar machen! Sollte dir das passieren, musst du zum Questgeber zurückkehren und um eine weitere Falle bitten.|r",
        ["|cRXP_WARN_You have 5 minutes to get |cRXP_LOOT_Grelin Whitebeard's Journal|r and return to Anvilmar before|r |T132791:0|t[Durnan's Scalding Mornbrew] |cRXP_WARN_expires|r"] = "|cRXP_WARN_Ihr habt 5 Minuten, um |cRXP_LOOT_Grelin Whitebeards Tagebuch|r zu erhalten und zu Ambossar zurückzukehren, bevor|r |T132791:0|t[Durnans kochend heißes Morgengebräu] |cRXP_WARN_verfällt|r",
        ["|cRXP_WARN_You have 5 minutes to return to Anvilmar before|r |T132791:0|t[Durnan's Scalding Mornbrew] |cRXP_WARN_expires|r"] = "|cRXP_WARN_Ihr habt 5 Minuten Zeit, um nach Ambossar zurückzukehren, bevor|r |T132791:0|t[Durnans kochend heißes Morgengebräu] |cRXP_WARN_verfällt|r",
        ["|cRXP_WARN_You have selected a guide meant for Orcs and Trolls. You should choose the same starter zone that you start in|r"] = "|cRXP_WARN_Ihr habt einen Leitfaden ausgewählt, der für Orks und Trolle bestimmt ist. Ihr solltet dieselbe Startzone wählen, in der ihr startet|r",
        ["|cRXP_WARN_You have selected a guide meant for Tauren. This zone will NOT work well for you due to missing one of the main questlines that are gated for Tauren only. It is recommended you choose the same starter zone that you start in|r"] = "|cRXP_WARN_Ihr habt einen Leitfaden für Tauren ausgewählt. Diese Zone wird für euch NICHT gut funktionieren, da eine der Hauptquests fehlt, die nur für Tauren verfügbar ist. Es wird empfohlen, dass ihr die gleiche Startzone wählt, in der ihr startet|r",
        ["|cRXP_WARN_You have selected a guide meant for Undead. It is recommended you choose the same starter zone that you start in|r"] = "|cRXP_WARN_Ihr habt eine Anleitung für Untote ausgewählt. Es wird empfohlen, dass ihr die gleiche Startzone wählt, in der ihr startet|r",
        ["|cRXP_WARN_You may have to wait about 10 seconds before you can accept this quest|r"] = "|cRXP_WARN_Ihr müsst möglicherweise etwa 10 Sek. warten, bevor ihr diese Quest annehmen könnt|r",
        ["|cRXP_WARN_You may have to wait for him to respawn or for others to finish the escort|r"] = "|cRXP_WARN_Ihr müsst möglicherweise warten, bis er respawnt oder bis andere die Eskorte beenden|r",
        ["|cRXP_WARN_You may need to go in the water for them|r"] = "|cRXP_WARN_Ihr müsstet möglicherweise ins Wasser gehen, um sie zu finden|r",
        ["|cRXP_WARN_You may need to press the macro twice|r."] = "|cRXP_WARN_Ihr müsst möglicherweise das Makro zweimal drücken|r.",
        ["|cRXP_WARN_You must be in|r |T132320:0|t[Stealth] |cRXP_WARN_to use|r |T133644:0|t[Pick Pocket]"] = "|cRXP_WARN_Ihr müsst in|r |T132320:0|t[Verstohlenheit] |cRXP_WARN_sein, um|r |T133644:0|t[Taschendiebstahl] zu nutzen",
        ["|cRXP_WARN_You must complete this quest and return to |cRXP_FRIENDLY_Daryl the Youngling|r with 12 minutes. If you fail the quest, abandon it and pick it up again|r"] = "|cRXP_WARN_Ihr müsst diese Quest abschließen und innerhalb von 12 Minuten zu |cRXP_FRIENDLY_Daryl der Jüngling|r zurückkehren. Falls ihr scheitert, brecht die Quest ab und nehmt sie erneut auf|r",
        ["|cRXP_WARN_You must complete this quest and return to |cRXP_FRIENDLY_Daryl the Youngling|r within 15 minutes. If you fail the quest, abandon it and pick it up again|r"] = "|cRXP_WARN_Ihr müsst diese Quest abschließen und zu |cRXP_FRIENDLY_Daryl der Jüngling|r innerhalb von 15 Minuten zurückkehren. Falls die Quest fehlschlägt, brecht sie ab und nehmt sie erneut an|r",
        ["|cRXP_WARN_You MUST complete this quest to unlock|r |T132290:0|t[Poisons]."] = "|cRXP_WARN_Ihr müsst diese Quest abschließen, um|r |T132290:0|t[Gifte].",
        ["|cRXP_WARN_You MUST do this for your|r |T132290:0|t[Poisons] |cRXP_WARN_quest later|r"] = "|cRXP_WARN_Ihr MÜSST dies für eure|r |T132290:0|t[Gifte]|cRXP_WARN_ Quest später machen|r",
        ["|cRXP_WARN_You must right click your Pet Frame and Dismiss your pet before you can tame another one|r"] = "|cRXP_WARN_Ihr müsst mit der rechten Maustaste auf Euer Begleiterfenster klicken und Euren Begleiter verabschieden, bevor ihr ein anderes zähmen könnt|r",
