        ["Abandon Zenn's Bidding"] = "Brecht die Quest Zenns Aufträge ab",
        ["After clicking on the Wardrobe, return to the city."] = "Nachdem ihr auf den Kleiderschrank geklickt habt, kehrt zur Stadt zurück.",
        ["After crossing the 3rd torch after exiting the cave, a |cRXP_ENEMY_Furlbog|r will spawn from both sides and attack |cRXP_FRIENDLY_Volcor|r"] = "Nachdem ihr die 3. Fackel überquert und die Höhle verlassen habt, spawnet ein |cRXP_ENEMY_Furbog|r von beiden Seiten und greift |cRXP_FRIENDLY_Volcor|r an",
        ["Ascend the Aldrassil Tree"] = "Klettert auf den Aldrassil-Baum",
        ["Ascend the spiral staircase, then kill |cRXP_ENEMY_Skypriest Aanders::256966|r atop the tower."] = "Erklimmt die Wendeltreppe und tötet dann |cRXP_ENEMY_Skypriest Aanders::256966|r oben auf dem Turm.",
        ["Attack |cRXP_ENEMY_Bartleby|r. He will submit at 1%"] = "Greift |cRXP_ENEMY_Bartleby|r an. Er wird sich bei 1% ergeben",
        ["Attack the |cRXP_ENEMY_Webbed Forsaken|r"] = "Greift den |cRXP_ENEMY_Eingesponnener Verlassener|r an",
        ["Be careful as |cRXP_ENEMY_Reef Crawlers|r can cast |T132155:0|t[Muscle Tear] an instant attack dealing 30-55 damage"] = "Seid vorsichtig da die |cRXP_ENEMY_Riffkriecher|r |T132155:0|t[Muskelriss] wirken.Ein sofortiger Angriff, der 30-55 Schaden verursacht",
        ["Be careful as they can cast |T132090:0|t[Exploit Weakness] a backstab attack dealing 20-40 damage if you turn your back to them"] = "Passt auf, denn sie können |T132090:0|t[Schwäche ausnutzen] wirken, einen Hinterhalt-Angriff, der 20-40 Schaden verursacht, wenn ihr von Euch den Rücken zu ihnen wendet",
        ["Be patient, this item has a low droprate"] = "Hab Geduld, dieser Gegenstand hat eine niedrige Drop-Rate",
        ["Burn the |cRXP_PICK_Attack Plan|r inside the tent on the ground"] = "Verbrennt den |cRXP_PICK_Angriffsplan|r im Zelt auf dem Boden auf",
        ["Burn the |cRXP_PICK_Attack Plan|r on the ground"] = "Verbrennt den |cRXP_PICK_Angriffsplan|r auf dem Boden",
        ["Buy |T132491:0|t[|cRXP_FRIENDLY_Wise Man's Belt|r] from her if it's up"] = "Kauft |T132491:0|t[|cRXP_FRIENDLY_Weisengürtel|r] von ihr, wenn er verfügbar ist",
        ["Buy |T132539:0|t[|cRXP_FRIENDLY_Agile Boots|r] from her if it's up"] = "Kauft |T132539:0|t[|cRXP_FRIENDLY_Bewegliche Stiefel|r] von ihr, wenn sie verfügbar sind",
        ["Buy |T132794:0|t[Refreshing Spring Water]"] = "Kauft |T132794:0|t[Refreshing Federn Wasser]",
        ["Buy |T132815:0|t[Ice Cold Milk]"] = "Kauft |T132815:0|t[Eiskalt Milk]",
        ["Buy 5 |T134059:0|t[Mild Spices] from her, use |T133971:0|t[|cRXP_FRIENDLY_Cooking|r] to cook |T132834:0|t[|cRXP_LOOT_Herb Baked Eggs|r] until you run out of |T132832:0|t[|cRXP_LOOT_Small Eggs|r]"] = "Kauft 5 |T134059:0|t[Milde Gewürze] von ihr, benutzt |T133971:0|t[|cRXP_FRIENDLY_Kochkunst|r], um |T132834:0|t[|cRXP_LOOT_Kräutergebackenes Ei|r] zu kochen, bis ihr keine |T132832:0|t[|cRXP_LOOT_Kleines Ei|r] mehr habt",
        ["Buy a |T134708:0|t[Mining Pick]"] = "Kauft a |T134708:0|t[Spitzhacke]",
        ["Buy a |T135637:0|t[Skinning Knife]"] = "Kauft a |T135637:0|t[Kürschnermesser]",
        ["Buy an |T133634:0|t[Apprentice's Skinning Satchel]"] = "Kauft an |T133634:0|t[Lehrling's Kürschnerei Satchel]",
        ["Buy an |T133635:0|t[Apprentice's Mining Pack]"] = "Kauft an |T133635:0|t[Lehrling's Bergbau Pack]",
        ["Buy an |T133637:0|t[Apprentice's Herb Pouch]"] = "Kauft an |T133637:0|t[Lehrling's Herb Pouch]",
        ["Buy and equip a |T135274:0|t[Shortsword]"] = "Kauft und equip a |T135274:0|t[Kurzschwert]",
        ["Buy and equip a |T135276:0|t[Bastard Sword]"] = "Kauft und equip a |T135276:0|t[Bastardschwert]",
        ["Buy the |T134437:0|t[Anti-Venom] for your |T132290:0|t[Poisons] quest later, and the rest for faster turn ins at Redridge Mountains shortly"] = "Kauft das |T134437:0|t[Gegengift] für eure |T132290:0|t[Gifte]-Quest später und den Rest für schnellere Questabgaben im Rotkammgebirge",
        ["Buy the following items for faster turn ins at Redridge Mountains shortly"] = "Kauft die folgenden Gegenstände für schnellere Abgaben im Rotkammgebirge",
        ["Buy the following items for instant turn ins at Darkshore later:"] = "Kauft die folgenden Gegenstände für eine sofortige Abgabe später in der Dunkelküste",
        ["Care as |cRXP_ENEMY_Greymist Tidehunters|r can cast |T136016:0|t[|cRXP_FRIENDLY_Poison|r] while in melee leaving a dot dealing 13 damage per 3 seconds for 30 seconds"] = "Passt auf, denn |cRXP_ENEMY_Gezeitenjäger der Grauflossen|r können |T136016:0|t[|cRXP_FRIENDLY_Gift|r] wirken im Nahkampf und hinterlassen einen DoT, der 13 Schaden alle 3 Sek. für 30 Sek. verursacht",
        ["Care as they can cast |T132090:0|t[Exploit Weakness] a backstab attack dealing 20-40 damage if you turn your back to them"] = "Passt auf, denn sie können |T132090:0|t[Schwäche ausnutzen] wirken, einen Hinterhalts-Angriff, der 20-40 Schaden verursacht, wenn ihr von Euch den Rücken zu ihnen wendet",
        ["Carefully drop down the mountain into Loch Modan"] = "Springt vorsichtig den Berg hinunter nach Loch Modan",
        ["Carry |cRXP_FRIENDLY_Fillion Flamebreeze::253281|r to safety."] = "Tragt |cRXP_FRIENDLY_Fillion Flamebreeze::253281|r in Sicherheit.",
        ["Cast |T132089:0|t[|cRXP_LOOT_Shadowmeld|r] and |T136057:0|t[|cRXP_LOOT_Elune's Light|r]"] = "Wirkt |T132089:0|t[|cRXP_LOOT_Schattenmimik|r] und |T136057:0|t[|cRXP_LOOT_Elunes Licht|r]",
        ["Cast |T133939:0|t[Find Herbs] to track nearby herbs"] = "Wirkt |T133939:0|t[Kräutersuche] zum Aufspüren nahegelegener Kräuter",
        ["Cast |T135929:0|t[Lesser Heal] and |T135987:0|t[Power Word: Fortitude] on |cRXP_FRIENDLY_Deathguard Kel|r"] = "Wirkt |T135929:0|t[Geringes Heilen] und |T135987:0|t[Machtwort: Seelenstärke] auf |cRXP_FRIENDLY_Todeswache Kel|r",
        ["Cast |T135929:0|t[Lesser Heal] and |T135987:0|t[Power Word: Fortitude] on |cRXP_FRIENDLY_Kor'ja|r"] = "Wirkt |T135929:0|t[Geringes Heilen] und |T135987:0|t[Machtwort: Seelenstärke] auf |cRXP_FRIENDLY_Kor'ja|r",
