        ["Cast Teleport: Moonglade"] = "Caste Teleportieren: Moonglade",
        ["Check for |cRXP_PICK_Chen's Empty Keg|r next to |cRXP_FRIENDLY_Kranal|r. Loot it and start the quest"] = "Sucht nach |cRXP_PICK_Chens leeres Fässchen|r neben |cRXP_FRIENDLY_Kranal|r. Sammelt die Beute und startet die Quest",
        ["Check if he has a |T132867:0|t[|cRXP_FRIENDLY_Lesser Magic Essence|r] for sale. If he does buy it. You will need it to craft a |T135139:0|t[|cRXP_LOOT_Wand|r]"] = "Überprüft, ob er die |T132867:0|t[|cRXP_FRIENDLY_Geringe Magieessenz|r] zum Verkauf hat. Falls ja, kauft sie. Ihr werdet sie benötigen, um einen |T135139:0|t[|cRXP_LOOT_Zauberstab|r] herzustellen",
        ["Check if he has the |T132867:0|t[|cRXP_FRIENDLY_Lesser Magic Essence|r] for sale. If he does buy it. You will need it to craft a |T135139:0|t[|cRXP_LOOT_Wand|r]"] = "Überprüft, ob er die |T132867:0|t[|cRXP_FRIENDLY_Geringe Magieessenz|r] zum Verkauf hat. Falls ja, kauft sie. Ihr werdet sie benötigen, um einen |T135139:0|t[|cRXP_LOOT_Zauberstab|r] herzustellen",
