        ["Click the macro in the Active Items frame to sit."] = "Klickt das Makro im Fenster der Aktiv Gegenstände, um euch zu setzen.",
        ["Climb the hill next to the big tree to the right of the Fire Scar Shrine entrance"] = "Klettert den Hügel neben dem großen Baum rechts vom Eingang des Schrein des Sengenden Feuers hinauf",
