        ["Climb the tower"] = "Klettert auf den Turm",
        ["Collect |cRXP_LOOT_Laden Mushrooms|r around The Forgotten Pools"] = "Sammelt |cRXP_LOOT_Potenter Pilz|r um Die vergessenen Teiche herum",
