        ["Conjure Food/water while you wait"] = "Zaubert Nahrung/Wasser herbei, während ihr wartet",
        ["Continue grinding |cRXP_ENEMY_Troggs|r until your |T134414:0|t[Hearthstone] is ready"] = "Farmt weiter |cRXP_ENEMY_Troggs|r bis euer |T134414:0|t[Ruhestein] wieder verfügbar ist",
