        ["Cross the bridge."] = "Überquert die Brücke.",
        ["Defeat |cRXP_ENEMY_Bartleby|r"] = "Besiegt |cRXP_ENEMY_Bartleby|r",
        ["Delete |T134459:0|t[Gyromast's Key] from your bags, as it's no longer needed"] = "Zerstört |T134459:0|t[Gyromasts Schlüssel] aus euren Taschen, da ihr ihn nicht mehr braucht",
        ["Delete the |T133944:0|t|cRXP_LOOT_[Blackwood Nut Sample]|r from your bags, as it's no longer needed"] = "Zerstört die |T133944:0|t|cRXP_LOOT_[Nussprobe der Schwarzfelle]|r aus eurer Tasche, da ihr sie nicht mehr benötigt",
        ["Delete the |T134013:0|t|cRXP_LOOT_[Blackwood Fruit Sample]|r from your bags, as it's no longer needed"] = "Zerstört die |T134013:0|t|cRXP_LOOT_[Obstprobe der Schwarzfelle]|r aus eurer Tasche, da sie nicht mehr benötigt",
        ["Delete the |T134059:0|t|cRXP_LOOT_[Blackwood Grain Sample]|r from your bags, as it's no longer needed"] = "Entfernt die |T134059:0|t|cRXP_LOOT_[Getreideprobe der Schwarzfelle]|r aus eurer Tasche, da ihr sie nicht mehr benötigt",
        ["Delete the |T134414:0|t[Hearthstone] from your bags, as it's no longer needed"] = "Entfernt den |T134414:0|t[Ruhestein] aus den Taschen von Euch, da er nicht mehr benötigt wird",
        ["Delete the |T134715:0|t[Phial of Scrying] from your bags, as it's no longer needed"] = "Zerstöre die |T134715:0|t[Wahrsagephiole] von Euch aus dem Inventar, da sie nicht mehr benötigt wird",
        ["Delete the |T135426:0|t[Small Throwing Knives] from your bags, as they're no longer needed"] = "Zerstört die |T135426:0|t [Kleinen Wurfmesser] aus den Taschen von Euch, da sie nicht mehr benötigt werden",
        ["Deposit the following items into your bank"] = "Deponiert die folgenden Gegenstände in eurer Bank",
