        ["Destroy the |T134414:0|t[Hearthstone] in your bags, as it's no longer needed"] = "Zerstört |T134414:0|t[Ruhestein] aus eurer Tasche, da er nicht mehr benötigt wird",
        ["Die |cRXP_WARN_ON THE SMALLER ISLAND|r and respawn at the |cRXP_FRIENDLY_Spirit Healer|r"] = "Sterbt |cRXP_WARN_AUF DER KLEINEREN INSEL|r und belebt euch bei dem |cRXP_FRIENDLY_Geistheiler|r wieder",
        ["Die and Respawn at the |cRXP_FRIENDLY_Spirit Healer|r"] = "Sterbt und spawnt beim |cRXP_FRIENDLY_Geistheiler|r",
        ["Die and respawn at the |cRXP_FRIENDLY_Spirit Healer|r by using |T136126:0|t[Life Tap] and standing on the Bonfire next to you"] = "Sterbt und spawnt  beim |cRXP_FRIENDLY_Geistheiler|r, indem ihr |T136126:0|t[Aderlass] benutzt und ihr euch ins Feuer neben euch stellt",
        ["Die and respawn at the |cRXP_FRIENDLY_Spirit Healer|r or run to Brill"] = "Sterbt und respawnt am |cRXP_FRIENDLY_Geistheiler|r oder lauft nach Brill",
        ["Die and respawn at the |cRXP_FRIENDLY_Spirit Healer|r, or run back"] = "Sterbt und lasst euch beim |cRXP_FRIENDLY_Geistheiler|r wiederbeleben, oder lauft zurück",
        ["Die and respawn at the Darnassus graveyard"] = "Sterbt absichtlich und respawnt beim Darnassus-Friedhof",
        ["Die and respawn at the Dolanaar graveyard"] = "Sterbt und respawnt am Friedhof von Dolanaar",
        ["Die and respawn at the Graveyard."] = "Sterbt und spawnt am Friedhof auf.",
