        ["Grind until your HS cooldown is <6 minutes. Die and respawn at the |cRXP_FRIENDLY_Spirit Healer|r"] = "Grindet bis eure Ruhestein-Abklingzeit weniger als 6 Minuten beträgt. Sterbt und erscheint beim |cRXP_FRIENDLY_Geistheiler|r",
        ["Grind until your HS cooldown is <9 minutes then run back to Auberdine"] = "Grindet bis eure Ruhestein-Abklingzeit weniger als 9 Minuten beträgt, dann lauft zurück nach Auberdine",
        ["Grind untill you're 2360 xp away from level 16 (12.040/14.400)"] = "Farmt, bis euch noch 2360 XP bis Stufe 16 fehlen (12.040/14.400)",
        ["Grinding to level 16 here is important, due to the next 3 quests being quite hard"] = "Ihr solltet bis Stufe 16 farmen, da die nächsten 3 Quests ziemlich schwer sind.",
        ["Halfway to the road, a |cRXP_ENEMY_Furlbogs|r will spawn from both sides and attack |cRXP_FRIENDLY_Volcor|r"] = "Auf halbem Weg zur Straße spawnen |cRXP_ENEMY_Furbolgs|r von beiden Seiten und greifen |cRXP_FRIENDLY_Volcor|r an",
        ["Head to the base of the mountain"] = "Lauft zum Fuß des Berges",
        ["Head to the upper level of the temple"] = "Geht zur oberen Ebene des Tempels",
        ["Head up the ramp to the north-west"] = "Lauft die Rampe nach Nordwesten hinauf",
        ["Hearth to Astranaar"] = "Ruhestein nach Astranaar",
        ["Hearth to Auberdine"] = "Ruhestein nach Auberdine",
        ["Hearth to Brill"] = "Benutzt euren Ruhestein nach Brill",
        ["Hearth to Camp Narache"] = "Benutzt euren Ruhestein zum Camp Narache",
        ["Hearth to Coldridge Valley"] = "Benutzt euren Ruhestein in Das Eisklammtal",
        ["Hearth to Darkshore"] = "Benutzt euren Ruhestein zum Dunkelküste",
        ["Hearth to Dolanaar"] = "Benutzt euren Ruhestein nach Dolanaar",
        ["Hearth to Goldshire"] = "Ruhestein nach Goldhain",
        ["Hearth to Ironforge"] = "Ruhestein nach Eisenschmiede",
        ["Hearth to Lakeshire"] = "Benutzt euren Ruhestein nach Seenhain",
        ["Hearth to Orgrimmar"] = "Ruhestein nach Orgrimmar",
        ["Hearth to Razor Hill"] = "Benutzt euren Ruhestein zum Klingenhügel",
        ["Hearth to Shadowglen"] = "Benutzt euren Ruhestein zum Laubschattental",
        ["Hearth to Stormwind"] = "Ruhestein nach Sturmwind",
        ["Hearth to Stormwind City"] = "Ruhestein nach Sturmwind",
        ["Hearth to The Crossroads"] = "Ruhestein nach Das Wegekreuz",
        ["Hearth to the Undercity"] = "Benutzt euren Ruhestein nach Unterstadt",
        ["Hearth to the Valley of Trials"] = "Ruhestein zum Tal der Prüfungen",
        ["Hearth to Thelsamar"] = "Benutzt euren Ruhestein nach Thelsamar",
        ["Hearth to Thendal Village"] = "Benutzt euren Ruhestein zum Thendal Village",
        ["Hearth to Undercity"] = "Benutzt euren Ruhestein nach Unterstadt",
        ["Hearth to Valanaar"] = "Benutzt euren Ruhestein zum Valanaar",
        ["Hearthstone to Auberdine"] = "Benutzt euren Ruhestein nach Auberdine",
        ["Hunter tips: Spam tab to target them early, use Hunter's Mark on them so you can run away and hit them from farther away."] = "Jäger-Tipps: Drückt Tab schnell, um sie frühzeitig anzuvisieren. Nutzt Mal des Jägers gegen sie, damit ihr weglaufen und sie von weiter weg treffen könnt.",
        ["If it's on cooldown, this step will skip on turnin of Harmony in Balance. You can complete it later."] = "Falls es auf Abklingzeit ist, wird dieser Schritt beim Abgeben von Harmonie in Gleichgewicht übersprungen. Ihr könnt ihn später abschließen.",
        ["If you fall down, just run out the cave normally to the quest turn in"] = "Falls ihr hinunterfällt, rennt einfach Normal aus der Höhle zur Questabgabe",
        ["If you have a Staff in your bags, equip it"] = "Falls ihr einen Stab in der Tasche habt, rüstet ihn aus",
        ["In Season of Discovery, you should NOT start outside of your race's starter zone as a Mage, as you will be unable to get your first rune here (|T135844:0|t[Ice Lance])"] = "In der „Season of Discovery“ solltest du als Magier nicht außerhalb des Startgebiets deines Volkes beginnen, da du dort deine erste Rune  (|T135844:0|t[Eislanze]) nicht bekommen wirst",
        ["Jump down the Hunter Rise onto the small hill to exit Thunder Bluff"] = "Springt von der Anhöhe der Jäger auf den kleinen Hügel um Donnerfels zu verlassen",
        ["Jump down the mountain and respawn at the Graveyard."] = "Springt den Berg hinunter und spawnt am Friedhof auf.",
        ["Jump into Thunder Ridge"] = "Springt in den Donnergrat",
        ["Jump off the |cRXP_WARN_lower (not the one you're on)|r mountain and use |T132845:0|t[Walk on Air] to fly towards the questgiver."] = "Springt vom |cRXP_WARN_niedrigeren (nicht dem, auf dem ihr steht)|r Berg und benutzt |T132845:0|t[Gehen on Luft] um zum Questgeber zu fliegen.",
        ["Jump off the |cRXP_WARN_lower mountain|r and use |T132845:0|t[Walk on Air] to fly toward the questgiver."] = "Springt herunter vom |cRXP_WARN_unteren Berg|r und benutzt |T132845:0|t[Luftwandeln], um zum Auftraggeber zu fliegen.",
        ["Jump off the cliff"] = "Springt von der Klippe",
        ["Jump off the cliff."] = "Springt von der Klippe.",
        ["Jump off the mountain and use |T132845:0|t[Walk on Air] |cRXP_WARN_in midair|r to fly towards the waypoint location."] = "Springt vom Berg herunter und benutzt |T132845:0|t[Gehen on Luft] |cRXP_WARN_in der Luft|r, um zum Wegpunkt zu fliegen.",
        ["Jump off the mountain and use |T132845:0|t[Walk on Air] to fly towards the questgiver."] = "Springt vom Berg herunter und benutzt |T132845:0|t[Gehen on Luft], um zum Questgeber zu fliegen.",
        ["Jump off the mountain and use |T132845:0|t[Walk on Air] to fly towards the waypoint location."] = "Springt vom Berg und benutzt |T132845:0|t[Luftwandeln], um zum Ort zu fliegen.",
        ["Jump off the mountain and use |T132845:0|t[Walk on Air] to fly towards the waypoint."] = "Springt vom Berg ab und benutzt |T132845:0|t[Gehen on Luft], um zum Wegpunkt zu fliegen.",
        ["Jump off the tower and use |T132845:0|t[Walk on Air] to fly towards the waypoint location."] = "Springt vom Turm und benutzt |T132845:0|t[Gehen on Luft], um zur Wegpunkt-Position zu fliegen.",
        ["Jump off the tower and use |T132845:0|t[Walk on Air] to fly towards the waypoint locations."] = "Springt vom Turm ab und benutzt |T132845:0|t[Luftwandeln], um zu den Wegpunktstandorten zu fliegen.",
        ["Jump off the tree and use |T132845:0|t[Walk on Air] to fly towards the questgiver."] = "Springt vom Berg herunter und benutzt |T132845:0|t[Gehen on Luft], um zum Questgeber zu fliegen.",
        ["Jump off the tree and use |T132845:0|t[Walk on Air] to fly towards the waypoint location."] = "Springt vom Berg und benutzt |T132845:0|t[Luftwandeln], um zum Ort zu fliegen.",
        ["Jump out of the lodge and die to the mobs below"] = "Springt aus der Hütte und sterbt durch die Mobs darunten",
        ["Jump over the tree root and hug the right to avoid aggroing mobs"] = "Springt über die Baumwurzel und haltet euch rechts, um Mobs zu vermeiden, die euch angreifen könnten",
        ["Keep an eye out for |cRXP_ENEMY_Ghost Howl|r. Loot him for his |T134358:0|t[|cRXP_LOOT_Demon Scarred Cloak|r]. Use it to start the quest"] = "Haltet Ausschau nach |cRXP_ENEMY_Geistheuler|r. Plündert ihn für seinen |T134358:0|t[|cRXP_LOOT_Dämonennarben-Umhang|r]. Benutzt es, um die Quest zu starten",
        ["Keep any |T134304:0|t[Murloc Fins] you might loot. You will need 8 for a quest later"] = "Behaltet alle |T134304:0|t[Murlocflossen], die ihr plündert. Ihr braucht später 8 für eine Quest",
        ["Keep killing |cRXP_ENEMY_Dark Strand mobs|r until you have enough xp to reach level 20"] = "Tötet weiter |cRXP_ENEMY_Mobs des dunklen Strangs|r bis ihr genug XP habt, um Stufe 20 zu erreichen",
        ["Kill |cRXP_ENEMY_\"Badwind\" Bennic::255534|r."] = "Tötet |cRXP_ENEMY_\"Badwind\" Bennic::255534|r.",
        ["Kill |cRXP_ENEMY_Adult Plainstriders|r. Loot them for their |T134028:0|t[|cRXP_LOOT_Tender Strider Meat|r]"] = "Tötet |cRXP_ENEMY_Erwachsener Ebenenschreiter|r. Plündert sie für |T134028:0|t[|cRXP_LOOT_Tender Strider Meat|r]",
        ["Kill |cRXP_ENEMY_Adult Plainstriders|r. Loot them for their |T134028:0|t[|cRXP_LOOT_Tender Strider Meat|r] and |cRXP_LOOT_Talons|r"] = "Tötet |cRXP_ENEMY_Erwachsener Ebenenschreiter|r. Plündert sie für ihr |T134028:0|t[|cRXP_LOOT_Tender Strider Meat|r] und |cRXP_LOOT_Ebenenschreiterkralle|r",
        ["Kill |cRXP_ENEMY_Al'Aketh Assassins::254626|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Assassins::254626|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Brawlers::270201|r and |cRXP_ENEMY_Al'Aketh Healers::254596|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Brawlers::270201|r und |cRXP_ENEMY_Al'Aketh Healers::254596|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Brawlers::270201|r, |cRXP_ENEMY_Al'Aketh Preachers::253195|r, and |cRXP_ENEMY_Al'Aketh Pillagers::253511|r |cRXP_WARN_along the way|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Brawlers::270201|r, |cRXP_ENEMY_Al'Aketh Preachers::253195|r, und |cRXP_ENEMY_Al'Aketh Pillagers::253511|r |cRXP_WARN_unterwegs|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Brawlers::270201|r, |cRXP_ENEMY_Al'Aketh Preachers::253195|r, and |cRXP_ENEMY_Al'Aketh Pillagers::253511|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Brawlers::270201|r, |cRXP_ENEMY_Al'Aketh Preachers::253195|r, und |cRXP_ENEMY_Al'Aketh Pillagers::253511|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Brawlers::270201|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Brawlers::270201|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Brutes::251145|r and |cRXP_ENEMY_Al'Aketh Neophytes::251448|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Brutes::251145|r und |cRXP_ENEMY_Al'Aketh Neophytes::251448|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Converts::251160|r and |cRXP_ENEMY_Roiling Winds::251143|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Converts::251160|r und |cRXP_ENEMY_Roiling Winde::251143|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Footsoldiers::252665|r and |cRXP_ENEMY_Al'Aketh Stormchasers::252664|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Footsoldiers::252665|r und |cRXP_ENEMY_Al'Aketh Stormchasers::252664|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Healers::254596|r and |cRXP_ENEMY_Al'Aketh Brawlers::270201|r."] = "Tötet |cRXP_ENEMY_Al'Aketh Healers::254596|r und |cRXP_ENEMY_Al'Aketh Brawlers::270201|r.",
        ["Kill |cRXP_ENEMY_Al'Aketh Stormcallers::252068|r. Loot them for the |T133647:0|t[|cRXP_LOOT_Stolen Shen'dar Supplies|r]."] = "Tötet |cRXP_ENEMY_Al'Aketh Stormcallers::252068|r. Plündert sie für |T133647:0|t[|cRXP_LOOT_Stolen Shen'dar Vorräte|r].",
        ["Kill |cRXP_ENEMY_Arra'Chea|r (Big black kodo). Kill and loot him for his |cRXP_LOOT_Horn|r"] = "Tötet |cRXP_ENEMY_Arra'Chea|r (Großes schwarzes Kodo). Tötet und plündert ihn für sein |cRXP_LOOT_Horn|r",
        ["Kill |cRXP_ENEMY_Bandit Highwaymen::252820|r. Loot them for the |T133693:0|t[|cRXP_LOOT_Blood-Stained Bandit Masks|r]."] = "Tötet |cRXP_ENEMY_Bandit Highwaymen::252820|r. Plündert sie für |T133693:0|t[|cRXP_LOOT_Blood-Stained Räuber Masks|r].",
        ["Kill |cRXP_ENEMY_Barak Kodobane|r. Loot him for his |cRXP_LOOT_Head|r"] = "Tötet |cRXP_ENEMY_Barak Kodobann|r. Plündert ihn für seinen |cRXP_LOOT_kopf|r",
        ["Kill |cRXP_ENEMY_Baron Longshore|r. Loot him for his |cRXP_LOOT_Head|r"] = "Tötet |cRXP_ENEMY_Baron Küstenschipper|r. Plündert ihn für seinen |cRXP_LOOT_Kopf|r",
        ["Kill |cRXP_ENEMY_Battleboars|r. Loot them for their |cRXP_LOOT_Flanks|r and |cRXP_LOOT_Snouts|r"] = "Tötet |cRXP_ENEMY_Kampfeber|r. Plündert sie für ihre |cRXP_LOOT_Kampfeberflanke|r und |cRXP_LOOT_Kampfeberschnauze|r",
        ["Kill |cRXP_ENEMY_Bears::250926|r. Loot them for |T132136:0|t[|cRXP_LOOT_Scrawny Ursera Claw|r]."] = "Tötet |cRXP_ENEMY_Bears::250926|r. Plündert sie für |T132136:0|t[|cRXP_LOOT_Scrawny Ursera Klaue|r].",
        ["Kill |cRXP_ENEMY_Bellygrub|r. Loot him for his |cRXP_LOOT_Tusk|r"] = "Tötet |cRXP_ENEMY_Stopfwanst|r. Plündert ihn für seine |cRXP_LOOT_Hauer|r",
        ["Kill |cRXP_ENEMY_Bloodfeather Harpies|r on the way to Darnassus. Loot them for their |cRXP_LOOT_Belts|r. |cRXP_WARN_You don't have to complete this objective now|r"] = "Tötet |cRXP_ENEMY_Harpyie der Blutfedern|r auf dem Weg nach Darnassus. Plündert sie für ihre |cRXP_LOOT_Gürtel|r. |cRXP_WARN_Ihr müsst dieses Ziel jetzt nicht abschließen|r",
        ["Kill |cRXP_ENEMY_Burning Blade Orcs|r. Loot them for their |cRXP_LOOT_Collars|r and for a |cRXP_LOOT_Lieutenant's Insignia|r"] = "Tötet |cRXP_ENEMY_Burning Blade Orks|r. Sammelt Beute für |cRXP_LOOT_Senghalsband|r und für |cRXP_LOOT_Insignien des Lieutenants|r",
        ["Kill |cRXP_ENEMY_Captain Perrine|r, |cRXP_ENEMY_Scarlet Zealots|r and |cRXP_ENEMY_Scarlet Missionaries|r. Loot them for their |cRXP_LOOT_Scarlet Insignia Rings|r"] = "Tötet |cRXP_ENEMY_Captain Perrine|r, |cRXP_ENEMY_Scharlachroter Zelot|r und |cRXP_ENEMY_Scharlachroter Missionar|r. Plündert sie für ihre |cRXP_LOOT_Scharlachroter Insignienring|r",
        ["Kill |cRXP_ENEMY_Captain Vachon|r inside the tower"] = "Tötet |cRXP_ENEMY_Captain Vachon|r im Turm",
        ["Kill |cRXP_ENEMY_Chakuyak|r. Loot it for its |cRXP_LOOT_Pelt|r"] = "Tötet |cRXP_ENEMY_Chakuyak|r. Plündert sie für den |cRXP_LOOT_Pelz|r",
        ["Kill |cRXP_ENEMY_Chief Sharptusk Thornmantle|r inside the big hut. Loot him for his |cRXP_LOOT_Head|r"] = "Tötet |cRXP_ENEMY_Häuptling Spitzhauer Dornenmantel|r in der großen Hütte. Plündert seinen |cRXP_LOOT_Kopf|r",
        ["Kill |cRXP_ENEMY_Cirrusfly Queen::251404|r."] = "Tötet |cRXP_ENEMY_Cirrusfly Königin::251404|r.",
        ["Kill |cRXP_ENEMY_Commander Cyclas::251966|r. Loot him for |T134161:0|t[|cRXP_LOOT_Commander Cyclas's Head|r]."] = "Tötet |cRXP_ENEMY_Commander Cyclas::251966|r. Plündert sie für |T134161:0|t[|cRXP_LOOT_Commander Cyclas's Kopf|r].",
        ["Kill |cRXP_ENEMY_Commander Haalien::253622|r. Loot him for |T134161:0|t[|cRXP_LOOT_Severed Head|r] and |T135332:0|t[|cRXP_LOOT_Ripped Missive|r]."] = "Tötet |cRXP_ENEMY_Commander Haalien::253622|r. Plündert sie für |T134161:0|t[|cRXP_LOOT_Severed Kopf|r] und |T135332:0|t[|cRXP_LOOT_Ripped Missive|r].",
        ["Kill |cRXP_ENEMY_Crag Boars|r. Loot them for |T133970:0|t|cRXP_LOOT_[Chunks of Boar Meat]|r and |cRXP_LOOT_Crag Boar Ribs|r"] = "Tötet |cRXP_ENEMY_Klippeneber|r. Plündert sie für |T133970:0|t|cRXP_LOOT_[Brocken Eberfleisch]|r und |cRXP_LOOT_Klippeneberrippchen|r",
        ["Kill |cRXP_ENEMY_Cursed Highbornes|r, |cRXP_ENEMY_Writhing Highbornes|r and |cRXP_ENEMY_Wailing Highbornes|r. Loot them for their |cRXP_LOOT_Relics|r"] = "Tötet |cRXP_ENEMY_Verfluchte Hochgeborene|r, |cRXP_ENEMY_Zuckender Hochgeborener|r und |cRXP_ENEMY_Klagende Hochgeborene|r. Plündert sie für ihre |cRXP_LOOT_Relikte|r",
        ["Kill |cRXP_ENEMY_Daggerfang|r, he |cRXP_WARN_might be patrolling along the shore|r. Loot him for |T3736888:0|t[|cRXP_LOOT_Marek's Croc-Hunting Knife|r]"] = "Tötet |cRXP_ENEMY_Daggerfang|r, |cRXP_WARN_er könnte entlang des Ufers patrouillieren|r. Plündert ihn für |T3736888:0|t[|cRXP_LOOT_Marek's Krokodil-Jagdmesser|r]",
        ["Kill |cRXP_ENEMY_Dark Iron Spies|r. Loot them for the |cRXP_LOOT_Dark Iron Script|r"] = "Tötet |cRXP_ENEMY_Spion der Dunkeleisenzwerge|r. Plündert sie für |cRXP_LOOT_Dunkeleisenmanuskript|r",
        ["Kill |cRXP_ENEMY_Dark Iron Spies|r. Loot them for the |T237385:0|t[|cRXP_LOOT_Dark Iron Map|r]"] = "Tötet |cRXP_ENEMY_Spion der Dunkeleisenzwerge|r. Plündert sie für |T237385:0|t[|cRXP_LOOT_Dunkeleisenkarte |r]",
        ["Kill |cRXP_ENEMY_Dark Strand Cultists|r and |cRXP_ENEMY_Dark Strand Adepts|r. Loot them for the |cRXP_LOOT_Glowing Soul Gem|r"] = "Tötet |cRXP_ENEMY_Kultist des dunklen Strangs|r und |cRXP_ENEMY_Adept des dunklen Strangs|r. Plündert sie für |cRXP_LOOT_Leuchtender Seelenedelstein|r",
        ["Kill |cRXP_ENEMY_Dark Strand Cultists|r, |cRXP_ENEMY_Dark Strand Adepts|r, |cRXP_ENEMY_Dark Strand Enforcers|r and |cRXP_ENEMY_Dark Strand Excavators|r. Loot them for the |cRXP_LOOT_Glowing Soul Gem|r"] = "Tötet |cRXP_ENEMY_Kultist des dunklen Strangs|r, |cRXP_ENEMY_Adept des dunklen Strangs|r, |cRXP_ENEMY_Vollstrecker des dunklen Strangs|r und |cRXP_ENEMY_Ausgräber des dunklen Strangs|r. Plündert sie für |cRXP_LOOT_Leuchtender Seelenedelstein|r",
        ["Kill |cRXP_ENEMY_Darkhounds|r. Loot them for their |cRXP_LOOT_Blood|r and |cRXP_LOOT_Hides|r"] = "Tötet |cRXP_ENEMY_Schattenhunde|r. Plündert sie für |cRXP_LOOT_Blut|r und |cRXP_LOOT_Bälge|r",
        ["Kill |cRXP_ENEMY_Defias Bandits|r. Loot them for the |T134939:0|t[|cRXP_LOOT_Westfall Deed|r]"] = "Tötet |cRXP_ENEMY_Bandit der Defias|r. Plündert sie für |T134939:0|t[|cRXP_LOOT_Westfall-Urkunde|r]",
        ["Kill |cRXP_ENEMY_Defias Trappers|r and |cRXP_ENEMY_Defias Smugglers|r. Loot them for their |T133694:0|t|cRXP_LOOT_Red Leather Bandanas|r"] = "Tötet |cRXP_ENEMY_Fallensteller der Defias|r und |cRXP_ENEMY_Schmuggler der Defias|r. Plündert sie für |T133694:0|t|cRXP_LOOT_Rotes Lederkopftuch|r",
        ["Kill |cRXP_ENEMY_Deth'ryll Satyrs|r. Loot them for the |cRXP_LOOT_Ancient Moonstone Seal|r"] = "Tötet |cRXP_ENEMY_Satyr der Deth'ryll|r. Plündert sie für |cRXP_LOOT_Altes Mondstein-Siegel|r",
        ["Kill |cRXP_ENEMY_Devlin|r. Loot him for his |cRXP_LOOT_Remains|r"] = "Tötet |cRXP_ENEMY_Devlin|r. Plündert ihn für |cRXP_LOOT_Devlins sterbliche Überreste|r",
        ["Kill |cRXP_ENEMY_Dreadmaw Crocolisks|r on the way. Loot them for |cRXP_LOOT_Kron's Amulet|r"] = "Tötet |cRXP_ENEMY_Schaudermagenkrokilisk|r auf dem Weg. Plündert sie für |cRXP_LOOT_Krons Amulett|r",
        ["Kill |cRXP_ENEMY_Duskbats|r. Loot them for their |cRXP_LOOT_Pelts|r and |cRXP_LOOT_Wing Membranes|r"] = "Tötet |cRXP_ENEMY_Nachtsauger|r. Plündert sie für |cRXP_LOOT_Pelze|r und |cRXP_LOOT_Nachtsaugerflügelmembran|r",
        ["Kill |cRXP_ENEMY_Echeyakee|r. Loot him for |cRXP_LOOT_Echeyakee's Hide|r"] = "Tötet |cRXP_ENEMY_Echeyakee|r. Plündert ihn für |cRXP_LOOT_Echeyakees Balg|r",
        ["Kill |cRXP_ENEMY_Elder Black Bears|r. Loot them for their |T134027:0|t|cRXP_LOOT_Bear Meat|r"] = "Tötet |cRXP_ENEMY_Alter Schwarzbär|r. Plündert sie für |T134027:0|t|cRXP_LOOT_Bärenfleisch|r",
