        ["Kill |cRXP_ENEMY_Webwood Spiders|r. Loot them for their |cRXP_LOOT_Ichor|r and |cRXP_LOOT_Venom Sacs|r"] = "Tötet |cRXP_ENEMY_Waldweberspinne|r. Plündert sie für |cRXP_LOOT_Sekret|r und |cRXP_LOOT_Giftbeutel|r",
        ["Kill |cRXP_ENEMY_Wind Hollows::251676|r."] = "Tötet |cRXP_ENEMY_Wind Hollows::251676|r.",
        ["Kill |cRXP_ENEMY_Windmistress Gaedress|r. Loot her for her |T133333:0|t[|cRXP_LOOT_Amulet|r]"] = "Tötet |cRXP_ENEMY_Windmeisterin Gaedress|r. Plündert sie für |T133333:0|t[|cRXP_LOOT_Amulett|r]",
        ["Kill |cRXP_ENEMY_Windshaper Novice Seers::257532|r."] = "Tötet |cRXP_ENEMY_Windshaper Novice Seers::257532|r.",
        ["Kill |cRXP_ENEMY_Windsong Crawlers::254588|r |cRXP_WARN_along the way|r. Loot them for |T133972:0|t[|cRXP_LOOT_Windsong Crawler Meat|r]."] = "Tötet |cRXP_ENEMY_Windsong Crawlers::254588|r |cRXP_WARN_unterwegs|r. Plündert sie, um |T133972:0|t[|cRXP_LOOT_Windsong Kriecher Fleisch|r] zu erhalten.",
        ["Kill |cRXP_ENEMY_Windsong Crawlers::254588|r. Loot them for |T133972:0|t[|cRXP_LOOT_Windsong Crawler Meat|r]."] = "Tötet |cRXP_ENEMY_Windsong Crawlers::254588|r. Plündert sie für |T133972:0|t[|cRXP_LOOT_Windsong Kriecher Fleisch|r].",
        ["Kill |cRXP_ENEMY_Witchmother Arysa|r. Loot her for her |T133324:0|t[|cRXP_LOOT_Amulet|r]"] = "Tötet |cRXP_ENEMY_Hexenmutter Arysa|r. Plündert sie für ihre |T133324:0|t[|cRXP_LOOT_Amulett|r]",
        ["Kill |cRXP_ENEMY_Xabraxxis|r. Open the |cRXP_PICK_Xabraxxis' Demon Bag|r he drops on the ground. Loot it for the |cRXP_LOOT_Talisman of Corruption|r"] = "Tötet |cRXP_ENEMY_Xabraxxis|r. Öffnet die |cRXP_PICK_Xabraxxis Dämonentasche|r, die er auf den Boden fallen lässt. Plündert sie für den |cRXP_LOOT_Talisman der Verderbnis|r",
        ["Kill |cRXP_ENEMY_Yarrog Baneshadow|r. Loot him for the |cRXP_LOOT_Burning Blade Medallion|r"] = "Tötet |cRXP_ENEMY_Yarrog Schattenbann|r. Plündert ihn für das |cRXP_LOOT_Medaillon der Burning Blade|r",
        ["Kill |cRXP_ENEMY_Young Black Bears|r or |cRXP_ENEMY_Ice Claw Bears|r. Loot them for their |cRXP_LOOT_Thick Bear Fur|r"] = "Tötet |cRXP_ENEMY_Junger Schwarzbär|r oder |cRXP_ENEMY_Eisklauenbär|r. Plündert sie für |cRXP_LOOT_Dickes Bärenfell|r",
        ["Kill |cRXP_ENEMY_Young Goretusks|r and |cRXP_ENEMY_Young Fleshrippers|r. Loot them for their |cRXP_LOOT_Vulture Meat|r, |cRXP_LOOT_Snouts|r and |cRXP_LOOT_Livers|r"] = "Tötet |cRXP_ENEMY_Junger Geiferzahn|r und |cRXP_ENEMY_Junger Fleischreißer|r. Plündert sie für |cRXP_LOOT_Sehniges Geierfleisch|r, |cRXP_LOOT_Geiferzahnschnauze|r und |cRXP_LOOT_Geiferzahnleber|r",
        ["Kill |cRXP_ENEMY_Young Night Web Spiders|r close to the cave entrance"] = "Tötet die |cRXP_ENEMY_Junger Nachtweber|r in der Nähe des Höhleneingangs",
        ["Kill |cRXP_ENEMY_Young Wolves|r until you have 10c+ worth of vendor trash"] = "Tötet |cRXP_ENEMY_Junge Wölfe|r bis ihr 10 Kupfer+ Vendor-Schrott habt",
        ["Kill |cRXP_ENEMY_Zaal Stormshield::257196|r. Loot him for the |T134959:0|t[|cRXP_LOOT_Skybreaker Bulwark|r]."] = "Tötet |cRXP_ENEMY_Zaal Sturmschild::257196|r. Plündert sie für |T134959:0|t[|cRXP_LOOT_Skybreaker Bollwerk|r].",
        ["Kill |cRXP_ENEMY_Zalazane|r. Loot him for his |cRXP_LOOT_Head|r"] = "Tötet |cRXP_ENEMY_Zalazane|r. Plündert ihn für seinen |cRXP_LOOT_Kopf|r",
        ["Kill a |cRXP_ENEMY_Razormane Water Seeker|r or |cRXP_ENEMY_Razormane Thornweaver|r. Loot them for a |cRXP_LOOT_Fire Tar|r"] = "Tötet einen |cRXP_ENEMY_Wassersucher der Grimmhauer|r oder |cRXP_ENEMY_Dornenwirker der Grimmhauer|r. Plündert sie für |cRXP_LOOT_Feuerteer|r",
        ["Kill all |cRXP_ENEMY_Lasher Sproutlings|r you see on the way to Denalan. Loot them for |T237424:0|t[|cRXP_LOOT_Dewy Lasher Fronds|r]"] = "Tötet alle |cRXP_ENEMY_Peitscher Sprösslinge|r, die ihr auf dem Weg zu Denalan seht. Plündert sie für die |T237424:0|t[|cRXP_LOOT_Taubedeckter Peitscherwedel|r]",
        ["Kill all |cRXP_ENEMY_Lasher Sproutlings|r you see on the way to the cat. Loot them for |T237424:0|t[|cRXP_LOOT_Dewy Lasher Fronds|r]"] = "Tötet alle |cRXP_ENEMY_Blühenden Sprösslinge|r, die ihr auf dem Weg zur Katze seht. Plündert sie für die |T237424:0|t[|cRXP_LOOT_Taubedeckter Peitscherwedel|r]",
        ["Kill all types of |cRXP_ENEMY_Wendigos|r. Loot them for their |cRXP_LOOT_Wendigo Manes|r"] = "Tötet alle |cRXP_ENEMY_Wendigos|r. Plündert sie für |cRXP_LOOT_Wendigomähne|r",
        ["Kill and loot |cRXP_WARN_Ghostpaw Runners|r you encounter while questing. Keep any |T133970:0|t[|cRXP_LOOT_Lean Wolf Flanks|r] you get. You will need 10 for a cooking quest later"] = "Tötet und plündert |cRXP_WARN_Geisterpfotenläufer|r,die ihr beim Questen antrefft. Behaltet alle |T133970:0|t[|cRXP_LOOT_Magere Wolfflanke|r], die ihr erhaltet. Ihr werdet später 10 für eine Kochquest benötigen",
        ["Kill any |cRXP_ENEMY_Zhevra|r you see. Loot them for their |cRXP_LOOT_Hooves|r"] = "Tötet jedes |cRXP_ENEMY_Zhevra|r, das ihr seht. Plündert sie für ihre |cRXP_LOOT_Hufe|r",
        ["Kill every |cRXP_ENEMY_Raptor|r you see. Loot them for their |cRXP_LOOT_Heads|r"] = "Tötet jeden |cRXP_ENEMY_Raptor|r, den ihr seht. Plündert sie für ihren |cRXP_LOOT_Kopf|r",
        ["Kill mobs along the way if you can do so without losing time."] = "Tötet Mobs unterwegs, wenn ihr das tun könnt, ohne Zeit zu verlieren.",
        ["Kill the |cRXP_ENEMY_Bloodtalon Matriarch|r. Loot it for the |cRXP_LOOT_Bloodtalon Matriarch Eggs|r"] = "Tötet die |cRXP_ENEMY_Blutklauenmatriarchin|r. Plündert sie für |cRXP_LOOT_Blutklauenmatriachin Eier|r",
        ["Kill the |cRXP_ENEMY_Greymist Warriors|r and |cRXP_ENEMY_Greymist Hunters|r in the camp"] = "Tötet die |cRXP_ENEMY_Krieger der Grauflossen|r und |cRXP_ENEMY_Jäger der Grauflossen|r im Lager",
        ["Kill the |cRXP_ENEMY_Minor Manifestation of Fire|r. Loot him for a |cRXP_LOOT_Glowing Ember|r"] = "Tötet die |cRXP_ENEMY_Schwache Feuermanifestation|r. Plündert sie für eine |cRXP_LOOT_Leuchtendes Holzscheit|r",
        ["Kill the |cRXP_ENEMY_Minor Manifestation of Fire|r. Loot it for the |cRXP_LOOT_Glowing Ember|r"] = "Tötet die |cRXP_ENEMY_Schwache Feuermanifestation|r. Plündert sie, um |cRXP_LOOT_Leuchtendes Holzscheit|r zu erhalten",
        ["Kill the |cRXP_ENEMY_Whispering Horror|r (elite). Loot him for |T134438:0|t[|cRXP_LOOT_Whispering Horror Residue|r]"] = "Tötet die |cRXP_ENEMY_Flüsternder Schrecken|r (elite). Plündert ihn für |T134438:0|t[|cRXP_LOOT_Überreste des flüsternden Schreckens|r]",
        ["Kite |cRXP_ENEMY_Vagash|r into the |cRXP_FRIENDLY_Dun Morogh Mountaineer|r"] = "Lockt |cRXP_ENEMY_Vagash|r zu den |cRXP_FRIENDLY_Gebirgsjäger von Dun Morogh|r",
        ["Kite |cRXP_ENEMY_Vagash|r to |cRXP_FRIENDLY_Rudra Amberstill|r"] = "Lockt |cRXP_ENEMY_Vagash|r zu |cRXP_FRIENDLY_Rudra Amberstill|r",
        ["Leave the cave"] = "Verlasst die Höhle",
        ["Leave the Cave"] = "Verlasst die Höhle",
        ["Leave the Kolkar base"] = "Verlasst das Kolkar-Lager",
        ["Leave the tram and enter Ironforge"] = "Verlasst die Straßenbahn und betretet Eisenschmiede",
        ["Leave Undercity through the Sewers"] = "Verlasst die Unterstadt durch die Kanalisation",
        ["Logout skip on the ledge behind the eggs. Move your character until it looks like they're floating, then log out, and back in."] = "Nutzt den Auslog-Skip auf dem Vorsprung hinter den Eiern. Bewegt den Charakter von Euch, bis es aussieht, als würden sie schweben, dann loggt euch aus und wieder ein.",
        ["Loot |cRXP_ENEMY_Dustwind Storm Witches|r for a |T134336:0|t[|cRXP_LOOT_Dull Storm Orb|r]. Use it to accept the quest"] = "Plündert |cRXP_ENEMY_Sturmhexe der Staubschwingen|r für eine |T134336:0|t[|cRXP_LOOT_Matte Sturmkugel|r]. Benutzt sie, um die Quest anzunehmen",
        ["Loot |cRXP_LOOT_Elune's Tear|r on the ground"] = "Loote |cRXP_LOOT_Elunes Träne|r auf dem Boden",
        ["Loot |cRXP_LOOT_Lunar Fungi|r on the ground throughout caves"] = "Beute |cRXP_LOOT_Lunarfungus|r auf dem Boden in der Höhle",
        ["Loot |cRXP_LOOT_Thazz'ril's Pick|r against the wall"] = "Plündert |cRXP_LOOT_Thazz'rils Hacke|r an der Wand",
        ["Loot |cRXP_PICK_Abandoned Training Weapons|r on the ground"] = "Plündert |cRXP_PICK_Zurückgelassene Übungswaffe|r auf dem Boden",
        ["Loot |cRXP_PICK_Andron's Bookshelf|r behind |cRXP_FRIENDLY_Andron|r"] = "Plündert |cRXP_PICK_Andron's Bücherregal|r hinter |cRXP_FRIENDLY_Andron|r",
        ["Loot |cRXP_PICK_Chen's Empty Keg|r from the ground and start the quest"] = "Plündert |cRXP_PICK_Chens leeres Fässchen|r vom Boden und startet die Quest",
        ["Loot |cRXP_PICK_Dry Branches|r on the ground underneath trees near Brill"] = "Plündert |cRXP_PICK_Trockener Ast|r auf dem Boden unter Bäumen in der Nähe von Brill",
        ["Loot |cRXP_PICK_Flintfire's Shipments|r on the ground inside the Grizzled Den cave"] = "Sammelt |cRXP_PICK_Flintfires Lieferung|r vom Boden in dem altgedienten Bau",
        ["Loot |cRXP_PICK_Gozwin's Mechanic's Log|r on the ground"] = "Plündert |cRXP_PICK_Gozwins Mechanikerlogbuch|r auf dem Boden",
        ["Loot |cRXP_PICK_Gunther's Books|r for |cRXP_LOOT_The Lich's Spellbook|r on the island in Brightwater Lake"] = "Plündert |cRXP_PICK_Gunthers Bücher|r für |cRXP_LOOT_Das Zauberbuch des Lichs|r auf der Insel im Blendwassersee",
        ["Loot |cRXP_PICK_Milly's Harvest|r on the ground"] = "Plündert |cRXP_PICK_Millys Ernte|r auf dem Boden",
        ["Loot |cRXP_PICK_Perrine's Chest|r for |T133733:0|t[Egalin's Grimoire]"] = "Beute |cRXP_PICK_Perrines Truhe|r für |T133733:0|t[Egalins Zauberfoliant]",
        ["Loot |cRXP_PICK_Perrine's Chest|r on the ground for |T133733:0|t[Egalin's Grimoire]"] = "Beute |cRXP_PICK_Perrine's Truhe|r auf dem Boden für |T133733:0|t[Egalins Zauberfoliant]",
        ["Loot |cRXP_PICK_Windfury Cones|r on the ground"] = "Plündert |cRXP_PICK_Windzornzapfen|r auf dem Boden",
        ["Loot |T134460:0|t[|cRXP_LOOT_Gnarlpine Totems|r] from the Grell Camps"] = "Plündert |T134460:0|t[|cRXP_LOOT_Totem der Knarzklauen|r] aus den Grell Camps",
        ["Loot |T134460:0|t[|cRXP_PICK_Gnarlpine Totems|r] from the Grell Camps"] = "Sammelt |T134460:0|t[|cRXP_PICK_Totem der Knarzklauen|r] aus den Grell-Lagern",
        ["Loot a |cRXP_LOOT_Webwood Egg|r on the ground at the back of the Cave"] = "Sammelt das |cRXP_LOOT_Waldweberei|r auf dem Boden am hinteren Ende der Höhle",
        ["Loot any of the plants on the ground for a |cRXP_PICK_Balnir Snapdragon|r"] = "Plündert eine der Pflanzen am Boden für einen |cRXP_PICK_Balnirlöwenmäulchen|r",
        ["Loot one of the |cRXP_LOOT_Skulls|r on the ground"] = "Plündert einen der |cRXP_LOOT_Schädel|r vom Boden",
        ["Loot the |cRXP_ENEMY_Rockjaw Skullthumpers|r and |cRXP_ENEMY_Rockjaw Bonesnappers|r for the |T132621:0|t[|cRXP_LOOT_Empty Powder Keg|r]"] = "Plündert die |cRXP_ENEMY_Schädelhauer der Felsenkiefer|r und |cRXP_ENEMY_Knochenknacker der Felsenkiefer|r für das|T132621:0|t[|cRXP_LOOT_Leeres Pulverfass|r]",
        ["Loot the |cRXP_LOOT_Bundle of Wood|r on the ground. |cRXP_WARN_They are found beneath the trees|r"] = "Plündert die |cRXP_LOOT_Kleinholzbündel|r vom Boden |cRXP_WARN_am Stamm der Bäume|r",
        ["Loot the |cRXP_LOOT_Bundles of Wood|r on the ground at the base of the trees"] = "Plündert die |cRXP_LOOT_Kleinholzbündel|r vom Boden am Stamm der Bäume",
        ["Loot the |cRXP_LOOT_Cactus Apples|r near the Cacti"] = "Beute |cRXP_LOOT_Kaktusapfel|r in der Nähe der Kakteen",
        ["Loot the |cRXP_LOOT_Pumpkins|r found in the field"] = "Sammelt die |cRXP_LOOT_Kürbisse|r im Feld",
        ["Loot the |cRXP_LOOT_Scaber Stalks|r and a |cRXP_LOOT_Death Cap|r on the ground"] = "Plündert |cRXP_LOOT_Schorfstängling|r und eine |cRXP_LOOT_Todeskappe|r auf dem Boden",
        ["Loot the |cRXP_LOOT_Water Pitcher|r on the well behind |cRXP_FRIENDLY_Greatmother Hawkwind|r"] = "Plündert |cRXP_LOOT_Wasserkrug|r auf dem Brunnen hinter |cRXP_FRIENDLY_Großmutter Hawkwind|r",
        ["Loot the |cRXP_PICK_Book|r in the shelf"] = "Sammelt das |cRXP_PICK_Buch|r im Regal",
        ["Loot the |cRXP_PICK_Bottles of Whispering Elixir|r on the ground and on the walls"] = "Plündert die |cRXP_PICK_Flasche mit flüsterndem Elixier|r auf dem Boden und an den Wänden",
        ["Loot the |cRXP_PICK_Duskweed Petals|r at the farms in Elwynn Forest"] = "Sammelt die |cRXP_PICK_Dämmerkrautblüte|r bei den Farmen im Wald von Elwynn",
        ["Loot the |cRXP_PICK_Fishing Nets|r in the water for the |cRXP_LOOT_Half-Eaten Fish|r"] = "Plündert die |cRXP_PICK_Fischernetze|r im Wasser für den |cRXP_LOOT_Halb aufgegessener Fisch|r",
        ["Loot the |cRXP_PICK_Gnomish Toolboxes|r inside and around the boats"] = "Plündert den |cRXP_PICK_Gnomen-Werkzeugkasten|r in und um die Boote herum",
        ["Loot the |cRXP_PICK_Grain Sacks|r and |cRXP_PICK_Meat Haunches|r on the ground for |cRXP_LOOT_Stolen Supplies|r"] = "Sammelt die |cRXP_PICK_Getreidesäcke|r und |cRXP_PICK_Fleischkeulen|r vom Boden für |cRXP_LOOT_Gestohlene Versorgungsgüter|r",
        ["Loot the |cRXP_PICK_Handful of Cattails|r and |cRXP_PICK_Speargrass Cuttings|r in the water"] = "Plündert |cRXP_PICK_Handful of Cattails|r und |cRXP_PICK_Speargrass Cuttings|r im Wasser",
        ["Loot the |cRXP_PICK_Junk Piles|r on the ground for |cRXP_LOOT_Shiny Junk|r"] = "Plündert die |cRXP_PICK_Schrotthaufen|r auf dem Boden nach |cRXP_LOOT_Glänzender Plunder|r",
        ["Loot the |cRXP_PICK_Junk Piles|r on the ground for |cRXP_LOOT_Shiny Junk|r. |cRXP_WARN_If you are unable to loot these due to too many |cRXP_ENEMY_Murlocs|r, skip this objective|r"] = "Plündert die |cRXP_PICK_Schrotthaufen|r auf dem Boden für |cRXP_LOOT_Glänzender Plunder|r. |cRXP_WARN_Falls ihr diese aufgrund zu vieler|cRXP_ENEMY_Murlocs|r nicht plündern könnt, überspringt dieses Ziel|r",
        ["Loot the |cRXP_PICK_Stardust Covered Bushes|r for the |cRXP_LOOT_Handful of Stardust|r"] = "Loote die |cRXP_PICK_Mit Sternenstaub bedeckter Busch|r für |cRXP_LOOT_Hand voll Sternenstaub|r",
        ["Loot the |cRXP_PICK_Stolen Iron Chest|r for its |cRXP_LOOT_Forged Steel Bars|r"] = "Plündert die |cRXP_PICK_Gestohlene Eisentruhe|r für ihre |cRXP_LOOT_Schmiedestahlbarren|r",
        ["Loot the |cRXP_PICK_Weapon Racks|r and |cRXP_PICK_Stolen Weapons|r the ground"] = "Sammelt die |cRXP_PICK_Waffenständer|r und |cRXP_PICK_Gestohlene Waffen|r vom Boden",
        ["Loot the |T134269:0|t[|cRXP_LOOT_Dirt-stained Map|r] on the ground. Use it to start the quest"] = "Plündert die |T134269:0|t[|cRXP_LOOT_Schmutzbefleckte Karte|r] vom Boden. Benutzt es, um die Quest zu starten",
        ["Loot the 3 |cRXP_LOOT_Fel Cones|r from the locations marked on your map."] = "Plündert die 3 |cRXP_LOOT_Teufelszapfen|r von den Orten auf eurerKarte.",
        ["Loot the orange |cRXP_PICK_Rocks|r on the ground"] = "Plündert die orangen |cRXP_PICK_Rocks|r auf dem Boden",
        ["Loot them for |T133972:0|t[|cRXP_LOOT_Strider Meat|r] and |T132832:0|t[|cRXP_LOOT_Small Eggs|r]."] = "Plündert sie für |T133972:0|t[|cRXP_LOOT_Strider Fleisch|r] und |T132832:0|t[|cRXP_LOOT_Small Eggs|r].",
        ["Loot them for |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r]."] = "Plündert sie für |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r].",
        ["Loot them for |T1508517:0|t[|cRXP_LOOT_Shriekling Talons|r] and |T132927:0|t[|cRXP_LOOT_Pristine Shriekling Feathers|r]."] = "Plündert sie für |T1508517:0|t[|cRXP_LOOT_Shriekling Krallen|r] und |T132927:0|t[|cRXP_LOOT_Pristine Shriekling Feders|r].",
        ["Loot them for |T1508517:0|t[|cRXP_LOOT_Shriekling Talons|r]."] = "Plündert sie für |T1508517:0|t[|cRXP_LOOT_Shriekling Krallen|r].",
        ["Loot them for |T237416:0|t[|cRXP_LOOT_Prideclaw Pelts|r]."] = "Plündert sie für |T237416:0|t[|cRXP_LOOT_Prideclaw Pelts|r].",
        ["Loot them for |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r] and |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r]."] = "Plündert sie für |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r] und |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r].",
        ["Loot them for |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r], |T133856:0|t[|cRXP_LOOT_Al'Aketh Cultist's Ears|r] and |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r]."] = "Plündert sie für |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r], |T133856:0|t[|cRXP_LOOT_Al'Aketh Cultist's Ohren|r] und |T1379232:0|t[|cRXP_LOOT_Al'Aketh Windstone Charms|r].",
        ["Loot them for |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r]."] = "Plündert sie für |T4622283:0|t[|cRXP_LOOT_Bloody Heirlooms|r].",
        ["Loot them for the |T1020384:0|t[Signet of Akir]"] = "Plündert sie für |T1020384:0|t[Signet of Akir]",
        ["Loot them for the |T132927:0|t[|cRXP_LOOT_Pristine Shriekling Feathers|r]."] = "Plündert sie für |T132927:0|t[|cRXP_LOOT_Pristine Shriekling Feders|r].",
        ["Loot them for the |T133856:0|t[|cRXP_LOOT_Al'Aketh Cultist's Ears|r]."] = "Plündert sie für |T133856:0|t[|cRXP_LOOT_Al'Aketh Cultist's Ohren|r].",
        ["Loot them for their |cRXP_LOOT_Okra|r and |cRXP_LOOT_Flasks of Oil|r"] = "Plündert sie für ihr |cRXP_LOOT_Okra|r und ihr |cRXP_LOOT_Fläschchen Öl|r",
        ["Make Sharpening Stones/Bandages while you wait"] = "Macht Wetzsteine/Bandagen, während ihr wartet",
        ["Make sure your HS cooldown is <10 min"] = "Stellt sicher, dass euer Ruhestein Ablinkzeit <10 min ist",
        ["Make your way up the mountain"] = "Macht von Euch den Weg den Berg hinauf",
        ["Manually drag the reagent bag into the reagent bag slot. Right-clicking it will place it in an empty general bag slot instead"] = "Zieht den Reagenzienbeutel manuell in den Reagenzienbeutel-Platz. Ein Rechtsklick wird ihn stattdessen in einen leeren allgemeinen Beutel-Platz platzieren.",
        ["Move toward the second floor of the keep"] = "Bewegt euch zum zweiten Stock der Burg",
        ["Next to a small tree"] = "Neben einem kleinen Baum",
        ["Next to the massive tree"] = "Neben dem riesiegen Baum",
        ["Note that you have selected the single target Mage guide. Single target is a lot safer than AoE Mage, but a LOT slower"] = "Hinweis: Ihr habt den Single-Target-Magier-Guide ausgewählt. Single Target ist viel sicherer als AoE Magier, aber VIEL langsamer",
        ["On the small hill"] = "Auf dem kleinen Hügel",
        ["Once you get past the furbolg area, die on purpose and respawn at the Darnassus graveyard"] = "Sobald ihr das Furbolg-Areal hinter euch habt, sterbt absichtlich und respawnt am Friedhof von Darnassus",
        ["Once your lockpicking is 70, go to the bottom floor of the ship and open |cRXP_PICK_The Jewel of the Southsea|r"] = "Sobald Eure Schlösserkunst 70 ist, geht ins Untergeschoss des Schiffes und öffnet |cRXP_PICK_Das Juwel der Südlichen Meere|r",
        ["Only use ranged attacks while running from it, avoid being at melee range"] = "Nutzt nur Fernkampfangriffe, während ihr vor ihm wegrennt, vermeidet Nahkampfreichweite",
        ["Open |cRXP_PICK_Alexston's Chest|r. Loot it for |cRXP_LOOT_A Simple Compass|r"] = "Öffne |cRXP_PICK_Alexstons Truhe|r. Plündert sie für |cRXP_LOOT_Ein einfacher Kompass|r",
        ["Open |cRXP_PICK_Benedict's Chest|r. Loot it for the |T133471:0|t[|cRXP_LOOT_Aged Envelope|r]"] = "Öffnet |cRXP_PICK_Benedict's Truhe|r. Plündert sie für |T133471:0|t[|cRXP_LOOT_Vergilbter Umschlag|r]",
        ["Open |cRXP_PICK_Furlbrow's Wardrobe|r. Loot it for |cRXP_LOOT_Furlbrow's Pocket Watch|r"] = "Öffnet |cRXP_PICK_Furlbrows Kleiderschrank|r. Plündert sie für |cRXP_LOOT_Furlbrows Taschenuhr|r",
        ["Open |cRXP_PICK_Kerlonian's Chest|r. Loot it for the |T134229:0|t[|cRXP_LOOT_Horn of Awakening|r]"] = "Öffnet |cRXP_PICK_Kerlonians Truhe|r. Plündert sie für |T134229:0|t[|cRXP_LOOT_Horn der Erweckung|r]",
        ["Open |cRXP_PICK_Lucius's Lockbox|r. Loot it for the |cRXP_LOOT_Token of Thievery|r"] = "Öffnet die |cRXP_PICK_Lucius's Schließkassette|r. Sammelt die Beute für die |cRXP_LOOT_Marke der Diebeskunst|r",
        ["Open |cRXP_PICK_MacGrann's Meat Locker|r. Loot it for |cRXP_LOOT_MacGrann's Dried Meats|r"] = "Öffnet |cRXP_PICK_MacGranns Fleisch-Spind|r. Plündert sie für |cRXP_LOOT_MacGranns Trockenfleisch|r",
        ["Open |cRXP_PICK_Tallonkai's Dresser|r. Loot it for the |cRXP_LOOT_Emerald Dreamcatcher|r"] = "Öffnet |cRXP_PICK_Tallonkais Kommode|r. Plündert sie für |cRXP_LOOT_Smaragdgrüner Traumfänger|r",
        ["Open |T136241:0|t[Blacksmithing] and craft a |T135248:0|t[Rough Sharpening Stone] for your sharp weapon and apply it."] = "Öffnet |T136241:0|t[Schmiedekunst] und fertigt einen |T135248:0|t[Rauer Wetzstein] an und wendet ihn an.",
        ["Open |T136241:0|t[Blacksmithing] and craft a |T135255:0|t[Rough Weightstone] for your blunt weapon apply it."] = "Öffnet |T136241:0|t[Schmiedekunst] und fertigt einen |T135255:0|t[Rauer Gewichtsstein] an und wendet ihn an.",
        ["Open a |cRXP_PICK_Bauble Container|r. Loot it for a |T134125:0|t[Shrine Bauble]"] = "Öffnet einen |cRXP_PICK_Schmuckstückbehälter|r. Plündert sie für ein |T134125:0|t[Schrein-Schmuckstück]",
        ["Open the |cRXP_PICK_Ammo Crate|r. Loot it for |cRXP_LOOT_Rumbleshot's Ammo|r"] = "Öffnet die |cRXP_PICK_Munitionskiste|r. Plündert sie für |cRXP_LOOT_Munition für Rumbleshot|r",
        ["Open the |cRXP_PICK_Beached Sea Creature|r. Loot it for the |cRXP_LOOT_Sea Creature Bones|r"] = "Öffnet die |cRXP_PICK_Gestrandete Meereskreatur|r. Plündert sie für die |cRXP_LOOT_Meereskreaturknochen|r",
        ["Open the |cRXP_PICK_Blackwood Fruit Stores|r. Loot it for the |T134013:0|t|cRXP_LOOT_[Blackwood Fruit Sample]|r"] = "Öffnet die |cRXP_PICK_Obstlager der Schwarzfelle|r. Plündert sie für die |T134013:0|t|cRXP_LOOT_[Obstprobe der Schwarzfelle]|r",
        ["Open the |cRXP_PICK_Blackwood Grain Stores|r. Loot it for the |T134059:0|t|cRXP_LOOT_[Blackwood Grain Sample]|r"] = "Öffnet die |cRXP_PICK_Getreidelager der Schwarzfelle|r. Plündert sie für die |T134059:0|t|cRXP_LOOT_[Getreideprobe der Schwarzfelle]|r",
        ["Open the |cRXP_PICK_Blackwood Nut Stores|r. Loot it for the |T133944:0|t|cRXP_LOOT_[Blackwood Nut Sample]|r"] = "Öffnet die |cRXP_PICK_Blackwood Nut Stores|r. Plündert sie für die |T133944:0|t|cRXP_LOOT_[Nussprobe der Schwarzfelle]|r",
        ["Open the |cRXP_PICK_Blasting Supplies|r inside the mine and outside on the other side. Loot them for the |cRXP_LOOT_Seaforium Mining Charges|r"] = "Öffnet die |cRXP_PICK_Sprengvorräte|r im Bergwerk und draußen auf der anderen Seite. Sammelt sie für die |cRXP_LOOT_Zephyriumbergbauladung|r",
        ["Open the |cRXP_PICK_Equipment Boxes|r on the ground. Loot them for the |cRXP_LOOT_Scavenged Goods|r"] = "Öffnet die |cRXP_PICK_Ausrüstungskästen|r auf dem Boden. Sammelt sie für die |cRXP_LOOT_Aufgestöberte Waren|r",
        ["Open the |cRXP_PICK_Glinting Mud|r. Loot it for |cRXP_LOOT_Hilary's Necklace|r"] = "Öffnet |cRXP_PICK_Glitzernder Matsch|r. Plündert es für |cRXP_LOOT_Hilarys Halskette|r",
        ["Open the |cRXP_PICK_Miners' League Crates|r inside the mine. Loot them for the |cRXP_LOOT_Miners' Gear|r"] = "Öffnet die |cRXP_PICK_Kisten der Minenarbeiterliga|r in der Mine. Sammelt sie ein für die |cRXP_LOOT_Minenarbeiterausstattung|r",
        ["Open the |cRXP_PICK_Miners' League Crates|r. Loot them for the |cRXP_LOOT_Miners' Gear|r"] = "Öffnet |cRXP_PICK_Kisten der Minenarbeiterliga|r. Plündert sie für die |cRXP_LOOT_Minenarbeiterausstattung|r",
        ["Open the |cRXP_PICK_Plant Bundles|r in the ground. Loot them for |cRXP_LOOT_Bathran's Hairs|r"] = "Öffnet |cRXP_PICK_Pflanzenbündel|r auf dem Boden. Plündert sie für |cRXP_LOOT_Bathranshaar|r",
        ["Open the |cRXP_PICK_Plant Bundles|r on the ground. Loot them for |cRXP_LOOT_Bathran's Hairs|r"] = "Öffnet |cRXP_PICK_Pflanzenbündel|r auf dem Boden. Plündert sie für |cRXP_LOOT_Bathranshaar|r",
        ["Open the |cRXP_PICK_Sacks of Oats|r on the ground. Loot them for the |cRXP_LOOT_Handful of Oats|r"] = "Öffnet die |cRXP_PICK_Sack Hafer|r auf dem Boden. Plündert es für eine |cRXP_LOOT_Handvoll Hafer|r",
        ["Open the |cRXP_PICK_Shimmerweed Baskets|r on the ground. Loot them for their |cRXP_LOOT_Shimmerweed|r"] = "Öffnet die |cRXP_PICK_Schimmerkrautkorb|r auf dem Boden. Plündert sie für ihr |cRXP_LOOT_Schimmerkraut|r",
        ["Open the |cRXP_PICK_Skeletal Sea Turtle|r. Loot it for the |cRXP_LOOT_Sea Turtle Remains|r"] = "Öffnet die |cRXP_PICK_Skelettartige Meeresschildkröte|r. Plündert sie für die |cRXP_LOOT_Meeresschildkrötenüberreste|r",
        ["Open the |cRXP_PICK_Stolen Books|r. Loot it for the |cRXP_LOOT_Powers of the Void|r"] = "Öffnet |cRXP_PICK_Gestohlene Bücher|r. Sammelt die |cRXP_LOOT_Macht der Leere|r",
        ["Open the |cRXP_PICK_Strange Lockbox|r. Loot it for the |cRXP_LOOT_Half Pendant of Aquatic Agility|r"] = "Öffnet die |cRXP_PICK_Merkwürdige Schließkassette|r. Plündert sie für den |cRXP_LOOT_Halber Anhänger der Wasser-Beweglichkeit|r",
        ["Open the |cRXP_PICK_Sunken Chest|r. Loot it for |cRXP_LOOT_Oslow's Toolbox|r"] = "Öffnet die |cRXP_PICK_Versunkene Truhe|r. Plündert sie für |cRXP_LOOT_Oslows Werkzeugkasten|r",
        ["Possible Tornado Spawn Location"] = "Possible Tornado Erschaffen Ort",
        ["Press the Macro in the \"Active Items Frame\" to craft |T133685:0|t[Linen Bandages]."] = "Drückt das Makro im \"Aktiv Gegenstände Frame\", um |T133685:0|t[Leinenbandagen] zu craften.",
        ["Reach the end of the beach"] = "Erreicht das Ende des Strandes",
        ["Repair your gear"] = "Repariert euer Equip",
        ["Repair your weapon"] = "Repariert eure Waffe",
        ["Repeatedly use the |T537768:0|t[Flutterfly Swatter] on the |cRXP_ENEMY_Flutterflies::251622|r"] = "Benutzt wiederholt |T537768:0|t[Flatterfliegenklatsche] auf |cRXP_ENEMY_Flutterflies::251622|r",
        ["Respawn at the Spirit Healer"] = "Respawnt beim Geistheiler",
        ["Restock/Resupply"] = "Restock/Nachschub",
        ["Return to |cRXP_FRIENDLY_Aamelia Windfield's::252800|r main location and talk to her."] = "Kehrt zum Ort der |cRXP_FRIENDLY_Aamelia Windfield::252800|r zurück und sprecht mit ihr.",
        ["Return to |cRXP_FRIENDLY_Cerellean Whiteclaw|r on the dock"] = "Kehrt zu |cRXP_FRIENDLY_Cerellean Whiteclaw|r auf dem Dock zurück",
