        ["Return to Kharanos"] = "Kehrt nach Kharanos zurück",
        ["Return to the city and wait for the roleplay."] = "Kehrt zur Stadt zurück und wartet auf das Rollenspiel.",
        ["Return to Thelsamar"] = "Kehrt nach Thelsamar zurück",
        ["Right click the |cRXP_PICK_Altar|r"] = "Rechts-klickt den |cRXP_PICK_Altar|r",
        ["Run down the beach. Kill |cRXP_ENEMY_Crawlers|r and |cRXP_ENEMY_Makruras|r. Loot them for their |cRXP_LOOT_Mucus|r and |cRXP_LOOT_Eyes|r. You do not have to finish this step here."] = "Rennt den Strand hinunter. Tötet |cRXP_ENEMY_Kriecher|r und |cRXP_ENEMY_Makruras|r. Sammelt Beute von ihnen für |cRXP_LOOT_Kriechersekret|r und |cRXP_LOOT_Augen|r. Ihr müsst diesen Schritt hier nicht beenden",
        ["Run straight north while climbing the mountain"] = "Lauft geradeaus nach Norden, während ihr den Berg erklimmt",
        ["Run toward the edge of the Furbolg Camp"] = "Lauft zum Rand des Furbolg-Lagers",
        ["Run up out of the crypt toward |cRXP_FRIENDLY_Mordo|r"] = "Lauft aus der Gruft hinauf zu |cRXP_FRIENDLY_Mordo|r",
        ["Run up the dirt path then drop down into the bunker"] = "Lauft den Schmutzpfad hinauf und springt dann in den Bunker hinunter",
        ["Run up the ramp to |cRXP_ENEMY_Vagash|r"] = "Lauft die Rampe hinauf zu |cRXP_ENEMY_Vagash|r",
        ["Run up the side of the cave entrance. Jump down into Frostmane Hold"] = "Lauft die Seite des Höhleneingangs hinauf. Springt in die Höhle der Frostmähnen",
        ["Save up to 6 |cRXP_LOOT_Gooey Spider Legs|r looted from the |cRXP_ENEMY_Spiders|r in the zone for later"] = "Sammelt bis zu 6 |cRXP_LOOT_Klebriges Spinnenbein|r von den |cRXP_ENEMY_Spinnen|r in der Zone auf für später",
        ["Save up to 6 |cRXP_LOOT_Gooey Spider Legs|r looted from the |cRXP_ENEMY_Spiders|r in the zone. You will need them for a quest later"] = "Behalte bis zu 6 |cRXP_LOOT_Klebriges Spinnenbein|r was du von den |cRXP_ENEMY_Spinnen|r in der Zone gelootet hast. Du brauchst sie später für eine Quest",
        ["Set your Hearthstone to Astranaar"] = "Setzt von Euch Ruhestein auf Astranaar",
