        ["Skip this step if the area is too crowded"] = "Überspringt diesen Schritt, wenn das Gebiet zu voll ist",
        ["Skip training |T136006:0|t[|cRXP_LOOT_Wrath|r] if you can't afford it. Prioritize |T136104:0|t[|cRXP_LOOT_Thorns|r]"] = "Überspringt das Training von |T136006:0|t[|cRXP_LOOT_Zorn|r], wenn ihr es euch nicht leisten könnt. Priorisiert |T136104:0|t[|cRXP_LOOT_Dornen|r]",
        ["Stock up on |T132382:0|t[Sharp Arrows]"] = "Deckt euch mit |T132382:0|t[Scharfe Pfeile] ein",
        ["Stock up on food"] = "Füllt essen auf",
