        ["Take the Zeppelin to Durotar"] = "Nehmt den Zeppelin nach Durotar",
        ["Take the Zeppelin to Tirisfal Glades"] = "Nehmt den Zeppelin nach Tirisfal",
        ["Talk to |cRXP_FRIENDLY_Earthseer Farsen|r to view his farsight"] = "Sprecht mit |cRXP_FRIENDLY_Erdseher Farsen|r, um seine Fernsicht anzusehen",
        ["Talk to |cRXP_FRIENDLY_Talaanis Shadowsong::252476|r."] = "Sprecht mit |cRXP_FRIENDLY_Talaanis Shadowsong::252476|r.",
        ["Talk to |cRXP_FRIENDLY_The Threshwackonator 4100|r to start the escort"] = "Sprecht mit |cRXP_FRIENDLY_Der Dreschonator 4100|r um die Eskorte zu beginnen",
        ["Talk to a |cRXP_FRIENDLY_Novice Warrior|r, then defeat it in combat"] = "Sprecht mit einem |cRXP_FRIENDLY_Kriegernovize|r, dann besiegt ihn im Kampf",
        ["Talk to the |cRXP_FRIENDLY_Frightened Paladin|r, kill her as she becomes hostile"] = "Sprecht mit den |cRXP_FRIENDLY_Verängstigter Paladin|r, tötet sie, wenn sie feindselig wird",
        ["Tame a |cRXP_ENEMY_Prairie Wolf Alpha|r"] = "Zähmt einen |cRXP_ENEMY_Präriewolfalpha|r",
        ["Tame a |cRXP_ENEMY_Venomtail Scorpid|r"] = "Zähmt einen |cRXP_ENEMY_Siechstachelskorpid|r",
        ["Target |cRXP_FRIENDLY_Sentinel Shaya|r"] = "Ziel |cRXP_FRIENDLY_Schildwache Shaya|r",
        ["The process was cancelled. Please use the SIT macro again to restart it."] = "Der Vorgang wurde abgebrochen. Bitte benutzt das SIT-Makro nochmal, um ihn neu zu starten.",
        ["This will save you time as you won't need to run around looking for mobs to kill. Skip this step if you wish to not buy any"] = "Das spart dir Zeit, weil du dann später nicht rumläufst und die Mobs dafür töten musst. Überspring diesen Schritt, wenn du nichts kaufen willst",
        ["This will start an escort"] = "Das wird eine Eskorte starten",
        ["TIP: |cRXP_WARN_Take the leggings as the reward and keep them. You will use them to engrave a rune on later on|r"] = "TIPP: |cRXP_WARN_Nehmt die Hosen als Belohnung und behaltet sie. Ihr werdet sie später verwenden, um eine Rune darauf einzugravieren|r",
        ["TIP: |cRXP_WARN_Take the pants as reward from him. You will use them to engrave a rune on later|r"] = "TIPP: |cRXP_WARN_Nehmt die Hosen als Belohnung von ihm auf. Ihr werdet sie später verwenden, um eine Rune darauf einzugravieren|r",
        ["Train |T132309:0|t[|cRXP_LOOT_Wing Clip|r]"] = "Erlernt |T132309:0|t[|cRXP_LOOT_Zurechtstutzen|r]",
        ["Train |T133644:0|t[Pick Pocket] as well which is needed for your level 10 Rogue quest"] = "Lernt |T133644:0|t[Taschendiebstahl] ebenfalls, was für eure Stufe-10-Schurken-Quest benötigt wird",
        ["Train |T135139:0|t[|cRXP_FRIENDLY_Lesser Magic Wand|r] from her"] = "Erlernt |T135139:0|t[|cRXP_FRIENDLY_Geringer Magiezauberstab|r] von ihr",
        ["Train |T136244:0|t[|cRXP_LOOT_Enchanting|r]. You will need it to craft a |T135139:0|t[|cRXP_LOOT_Wand|r]"] = "Erlernt |T136244:0|t[|cRXP_LOOT_Verzauberkunst|r]. Ihr werdet sie benötigen, um einen |T135139:0|t[|cRXP_LOOT_Zauberstab|r] herzustellen",
        ["Train |T136249:0|t[Tailoring]. Save up your |T132889:0|t[Linen Cloth]. This will allow you to create a wand later"] = "Erlernt |T136249:0|t[Schneiderei].Behaltet euren |T132889:0|t[Leinenstoff].Dies wird es euch ermöglichen, später einen Zauberstab Herzustellen",
        ["Train 1h Axes"] = "Erlernt 1h Äxte",
