        ["Travel upstairs in the Inn"] = "Geht im Gasthaus nach oben",
        ["Try to only Moonfire right after Meleeing |cRXP_WARN_to not reset your swing timer!|r"] = "Versucht, Mondfeuer nur direkt nach Nahkampfangriffen zu nutzen, |cRXP_WARN_um euren Schwung-Timer nicht zurückzusetzen!|r",
        ["Use |T1029587:0|t[Skysight] for the 10% movement speed buff."] = "Benutzt |T1029587:0|t[Himmelssicht] für den 10%-Bewegungsgeschwindigkeitsbuff.",
        ["Use |T1029587:0|t[Skysight] near the |cRXP_PICK_Elemental Convergence|r."] = "Benutzt |T1029587:0|t[Skysight] neben dem |cRXP_PICK_Elementar Konvergenz|r.",
        ["Use |T136244:0|t[|cRXP_LOOT_Enchanting|r] in your |cRXP_WARN_profession tab|r to craft |T135645:0|t[|cRXP_LOOT_Novice's Practice Wands|r] |cRXP_WARN_until you reach 10 enchanting|r"] = "Benutzt |T136244:0|t[|cRXP_LOOT_Verzauberkunst|r] in eurem |cRXP_WARN_Berufsfähigkeiten-Tab|r, um |T135645:0|t[|cRXP_LOOT_Übungszauberstab des Novizen|r] |cRXP_WARN_herzustellen, bis ihr 10 Verzauberkunst erreicht|r",
        ["Use |T136244:0|t[|cRXP_LOOT_Enchanting|r] in your |cRXP_WARN_profession tab|r to craft a |T135139:0|t[|cRXP_FRIENDLY_Lesser Magic Wand|r]"] = "Benutzt |T136244:0|t[|cRXP_LOOT_Verzauberkunst|r] in eurem |cRXP_WARN_Berufsfähigkeiten-Tab|r, um einen |T135139:0|t[|cRXP_FRIENDLY_Geringer Magiezauberstab|r] herzustellen",
        ["Use |T136244:0|t[|cRXP_LOOT_Enchanting|r] in your |cRXP_WARN_profession tab|r to create a |T135225:0|t[|cRXP_LOOT_Runed Copper Rod|r]"] = "Benutzt |T136244:0|t[|cRXP_LOOT_Verzauberkunst|r] in eurem |cRXP_WARN_Berufsfähigkeiten-Tab|r, um einen |T135225:0|t[|cRXP_LOOT_Runenverzierte Kupferrute|r] herzustellen",
        ["Use |T236219:0|t[Read Ley Line] for 100% increased passive Mana and Health regeneration."] = "Benutzt |T236219:0|t[Leylinie erschließen] für 100% erhöhte passive Mana- und Gesundheitsregeneration.",
        ["Use |T236219:0|t[Read Ley Line] near the |cRXP_WARN_Blue Rift|r on the ground"] = "Benutzt |T236219:0|t[Lesen Leylinie] neben dem |cRXP_WARN_Blue Rift|r am Boden",
        ["Use |T4624731:0|t[Pelt Collecting for Beginners] |cRXP_WARN_while walking towards the questgiver|r."] = "Benutzt |T4624731:0|t[Pelt Einsammeln for Beginners] |cRXP_WARN_während ihr zum Questgeber geht|r.",
        ["Use |T4624731:0|t[Wild Harvest] |cRXP_WARN_while walking towards the questgiver|r."] = "Benutzt |T4624731:0|t[Wild Ernten] |cRXP_WARN_während ihr zum Questgeber geht|r.",
        ["Use |T4625105:0|t[Mining for Dummies] |cRXP_WARN_while walking towards the questgiver|r."] = "Benutzt |T4625105:0|t[Bergbau for Dummies] |cRXP_WARN_während ihr zum Questgeber geht|r.",
        ["Use the |cRXP_WARN_/sit|r emote next to the campfire and |cRXP_WARN_sit still for 1 minute|r to complete the objective"] = "Benutzt das |cRXP_WARN_/sitzen|r Emote neben dem Lagerfeuer und |cRXP_WARN_bleibt 1 Minute lang sitzen|r um das Ziel zu abzuschließen",
        ["Use the |T132834:0|t[Herb Baked Egg] macro below to craft 1 for the experience buff."] = "Benutzt das Makro unten mit |T132834:0|t[Kräutergebackenes Ei], um 1 für den Erfahrungs-Buff herzustellen.",
        ["Use the |T132834:0|t[Herb Baked Egg] macro below to craft every Small Egg beyond the 3 reserved for Restocking the Larders."] = "Benutzt das Makro unten mit |T132834:0|t[Kräutergebackenes Ei], um jedes Kleine Ei außer den 3 für 'Vorräte auffüllen' reservierten herzustellen.",
        ["Use the |T133471:0|t[|cRXP_LOOT_Aged Envelope|r] to start the quest"] = "Benutzt den |T133471:0|t[|cRXP_LOOT_Vergilbter Umschlag|r] um die Quest zu starten",
        ["Use the |T133942:0|t[Rat Catcher's Flute] on |cRXP_FRIENDLY_Deeprun Rats|r in the Deeprun Tram"] = "Benutzt |T133942:0|t[Rattenfänger-Flöte] auf |cRXP_FRIENDLY_Tiefenbahn-Ratten|r in der Tiefenbahn",
        ["Use the |T134227:0|t[Horn of Echeyakee] to summon |cRXP_ENEMY_Echeyakee|r"] = "Benutzt das |T134227:0|t[Horn von Echeyakee], um |cRXP_ENEMY_Echeyakee|r zu beschwören",
        ["Use the |T134298:0|t[|cRXP_LOOT_Fang of Githyiss|r] to accept the quest"] = "Benutzt den |T134298:0|t[|cRXP_LOOT_Fangzahn von Githyiss|r] um die Quest zu akzeptieren",
        ["Use the |T134332:0|t[Ripped Missive] in your bags to begin the quest."] = "Benutzt |T134332:0|t[Ripped Missive] aus euren Taschen, um die Quest zu beginnen.",
        ["Use the |T134743:0|t[Earth Sapta]."] = "Benutzt |T134743:0|t[Erdsapta].",
        ["Vendor and Repair"] = "Verkaufe und Repariere",
        ["Vendor trash"] = "Verkauft Müll",
        ["Vendor trash and repair"] = "Verkauft trash und repariert",
        ["Vendor trash and repair if needed"] = "Händler trash und repair if needed",
        ["Vendor trash and repair if needed."] = "Händler trash und repair if needed.",
        ["Vendor trash and repair your gear."] = "Händler trash und repair von Euch gear.",
        ["Vendor Trash. |cRXP_BUY_Buy up to three|r |T133634:0|t[Small Brown Pouches] |cRXP_BUY_as needed|r."] = "Verkauft Müll. |cRXP_BUY_Kauft bis zu drei|r |T133634:0|t[Kleiner brauner Beutel] |cRXP_BUY_nach Bedarf|r.",
        ["Vendor trash. Sell your weapon if it gives you enough money for a |T132401:0|t[Large Axe] (4s 60). You'll come back later if you don't have enough yet"] = "Verkauft Müll. Verkauft von Euch Waffe, falls es euch genug Geld für eine |T132401:0|t[Große Axt] (4s 60c) bringt. Ihr kommt später zurück, falls ihr noch nicht genug habt",
        ["Vendor trash. Sell your weapon if it gives you enough money for a |T135139:0|t[Short Staff] (97c)"] = "Verkauft trash. Verkaufe deine Waffe, wenn sie dir genug Geld für einen |T135139:0|t[Kurzstab] (97c) bringt",
        ["Vendor your trash"] = "Verkaufe deinen trash",
        ["Wait for |cRXP_FRIENDLY_Denalan|r to complete the roleplay. Kill the |cRXP_ENEMY_Boglings|r for |T134187:0|t[|cRXP_LOOT_Bogling Roots|r] and loot the |cRXP_PICK_Sprouted Frond|r"] = "Wartet auf |cRXP_FRIENDLY_Denalan|r, bis das Rollenspiel endet. Tötet die |cRXP_ENEMY_Boglinge|r für |T134187:0|t[|cRXP_LOOT_Boglingwurzel|r] und plündert die |cRXP_PICK_Sprießender Wedel|r",
        ["Wait for the roleplay. Use the |T135432:0|t[Torch of Eternal Flame] on the burning |cRXP_PICK_Brazier of Offering|r."] = "Wartet auf das Rollenspiel. Benutzt die |T135432:0|t[Fackel of Ewige Flamme] auf dem brennenden |cRXP_PICK_Brazier of Opfergabe|r.",
        ["Watch out for the |cRXP_ENEMY_Ornery Galestrider::251707|r."] = "Achtung vor |cRXP_ENEMY_Ornery Galestrider::251707|r.",
        ["When Aamelia stops, place a Campfire if you have one and none is nearby. Start cooking for skillups."] = "Wenn Aamelia stehen bleibt, platziert ein Lagerfeuer, wenn ihr eins habt und keines ist in der Nähe. Fangt an zu kochen, um Fertigkeitspunkte zu erhalten.",
        ["While falling from the tower, use |T132845:0|t[Walk on Air] and aim for the quest giver."] = "Während ihr vom Turm fallt, benutzt |T132845:0|t[Gehen on Luft] und zielt auf den Questgeber.",
        ["You can also just jump and spam the button on the ground."] = "Ihr könnt auch einfach springen und den Knopf auf dem Boden drücken.",
        ["You can jump off the mountain and use |T132845:0|t[Walk on Air] |cRXP_WARN_in midair|r to fly towards the waypoint location."] = "Ihr könnt vom Berg abspringen und |T132845:0|t[Luftwandeln] |cRXP_WARN_in der Luft|r benutzen, um zum Wegpunkt-Ort zu fliegen.",
        ["You can use the |T134296:0|t[|cRXP_FRIENDLY_Severed Voodoo Claws|r] on him to severely reduce his damage!"] = "Ihr könnt |T134296:0|t[|cRXP_FRIENDLY_Abgespaltene Voodooklaue|r] auf ihn verwenden, um seinen Schaden stark zu reduzieren!",
        ["You have roughly 5 minutes to run back."] = "Ihr habt etwa 5 Minuten Zeit, um zurückzulaufen.",
        ["You have selected a guide meant for Gnomes and Dwarves. You should choose the same starter zone that you start in"] = "Ihr habt einen Leitfaden für Gnome und Zwerge ausgewählt. Ihr solltet die gleiche Startzone wählen, in der ihr startet",
        ["You have selected a guide meant for Humans. You should choose the same starter zone that you start in"] = "Ihr habt einen Leitfaden für Menschen ausgewählt. Ihr solltet die gleiche Startzone wählen, in der ihr startet",
        ["You have selected a guide meant for Night Elves. You should choose the same starter zone that you start in"] = "Ihr habt einen Leitfaden für Nachtelfen ausgewählt. Ihr solltet die selbe Anfangszone wählen, in der ihr startet",
    },
