        ["|cRXP_BUY_Buy an|r {A}{B} |cRXP_BUY_from him|r"] = "|cRXP_BUY_Kaufe|r {A}{B} |cRXP_BUY_bei ihm|r",
        ["|cRXP_BUY_Buy|r {A}{B} |cRXP_BUY_from her if they're up|r"] = "|cRXP_BUY_Kaufe|r {A}{B} |cRXP_BUY_bei ihr, wenn sie es vorrätig hat|r",
        ["|cRXP_BUY_Buy|r {A}{B} |cRXP_BUY_from her|r"] = "|cRXP_BUY_Kaufe|r {A}{B} |cRXP_BUY_bei ihr|r",
        ["|cRXP_BUY_Buy|r {A}{C} |cRXP_BUY_and|r {B}{D} |cRXP_BUY_from her if they're up|r"] = "|cRXP_BUY_Kaufe|r {A}{C} |cRXP_BUY_und|r {B}{D} |cRXP_BUY_bei ihr, wenn sie beides vorrätig hat|r",
        ["|cRXP_BUY_Sell your junk, then restock on food and water if necessary|r"] = "|cRXP_BUY_Verkaufe deinen Plunder und fülle bei Bedarf deine Vorräte an Essen und Wasser auf|r",
        ["|cRXP_BUY_Sell your junk, then restock on food if necessary|r"] = "|cRXP_BUY_Verkaufe deinen Plunder und fülle bei Bedarf deine Essensvorräte auf|r",
        ["|cRXP_WARN_After {A} PM game time only.|r"] = "|cRXP_WARN_Erst nach {A} Uhr abends (Serverzeit).|r",
        ["|cRXP_WARN_Avoid the birds and click Fillion out of combat, or you'll be teleported outside|r."] = "|cRXP_WARN_Weiche den Vögeln aus und klicke Fillion außerhalb des Kampfes an. Sonst wirst du nach draußen teleportiert|r.",
        ["|cRXP_WARN_Be careful as they cast|r {A}{B} |cRXP_WARN_(Charges {C} extra attacks every {D} seconds)|r"] = "|cRXP_WARN_Achtung, sie wirken|r {A}{B} |cRXP_WARN_({C} zusätzliche Angriffe alle {D} Sekunden)|r",
        ["|cRXP_WARN_Be careful of |cRXP_ENEMY_Ursangous|r (strong lvl {A}) that patrols in the area|r"] = "|cRXP_WARN_Achte auf |cRXP_ENEMY_Ursangous|r |cRXP_WARN_(starker Gegner, Stufe {A}), der in der Gegend patrouilliert|r",
        ["|cRXP_WARN_Be careful of the {B} groups of {C} |cRXP_ENEMY_Raging Moonkins|r west of the {A} as the duos closest to each other are leashed together|r"] = "|cRXP_WARN_Pass westlich von|r {A} |cRXP_WARN_bei den|r {B} |cRXP_WARN_Gruppen mit je|r {C} |cRXP_ENEMY_Tobenden Mondkins|r |cRXP_WARN_auf. Die beiden engsten Paare greifen gemeinsam an|r",
        ["|cRXP_WARN_Be careful! Do NOT approach him until he becomes friendly or he will attack you!|r"] = "|cRXP_WARN_Achtung! Nähere dich ihm erst, wenn er freundlich wird. Sonst greift er dich an!|r",
        ["|cRXP_WARN_Be careful! He is a strong elite and is guarded by at least two|r {A} |cRXP_WARN_mobs|r"] = "|cRXP_WARN_Achtung! Er ist ein starker Elitegegner und wird von mindestens zwei|r {A} |cRXP_WARN_bewacht|r",
        ["|cRXP_WARN_Be careful! The|r {A} |cRXP_WARN_have a chance of summoning a level {C}|r {B}"] = "|cRXP_WARN_Achtung!|r {A} |cRXP_WARN_können Folgendes auf Stufe {C} beschwören:|r {B}",
        ["|cRXP_WARN_Be careful! Three|r {A} |cRXP_WARN_will spawn when you reach the bonfire in Camp Aparaje|r"] = "|cRXP_WARN_Achtung! Drei|r {A} |cRXP_WARN_erscheinen, sobald du das Lagerfeuer im Lager Aparaje erreichst|r",
        ["|cRXP_WARN_Be careful! You may aggro {A}-{B} mobs at the same time|r"] = "|cRXP_WARN_Achtung! Du könntest {A}–{B} Gegner gleichzeitig anlocken|r",
        ["|cRXP_WARN_Cast|r {A}{B}"] = "|cRXP_WARN_Wirke|r {A}{B}",
        ["|cRXP_WARN_Clear the area around|r {A}|cRXP_WARN_. Be careful as she webs you. Keep her permanently feared with dots|r"] = "|cRXP_WARN_Räume die Gegner in der Nähe von|r {A} |cRXP_WARN_aus dem Weg. Achtung, sie spinnt dich ein. Halte sie mit „Furcht“ auf Abstand und belege sie mit Schaden-über-Zeit-Zaubern|r",
        ["|cRXP_WARN_Clear the area around|r {A}|cRXP_WARN_. Be careful as she webs you|r"] = "|cRXP_WARN_Räume die Gegner in der Nähe von|r {A} |cRXP_WARN_aus dem Weg. Achtung, sie spinnt dich ein|r",
        ["|cRXP_WARN_Click here for a guide video on how you can kite|r {A}"] = "|cRXP_WARN_Klick hier für ein Video, das zeigt, wie du im Kampf Abstand hältst zu|r {A}",
        ["|cRXP_WARN_Click here for a video guide|r"] = "|cRXP_WARN_Hier klicken für eine Videoanleitung|r",
        ["|cRXP_WARN_CLICK HERE for an example|r"] = "|cRXP_WARN_Klick hier für ein Beispiel|r",
        ["|cRXP_WARN_Click here for video reference|r"] = "|cRXP_WARN_Hier klicken für ein Beispielvideo|r",
        ["|cRXP_WARN_Create|r {A}{B} |cRXP_WARN_until your skill is {C} or higher|r"] = "|cRXP_WARN_Stelle|r {A}{B} |cRXP_WARN_her, bis du Fertigkeitsstufe {C} erreichst|r",
        ["|cRXP_WARN_Create|r {A}{C} |cRXP_WARN_if you found any|r {B}{D}"] = "|cRXP_WARN_Stelle|r {A}{C} |cRXP_WARN_her, falls du|r {B}{D} |cRXP_WARN_gefunden hast|r",
        ["|cRXP_WARN_Delete any leftover|r {A}{B} |cRXP_WARN_you may still have|r"] = "|cRXP_WARN_Entferne alle übrigen|r {A}{B} |cRXP_WARN_aus deinen Taschen|r",
        ["|cRXP_WARN_Delete any|r {A}{B} |cRXP_WARN_you have left|r"] = "|cRXP_WARN_Entferne alle übrigen|r {A}{B} |cRXP_WARN_aus deinen Taschen|r",
        ["|cRXP_WARN_Delete the|r {A}{B} |cRXP_WARN_from your bags, as it's no longer needed|r"] = "|cRXP_WARN_Entferne|r {A}{B} |cRXP_WARN_aus deinen Taschen. Du brauchst es nicht mehr|r",
        ["|cRXP_WARN_Delete|r {A}{B} |cRXP_WARN_from your bags, as it's no longer needed|r"] = "|cRXP_WARN_Entferne|r {A}{B} |cRXP_WARN_aus deinen Taschen. Du brauchst es nicht mehr|r",
        ["|cRXP_WARN_Do not go underwater until you arive right above the Bauble|r"] = "|cRXP_WARN_Tauche erst ab, wenn du genau über dem Questgegenstand bist|r",
        ["|cRXP_WARN_Do NOT set your|r {A}{B}"] = "|cRXP_WARN_Binde hier auf keinen Fall deinen|r {A}{B}",
        ["|cRXP_WARN_Don't go out of your way to complete this yet|r"] = "|cRXP_WARN_Mach dafür jetzt noch keinen Umweg|r",
        ["|cRXP_WARN_Dual-wield the|r {C}{F} |cRXP_WARN_and|r {D}{G} |cRXP_WARN_if you don't have the|r {E}{H}."] = "|cRXP_WARN_Führe|r {C}{F} |cRXP_WARN_und|r {D}{G} |cRXP_WARN_gleichzeitig, falls du Folgendes nicht hast:|r {E}{H}.",
        ["|cRXP_WARN_Each mob here will take increased damage to certain abilities|r"] = "|cRXP_WARN_Jeder Gegner hier erleidet durch bestimmte Fähigkeiten erhöhten Schaden|r",
        ["|cRXP_WARN_Equip the|r {A}{B}"] = "|cRXP_WARN_Lege Folgendes an:|r {A}{B}",
        ["|cRXP_WARN_Equip the|r {A}{B}."] = "|cRXP_WARN_Lege Folgendes an:|r {A}{B}.",
        ["|cRXP_WARN_Equip the|r {B}{C}"] = "|cRXP_WARN_Lege Folgendes an:|r {B}{C}",
        ["|cRXP_WARN_Fill your|r {A}{B} |cRXP_WARN_in the watering hole below Brine's hut|r"] = "|cRXP_WARN_Fülle|r {A}{B} |cRXP_WARN_am Wasserloch unterhalb von Brines Hütte|r",
        ["|cRXP_WARN_First wave at {A} seconds ({B} Kobolds), Second wave at {C} minutes {D} seconds ({E} Kobolds, {F} casters {G} melee), and the Third wave at {H} minutes {I} seconds ({J} Kobolds). The objective completes at {K} minutes|r"] = "|cRXP_WARN_Erste Welle nach {A} Sekunden ({B} Kobolde). Zweite Welle nach {C} Minuten und {D} Sekunden ({E} Kobolde, davon {F} Zauberwirker und {G} Nahkämpfer). Dritte Welle nach {H} Minuten und {I} Sekunden ({J} Kobolde). Das Ziel ist nach {K} Minuten erfüllt|r",
        ["|cRXP_WARN_He has {A} spawnpoints (marked on the map)|r"] = "|cRXP_WARN_Er kann an {A} Stellen auftauchen (auf deiner Karte markiert)|r",
        ["|cRXP_WARN_He is at the top of the tower|r"] = "|cRXP_WARN_Er steht oben auf dem Turm|r",
        ["|cRXP_WARN_He is|r {A}{B}"] = "|cRXP_WARN_Er ist|r {A}{B}",
        ["|cRXP_WARN_His spawn point is marked on your map|r"] = "|cRXP_WARN_Sein Spawnpunkt ist auf deiner Karte markiert|r",
        ["|cRXP_WARN_If a Tornado is nearby, use it for faster travel|r."] = "|cRXP_WARN_Wenn ein Tornado in der Nähe ist, nutze ihn zur schnelleren Fortbewegung|r.",
        ["|cRXP_WARN_If it's not up, buy a|r {A}{B} |cRXP_WARN_instead|r"] = "|cRXP_WARN_Wenn es nicht vorrätig ist, kaufe stattdessen|r {A}{B}",
        ["|cRXP_WARN_If you have {G}|r {C}{E} |cRXP_WARN_left, use them to obtain|r {D}{F} |cRXP_WARN_from|r {B}"] = "|cRXP_WARN_Wenn du noch {G}|r {C}{E} |cRXP_WARN_hast, hol dir damit|r {D}{F} |cRXP_WARN_bei|r {B}",
        ["|cRXP_WARN_If you have any|r {A}{C}|cRXP_WARN_, use one to cure yourself of|r {B}{D}"] = "|cRXP_WARN_Wenn du|r {A}{C} |cRXP_WARN_hast, benutze eines davon gegen|r {B}{D}",
        ["|cRXP_WARN_If you have the Thunder Bluff flight path, fly there instead|r"] = "|cRXP_WARN_Wenn du den Flugpunkt in Donnerfels schon hast, flieg dorthin|r",
        ["|cRXP_WARN_If you see a Tornado, use it for faster travel|r."] = "|cRXP_WARN_Wenn du einen Tornado siehst, nutze ihn zur schnelleren Fortbewegung|r.",
        ["|cRXP_WARN_It can take up to {A} minutes until he spawns|r"] = "|cRXP_WARN_Es kann bis zu {A} Minuten dauern, bis er auftaucht|r",
        ["|cRXP_WARN_It patrols the northern side of the river|r"] = "|cRXP_WARN_Der Gegner patrouilliert am Nordufer des Flusses|r",
        ["|cRXP_WARN_It patrols the southern side of the river|r"] = "|cRXP_WARN_Der Gegner patrouilliert am Südufer des Flusses|r",
        ["|cRXP_WARN_Jump onto one of the cages. Perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Spring auf einen der Käfige. Logg dich aus und wieder ein, um den Weg abzukürzen|r",
        ["|cRXP_WARN_Jump onto the white stone on your right. Perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Spring auf den weißen Stein rechts von dir. Logg dich aus und wieder ein, um den Weg abzukürzen|r",
        ["|cRXP_WARN_Jump onto the wooden beam. Perform a Logout Skip by logging out and back in. Run back to Orgrimmar if you don't succeed|r"] = "|cRXP_WARN_Spring auf den Holzbalken. Logg dich aus und wieder ein, um den Weg abzukürzen. Wenn es nicht klappt, lauf nach Orgrimmar zurück|r",
        ["|cRXP_WARN_Jump onto the wooden wheel. Perform a Logout Skip by logging out and back in|r"] = "|cRXP_WARN_Spring auf das Holzrad. Logg dich aus und wieder ein, um den Weg abzukürzen|r",
        ["|cRXP_WARN_Keep one bag slot free|r."] = "|cRXP_WARN_Halte einen Taschenplatz frei|r.",
        ["|cRXP_WARN_Make sure to avoid Astranaar guards en route. Follow the waypoint for safety|r"] = "|cRXP_WARN_Weiche unterwegs den Wachen von Astranaar aus. Halte dich an den Wegpunkt|r",
        ["|cRXP_WARN_Make sure to turn off any autocomplete functions from addons such as Questie or Leatrix Plus for this!|r"] = "|cRXP_WARN_Deaktiviere dafür die automatische Questabgabe in Addons wie Questie oder Leatrix Plus!|r",
        ["|cRXP_WARN_Make sure you kill all six|r {A} |cRXP_WARN_before starting the quest inside|r"] = "|cRXP_WARN_Töte alle sechs|r {A}|cRXP_WARN_, bevor du drinnen die Quest startest|r",
        ["|cRXP_WARN_Most buff food grants {A}% increased experience from kills for {B} minutes. Try to maintain a high uptime on this buff while leveling|r."] = "|cRXP_WARN_Die meisten Speisen mit Stärkungseffekt geben dir {B} Minuten lang {A} % mehr Erfahrung für getötete Gegner. Versuche, den Effekt beim Leveln möglichst durchgehend aktiv zu halten|r.",
        ["|cRXP_WARN_Night only:|r this quest can only be done after {B} PM game time. Before then the {A} isn't there, so don't worry if you can't find him. Hover the clock by your minimap to see the realm (game) time."] = "|cRXP_WARN_Nur nachts:|r Diese Quest kannst du erst nach {B} Uhr abends (Serverzeit) erledigen. Vorher ist {A} nicht da. Zeig mit der Maus auf die Uhr an der Minikarte, um die Serverzeit zu sehen.",
        ["|cRXP_WARN_Optional: the basilisks for this quest are level {A}-{B} and the Crystalhides stun. Skip this step if you're under {C} or it feels too hard; the guide goes on without it|r"] = "|cRXP_WARN_Optional: Die Basilisken für diese Quest sind Stufe {A}–{B}, und Kristallpanzerbasilisken können dich betäuben. Überspring den Schritt, wenn du unter Stufe {C} bist oder dir der Kampf zu schwer ist. Die Route geht weiter.|r",
        ["|cRXP_WARN_Press the Macro in the \"Active Items Frame\" to craft|r {A}{B} for a later quest|r"] = "|cRXP_WARN_Nutze das Makro im Fenster für aktive Gegenstände|r, um {A}{B} für eine spätere Quest herzustellen.",
        ["|cRXP_WARN_Remember to use a Potion and|r {A}{B} |cRXP_WARN_if needed|r"] = "|cRXP_WARN_Denk daran, bei Bedarf einen Trank und|r {A}{B} |cRXP_WARN_zu benutzen|r",
        ["|cRXP_WARN_Run to the main road as the |cRXP_FRIENDLY_Eye of Kilrogg|r follows you|r"] = "|cRXP_WARN_Lauf zur Hauptstraße, während dir |cRXP_FRIENDLY_Eye of Kilrogg|r |cRXP_WARN_folgt|r",
        ["|cRXP_WARN_Save all the|r {A}{B} |cRXP_WARN_you loot|r"] = "|cRXP_WARN_Heb alle erbeuteten|r {A}{B} |cRXP_WARN_auf|r",
        ["|cRXP_WARN_Save any|r {A}{B} |cRXP_WARN_you loot|r"] = "|cRXP_WARN_Behalte alle erbeuteten|r {A}{B}",
        ["|cRXP_WARN_Save them for later|r"] = "|cRXP_WARN_Heb sie für später auf|r",
        ["|cRXP_WARN_Skip this step if you can't find him|r"] = "|cRXP_WARN_Überspringe diesen Schritt, wenn du ihn nicht findest|r",
        ["|cRXP_WARN_Skip this step if you can't find it|r"] = "|cRXP_WARN_Überspringe diesen Schritt, wenn du den Gegner nicht findest|r",
        ["|cRXP_WARN_Skip this step if you did not have enough|r {A}{B} |cRXP_WARN_to reach {C} skill|r"] = "|cRXP_WARN_Überspringe diesen Schritt, wenn du mit den vorhandenen|r {A}{B} |cRXP_WARN_Fertigkeitsstufe {C} nicht erreichen konntest|r",
        ["|cRXP_WARN_Skip this step if you have the Thunder Bluff flight path|r"] = "|cRXP_WARN_Überspringe diesen Schritt, wenn du den Flugpunkt in Donnerfels schon hast|r",
        ["|cRXP_WARN_The Carcass only has a {A} minute duration!|r"] = "|cRXP_WARN_Der Kadaver bleibt nur {A} Minuten erhalten!|r",
        ["|cRXP_WARN_The|r {B}{C} |cRXP_WARN_is a very rare drop. Ignore this step if you don't get it|r"] = "|cRXP_WARN_Folgendes ist sehr selten:|r {B}{C}. |cRXP_WARN_Überspringe den Schritt, falls es nicht fällt|r",
        ["|cRXP_WARN_There will be waves of|r {A} |cRXP_WARN_that spawn. Be careful once|r {B} |cRXP_WARN_comes out, he hits very hard|r"] = "|cRXP_WARN_Es erscheinen mehrere Wellen von|r {A}|cRXP_WARN_. Pass auf, wenn|r {B} |cRXP_WARN_auftaucht. Er teilt kräftig aus|r",
        ["|cRXP_WARN_This is a pre-quest for \"The Wrath of Rath'mael\"|r"] = "|cRXP_WARN_Das ist die Vorquest für „Der Zorn von Rath'mael“|r",
        ["|cRXP_WARN_This is an elite or group part: bring help, or skip this step|r"] = "|cRXP_WARN_Hier warten Elitegegner, oder du brauchst eine Gruppe. Such dir Hilfe oder überspringe den Schritt.|r",
        ["|cRXP_WARN_This is hard! Group up if possible|r"] = "|cRXP_WARN_Das ist schwierig! Such dir nach Möglichkeit eine Gruppe|r",
        ["|cRXP_WARN_This next quest is very hard & grouping up is recommended. You can kite |cRXP_ENEMY_Warlord Krom'zar|r around using the building where the quest giver is located|r"] = "|cRXP_WARN_Die nächste Quest ist sehr schwer. Such dir am besten eine Gruppe. Du kannst |cRXP_ENEMY_Warlord Krom'zar|r |cRXP_WARN_um das Gebäude mit dem Questgeber herumlocken|r",
        ["|cRXP_WARN_This quest can be VERY difficult. Engage the |cRXP_ENEMY_Murlocs|r {A} by {B}, otherwise you may aggro multiple at the same time|r"] = "|cRXP_WARN_Diese Quest kann sehr schwierig sein. Lock die|r |cRXP_ENEMY_Murlocs|r |cRXP_WARN_einzeln an ({A} für {B}), damit dich nicht mehrere zugleich angreifen|r",
        ["|cRXP_WARN_This quest is optional. If you can't do it, skip this quest. You can try it again later|r"] = "|cRXP_WARN_Diese Quest ist optional. Wenn du sie gerade nicht schaffst, überspring sie und versuch es später erneut|r",
        ["|cRXP_WARN_This quest is optional. If you can't do it, skip this quest|r"] = "|cRXP_WARN_Diese Quest ist optional. Wenn du sie gerade nicht schaffst, überspring sie|r",
        ["|cRXP_WARN_This quest takes {A} minutes, and will spawn {B} waves of Kobolds at set times:|r"] = "|cRXP_WARN_Diese Quest dauert {A} Minuten. Zu festen Zeiten erscheinen {B} Wellen von Kobolden:|r",
        ["|cRXP_WARN_This will start an escort quest. Be careful as it's difficult|r"] = "|cRXP_WARN_Das startet eine schwierige Eskortquest|r",
        ["|cRXP_WARN_This will start an escort quest|r"] = "|cRXP_WARN_Das startet eine Eskortquest|r",
        ["|cRXP_WARN_Try to kite him to Ratchet to guards who will help, but make sure to deal at least {A}% damage!|r"] = "|cRXP_WARN_Locke ihn zu den Wachen in Ratschet, damit sie dir helfen. Verursache selbst mindestens {A} % des Schadens!|r",
        ["|cRXP_WARN_Type /sit at the campfire next to Eleanor Shackleton and wait for one minute until you get the \"Camp Benefits\" buff|r"] = "|cRXP_WARN_Gib am Lagerfeuer neben Eleanor Shackleton /sit ein und warte eine Minute auf den Lagerfeuer-Stärkungseffekt|r",
        ["|cRXP_WARN_Use the {A}{B} to start the quest|r"] = "|cRXP_WARN_Benutze {A}{B}, um die Quest zu starten|r",
        ["|cRXP_WARN_Use the|r {A}{B} |cRXP_WARN_at the Shrine of Remulos|r"] = "|cRXP_WARN_Benutze|r {A}{B} |cRXP_WARN_am Schrein von Remulos|r",
        ["|cRXP_WARN_Use the|r {C} |cRXP_WARN_on|r {B}|cRXP_WARN_'s body to bring him back|r"] = "|cRXP_WARN_Benutze|r {C} |cRXP_WARN_am Leichnam von|r {B}, |cRXP_WARN_um ihn wiederzubeleben|r",
        ["|cRXP_WARN_Use your|r {B}{C} |cRXP_WARN_on a|r {A} |cRXP_WARN_at max range|r."] = "|cRXP_WARN_Benutze|r {B}{C} |cRXP_WARN_aus maximaler Reichweite auf|r {A}.",
        ["|cRXP_WARN_Use your|r {B}{C} |cRXP_WARN_on an|r {A} |cRXP_WARN_at max range|r."] = "|cRXP_WARN_Benutze|r {B}{C} |cRXP_WARN_aus maximaler Reichweite auf|r {A}.",
        ["|cRXP_WARN_Use your|r {B}{C} |cRXP_WARN_to get buffs. Save at least {D} of them for later|r"] = "|cRXP_WARN_Benutze|r {B}{C} |cRXP_WARN_für Stärkungszauber. Heb mindestens {D} davon für später auf|r",
        ["|cRXP_WARN_Use|r {A}{B} |cRXP_WARN_at the Summoning Circle|r"] = "|cRXP_WARN_Benutze|r {A}{B} |cRXP_WARN_am Beschwörungskreis|r",
        ["|cRXP_WARN_Use|r {A}{D} |cRXP_WARN_to reduce his HP to half. Use|r {B}{E} |cRXP_WARN_to restore energy and use|r {C}{F}"] = "|cRXP_WARN_Benutze|r {A}{D}|cRXP_WARN_, um seine Gesundheit zu halbieren. Stell mit|r {B}{E} |cRXP_WARN_deine Energie wieder her und benutze|r {C}{F}",
        ["|cRXP_WARN_Vendor trash|r."] = "|cRXP_WARN_Verkaufe Trödel|r.",
        ["|cRXP_WARN_Wait for the RP to finish|r"] = "|cRXP_WARN_Warte, bis die Szene vorbei ist|r",
        ["|cRXP_WARN_Wait out the RP|r"] = "|cRXP_WARN_Warte, bis die Szene vorbei ist|r",
        ["|cRXP_WARN_When equipping bags, make sure your Reagent Bag is in the dedicated Reagent Bag slot|r."] = "|cRXP_WARN_Achte darauf, dass die Reagenzientasche im dafür vorgesehenen Taschenplatz ausgerüstet ist|r.",
        ["|cRXP_WARN_When you clear the building, run toward the Balcony. When |cRXP_ENEMY_Duriel Moonfire|r comes, let {A} and his {B} take aggro before you deal damage|r"] = "|cRXP_WARN_Lauf zum Balkon, sobald das Gebäude frei ist. Wenn |cRXP_ENEMY_Duriel Moonfire|r |cRXP_WARN_auftaucht, lass {A} und seinen Begleiter {B} zuerst die Aufmerksamkeit auf sich ziehen. Greif erst dann an|r",
        ["|cRXP_WARN_You are on a timed quest, don't go afk. It will get turned {A}-{B} minutes after pick-up|r"] = "|cRXP_WARN_Diese Quest hat ein Zeitlimit. Bleib am Rechner. Die Abgabe ist {A}–{B} Minuten nach der Annahme geplant|r",
        ["|cRXP_WARN_You can let|r {A} |cRXP_WARN_get some aggro before fighting him|r"] = "|cRXP_WARN_Lass zuerst|r {A} |cRXP_WARN_den Gegner auf sich ziehen. Greif erst dann ein|r",
        ["|cRXP_WARN_You don't actually need to assist |cRXP_FRIENDLY_Walton|r, he will survive with the help of|r {A}"] = "|cRXP_WARN_Du brauchst |cRXP_FRIENDLY_Walton|r |cRXP_WARN_nicht zu helfen. Er überlebt mit Hilfe von|r {A}",
        ["|cRXP_WARN_You turn it in to High Priestess Laurena when you get to Stormwind|r"] = "|cRXP_WARN_Gib die Quest in Sturmwind bei Hohepriesterin Laurena ab|r",
