        ["Done! Put the {A} on your action bars. It lights up the area around you for {B} minutes and goes out when you fight, swim or enter a capital city. If you ever delete it, you can come back for another."] = "Geschafft! Zieh {A} in deine Aktionsleiste. Sie leuchtet {B} Minuten und erlischt im Kampf, beim Schwimmen und beim Betreten einer Hauptstadt. Wenn du sie löschst, kannst du dir hier eine neue holen.",
