        ["Get to Aerie Peak in The Hinterlands: Use your Hearthstone to go back to Astranaar, then fly to Auberdine, then take the boat from Auberdine to Menethil Harbor, then fly to Southshore, then ride to Aerie Peak"] = "Reise zum Nistgipfel im Hinterland. Nutze den Ruhestein nach Astranaar. Fliege nach Auberdine. Nimm das Schiff (Auberdine → Hafen von Menethil). Fliege nach Süderstade. Reite zum Nistgipfel",
        ["Get to Astranaar in Ashenvale: Use your Hearthstone to go back to Astranaar"] = "Reise nach Astranaar im Eschental. Nutze den Ruhestein nach Astranaar",
        ["Get to Badlands: Fly to Thelsamar, then ride to the Badlands"] = "Reise ins Ödland. Fliege nach Thelsamar. Reite ins Ödland",
        ["Get to Badlands: Take the boat from Theramore to Menethil Harbor, then fly to Thelsamar, then ride to the Badlands"] = "Reise ins Ödland. Nimm das Schiff (Theramore → Hafen von Menethil). Fliege nach Thelsamar. Reite ins Ödland",
        ["Get to Blasted Lands: Ride to the Blasted Lands"] = "Reite in die Verwüsteten Lande",
        ["Get to Bloodvenom Post in Felwood: Use your Hearthstone to go back to Freewind Post, then fly to Bloodvenom Post"] = "Kehre per Ruhestein zum Freiwindposten zurück und flieg zum Blutgiftposten im Teufelswald",
        ["Get to Bloodvenom Post in Felwood: Use your Hearthstone to go back to Freewind Post, then fly to Zoram'gar Outpost, then ride to Bloodvenom Post"] = "Kehre per Ruhestein zum Freiwindposten zurück, flieg zum Außenposten von Zoram’gar und reite zum Blutgiftposten im Teufelswald",
        ["Get to Booty Bay in Stranglethorn Vale: Fly to Theramore, then ride to Ratchet, then take the boat from Ratchet to Booty Bay"] = "Reise nach Beutebucht im Schlingendorntal. Fliege nach Theramore. Reite nach Ratschet. Nimm das Schiff (Ratschet → Beutebucht)",
        ["Get to Booty Bay in Stranglethorn Vale: Use your Hearthstone to go back to Astranaar, then fly to Auberdine, then take the boat from Auberdine to Stormwind Harbor, then fly to Booty Bay"] = "Reise nach Beutebucht im Schlingendorntal. Nutze den Ruhestein nach Astranaar. Fliege nach Auberdine. Nimm das Schiff (Auberdine → Hafen von Sturmwind). Fliege nach Beutebucht",
        ["Get to Booty Bay in Stranglethorn Vale: Use your Hearthstone to go back to Freewind Post, then fly to Ratchet, then take the boat from Ratchet to Booty Bay"] = "Kehre per Ruhestein zum Freiwindposten zurück, flieg nach Ratschet und nimm das Schiff nach Beutebucht im Schlingendorntal",
        ["Get to Brackenwall Village in Dustwallow Marsh: Fly to Brackenwall Village"] = "Flieg nach Brackenwall in den Düstermarschen",
        ["Get to Brackenwall Village in Dustwallow Marsh: Use your Hearthstone to go back to Freewind Post, then fly to Camp Taurajo, then ride to Brackenwall Village"] = "Kehre per Ruhestein zum Freiwindposten zurück, flieg zum Lager Taurajo und reite nach Brackenwall in den Düstermarschen",
        ["Get to Camp Mojache in Feralas: Use your Hearthstone to go back to Freewind Post, then fly to Camp Mojache"] = "Kehre per Ruhestein zum Freiwindposten zurück und flieg zum Camp Mojache in Feralas",
        ["Get to Camp Mojache in Feralas: Use your Hearthstone to go back to Freewind Post, then ride to Camp Mojache"] = "Kehre per Ruhestein zum Freiwindposten zurück und reite zum Camp Mojache in Feralas",
        ["Get to Cenarion Hold in Silithus: Fly to Cenarion Hold"] = "Flieg zur Burg Cenarius in Silithus",
        ["Get to Cenarion Hold in Silithus: Fly to Marshal's Refuge, then ride to Cenarion Hold"] = "Flieg zu Marshals Zuflucht und reite zur Burg Cenarius in Silithus",
        ["Get to Cenarion Hold in Silithus: Ride back to Rut'theran Village, then fly to Marshal's Refuge, then ride to Cenarion Hold"] = "Reise zur Burg Cenarius in Silithus. Reite zurück nach Rut'theran. Fliege zu Marschalls Zuflucht. Reite zur Burg Cenarius",
        ["Get to Cenarion Hold in Silithus: Use your Hearthstone to go back to Astranaar, then fly to Cenarion Hold"] = "Reise zur Burg Cenarius in Silithus. Nutze den Ruhestein nach Astranaar. Fliege zur Burg Cenarius",
        ["Get to Chillwind Camp in Western Plaguelands: Fly to Southshore, then ride north through the Alterac Mountains to Chillwind Camp"] = "Reise zum Zugwindlager in den Westlichen Pestländern. Fliege nach Süderstade und reite nach Norden durch das Alteracgebirge",
        ["Get to Chillwind Camp in Western Plaguelands: Use your Hearthstone to go back to Astranaar, then fly to Auberdine, then take the boat from Auberdine to Menethil Harbor, then fly to Chillwind Camp"] = "Reise zum Zugwindlager in den Westliche Pestländern. Nutze den Ruhestein nach Astranaar. Fliege nach Auberdine. Nimm das Schiff (Auberdine → Hafen von Menethil). Fliege zum Zugwindlager",
        ["Get to Darkshire in Duskwood: Fly to Darkshire"] = "Reise nach Dunkelhain im Dämmerwald. Fliege nach Dunkelhain",
        ["Get to Darkshire in Duskwood: Fly to Darkshire (or ride south from Goldshire)"] = "Reise nach Dunkelhain im Dämmerwald. Fliege nach Dunkelhain oder reite von Goldhain nach Süden",
        ["Get to Darkshire in Duskwood: Fly to Lakeshire, then ride to Darkshire"] = "Reise nach Dunkelhain im Dämmerwald. Fliege nach Seenhain. Reite nach Dunkelhain",
        ["Get to Darnassus: Use your Hearthstone to go back to Astranaar, then fly to Rut'theran Village, then ride to Darnassus"] = "Reise nach Darnassus. Nutze den Ruhestein nach Astranaar, fliege nach Rut'theran und reite weiter nach Darnassus",
        ["Get to Duskwood: Take the zeppelin from Orgrimmar to Grom'gol, then ride north through Stranglethorn Vale into Duskwood. Stay off the roads near Darkshire, its guards attack Horde"] = "Reise in den Dämmerwald. Nimm den Zeppelin von Orgrimmar nach Grom'gol und reite dann nach Norden durch das Schlingendorntal in den Dämmerwald. Meide die Straßen bei Dunkelhain. Die Wachen greifen Hordenspieler an",
        ["Get to Everlook in Winterspring: Fly to Bloodvenom Post, then ride north through Timbermaw Hold to Everlook"] = "Flieg zum Blutgiftposten und reite nach Norden durch die Holzschlundfeste bis zur Ewigen Warte in Winterquell",
        ["Get to Everlook in Winterspring: Use your Hearthstone to go back to Astranaar, then fly to Everlook"] = "Reise zur Ewigen Warte in Winterquell. Nutze den Ruhestein nach Astranaar. Fliege zur Ewigen Warte",
        ["Get to Everlook in Winterspring: Use your Hearthstone to go back to Astranaar, then fly to Talonbranch Glade, then ride north through Timbermaw Hold to Everlook"] = "Reise zur Ewigen Warte in Winterquell. Nutze den Ruhestein nach Astranaar, fliege zur Krallenastlichtung und reite nach Norden durch die Holzschlundfeste",
        ["Get to Everlook in Winterspring: Use your Hearthstone to go back to Freewind Post, then fly to Everlook"] = "Kehre per Ruhestein zum Freiwindposten zurück und flieg zur Ewigen Warte in Winterquell",
        ["Get to Feathermoon Stronghold in Feralas: Fly to Feathermoon"] = "Reise zur Mondfederfeste in Feralas. Fliege zur Mondfederfeste",
        ["Get to Feathermoon Stronghold in Feralas: Use your Hearthstone to go back to Astranaar, then fly to Feathermoon"] = "Reise zur Mondfederfeste in Feralas. Nutze den Ruhestein nach Astranaar. Fliege zur Mondfederfeste",
        ["Get to Feathermoon Stronghold in Feralas: Use your Hearthstone to go back to Astranaar, then fly to Nijel's Point, then ride to the Forgotten Coast and take the boat to Feathermoon Stronghold"] = "Reise zur Mondfederfeste in Feralas. Nutze den Ruhestein nach Astranaar, fliege zu Nijels Spitze und reite zur Vergessenen Küste. Nimm dort das Schiff zur Mondfederfeste",
        ["Get to Freewind Post in Thousand Needles: Fly to Undercity, then take the zeppelin from Undercity to Orgrimmar, then fly to Camp Taurajo, then ride to Freewind Post"] = "Flieg nach Unterstadt. Nimm den Zeppelin nach Orgrimmar, flieg zum Lager Taurajo und reite zum Freiwindposten in Tausend Nadeln.",
        ["Get to Freewind Post in Thousand Needles: Use your Hearthstone to go back to Freewind Post"] = "Benutze den Ruhestein, um zum Freiwindposten in Tausend Nadeln zurückzukehren",
        ["Get to Gadgetzan in Tanaris: Fly to Gadgetzan"] = "Reise nach Gadgetzan in Tanaris. Fliege nach Gadgetzan",
        ["Get to Gadgetzan in Tanaris: Fly to Menethil Harbor, then take the boat from Menethil Harbor to Theramore, then fly to Gadgetzan"] = "Reise nach Gadgetzan in Tanaris. Fliege zum Hafen von Menethil. Nimm das Schiff (Hafen von Menethil → Theramore). Fliege nach Gadgetzan",
        ["Get to Gadgetzan in Tanaris: Fly to Theramore, then ride south through Thousand Needles to Gadgetzan"] = "Reise nach Gadgetzan in Tanaris. Fliege nach Theramore und reite nach Süden durch Tausend Nadeln nach Gadgetzan",
        ["Get to Gadgetzan in Tanaris: Use your Hearthstone to go back to Freewind Post, then fly to Gadgetzan"] = "Kehre per Ruhestein zum Freiwindposten zurück und flieg nach Gadgetzan in Tanaris",
        ["Get to Gadgetzan in Tanaris: Use your Hearthstone to go back to Freewind Post, then ride to Gadgetzan"] = "Kehre per Ruhestein zum Freiwindposten zurück und reite nach Gadgetzan in Tanaris",
        ["Get to Grom'gol in Stranglethorn Vale: Fly to Grom'gol"] = "Flieg zum Basislager von Grom'gol im Schlingendorntal",
        ["Get to Grom'gol in Stranglethorn Vale: Fly to Orgrimmar, then take the zeppelin from Orgrimmar to Grom'gol"] = "Flieg nach Orgrimmar und nimm den Zeppelin zum Basislager von Grom'gol im Schlingendorntal",
        ["Get to Grom'gol in Stranglethorn Vale: Take the zeppelin from Undercity to Grom'gol"] = "Nimm den Zeppelin von Unterstadt nach Grom'gol im Schlingendorntal",
        ["Get to Grom'gol in Stranglethorn Vale: Use your Hearthstone to go back to Freewind Post, then fly to Orgrimmar, then take the zeppelin from Orgrimmar to Grom'gol"] = "Kehre per Ruhestein zum Freiwindposten zurück, flieg nach Orgrimmar und nimm den Zeppelin nach Grom'gol im Schlingendorntal",
